/*
 * テキストの本文(社会:中学地理・歴史・公民/日本史探究・世界史探究・公共/政治経済)。このアプリのオリジナル。
 * 書式は lessons_1.js と同じ(+ pre / key / hint / check / faq / next)。【 】でかこんだ語は太字で表示する。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 中学地理 =====
  L.c_m1 = {
    goal: '緯度・経度で場所を表し、時差を計算できるようになり、世界の気候と各地域の特色を理由とセットで説明できるようになる。',
    intro: '地球は1日(24時間)で1回転しています。だから、日本が昼のとき、地球の反対側は夜です。この「場所によって時刻がちがう」しくみを数字で表したのが【時差】です。世界地理は、まず「地球上の住所」である緯度・経度を知り、そこから気候、さらに人々の暮らしや産業へとつなげていくと、ばらばらの暗記ではなくなります。',
    pre: '地球は、ほぼ球の形をしています。球の表面にある場所を表すには、ふつうの地図の「たて・よこ」の代わりに、【角度】を使います。角度は、1回転を360度とする数え方です。\n地球は、北極と南極を結ぶ線(地軸)を中心に、1日に1回、西から東へ回っています(自転)。太陽は東からのぼって西にしずむように見えますが、これは地球が西から東へ回っているからです。\n方位は、北・南・東・西の4つが基本です。地図では、とくに書いていなければ上が北です。\n時刻は、0時から24時までの24時間で1日です。「午後3時」は「15時」と同じです。時差の計算では、24時間制に直してから計算するとまちがえにくくなります。',
    secs: [
      { h: '緯度・経度は地球の住所', t: '地球上の場所をだれにでも同じように伝えるために、地球に見えない線を引いて、その角度で場所を表します。これが緯度と経度です。\n【緯度】は、地球の真ん中を東西にぐるりと回る【赤道】を0度として、北と南にそれぞれ90度まで測ります。北半球は北緯、南半球は南緯です。北極点は北緯90度、南極点は南緯90度です。\n同じ緯度を結んだ線を【緯線】といいます。緯線は赤道と平行な輪で、北極や南極に近づくほど輪が小さくなります。\n【経度】は、イギリスのロンドン(旧グリニッジ天文台)を通る【本初子午線】を0度として、東と西にそれぞれ180度まで測ります。東側が東経、西側が西経です。東経180度と西経180度は同じ線です。\n北極と南極を結ぶ同じ経度の線を【経線】(子午線)といいます。\n住所を言うときは「北緯35度・東経135度」のように、緯度と経度をセットで言います。これで地球上の1点が決まります。',
        key: '緯度は赤道が0度(南北に90度まで)、経度はロンドンを通る本初子午線が0度(東西に180度まで)。',
        ex: [{ q: '北緯35度・東経135度の地点の、地球のちょうど反対側(真裏)にあたる地点の緯度・経度は?', hint: '緯度は北と南を入れかえ、経度は180度から引いて東と西を入れかえます。', steps: ['真裏は、地球の中心をはさんで反対側にある。だから北半球の地点の真裏は南半球になり、緯度の数字はそのまま、北緯が南緯に変わる → 南緯35度。', '経度は、ぐるりと半周(180度)回った先になる。東経135度から180度回ると、180−135=45 で、45度の地点になる。', '東経の真裏は西経になるので、西経45度。'], a: '南緯35度・西経45度', check: '経度の数字を足すと 135+45=180 になれば、半周はなれていることが確かめられます。' }] },
      { h: '時差は「15度で1時間」', t: 'なぜ場所によって時刻がちがうのでしょうか。地球が西から東へ回っているので、東にある場所ほど先に太陽がのぼり、先に昼になるからです。\n地球は24時間で360度回るので、360÷24=【15度】回ると1時間たちます。だから、経度が15度ちがうと時刻が1時間ずれます。\n各国は、時刻の基準にする経線(【標準時子午線】)を決めています。日本の標準時は、兵庫県明石市を通る【東経135度】の経線で決めています。\n東へ行くほど太陽が早くのぼるので、時刻は【東ほど進んでいる】、西ほど遅れている、と考えます。\n計算の手順:①2地点の経度の差を出す(東経どうし・西経どうしは引き算、東経と西経なら足し算)。②15でわって時差を出す。③西にある地点なら時差を引き、東にある地点なら足す。\n日付は、ほぼ180度の経線にそって引かれた【日付変更線】で変わります。',
        key: '経度15度で1時間。東ほど時刻が進み、西ほど遅れている。',
        ex: [
          { q: '日本(東経135度)が1月10日午後3時のとき、ロンドン(経度0度)は何日の何時?', hint: 'まず経度の差を出し、15でわります。', steps: ['経度の差:135−0=135度。', '時差:135÷15=9時間。15でわるのは、15度で1時間ずれるから。', 'ロンドンは日本より西にあるので、9時間遅れている。', '午後3時を24時間制に直すと15時。15時−9時間=6時。'], a: '1月10日午前6時', check: '逆にロンドンの午前6時に9時間足すと15時(午後3時)にもどります。' },
          { q: '日本(東経135度)が1月1日午前10時のとき、ニューヨーク(西経75度)は何日の何時?', hint: '東経と西経の地点は、本初子午線をはさむので経度を足します。', steps: ['東経と西経なので、0度をはさんだ両側にある。だから足す:135+75=210度。', '時差:210÷15=14時間。', 'ニューヨークは日本の西側なので14時間遅れている。', '10時−14時間=−4時。0時より前になったので前の日にもどり、24−4=20時。'], a: '12月31日午後8時', check: '12月31日20時に14時間足すと、1月1日10時になります。' }
        ] },
      { h: '6つの大陸・3つの大洋と6つの州', t: '地球の表面は、約7割が海、約3割が陸です。広い陸地を【大陸】、広い海を【大洋】といいます。\n大陸は6つです。面積の大きい順に、ユーラシア大陸・アフリカ大陸・北アメリカ大陸・南アメリカ大陸・南極大陸・オーストラリア大陸です。\n大洋は3つで、【太平洋】(最も広い)・大西洋・インド洋です。\n世界の国々は、アジア州・ヨーロッパ州・アフリカ州・北アメリカ州・南アメリカ州・オセアニア州の【6つの州】に分けて学びます。大陸と州は同じではありません。たとえばユーラシア大陸は、アジア州とヨーロッパ州の2つにまたがっています。\n世界には190余りの国があります。面積が最も大きい国はロシア、2番目はカナダです。最も小さい国は、イタリアのローマ市内にあるバチカン市国です。\nまわりを海に囲まれた国を【島国】(日本・イギリスなど)、海にまったく面していない国を【内陸国】(モンゴル・スイスなど)といいます。' },
      { h: '世界の気候は5つに分けられる', t: 'なぜ地域によって暑さや雨の量がちがうのでしょうか。大きな理由は、赤道に近いほど太陽の光が真上近くから当たって暑く、極に近いほどななめに当たって寒いからです。これに、海からの距離や風、山の高さが加わります。\n世界の気候は、気温と降水量によって大きく5つに分けられます。\n【熱帯】…赤道付近。1年中暑い。1年中雨が多い熱帯雨林気候と、雨季と乾季があるサバナ気候がある。\n【乾燥帯】…雨が少ない。草木がほとんどない砂漠と、短い草が生えるステップがある。\n【温帯】…四季がある。日本の大部分もここ。西ヨーロッパは、暖流(北大西洋海流)の上をわたってくる【偏西風】のおかげで、高緯度のわりに冬が温暖(西岸海洋性気候)。地中海沿岸は夏に乾燥する(地中海性気候)。\n【冷帯(亜寒帯)】…冬の寒さがきびしく、夏は気温が上がる。針葉樹林(タイガ)が広がる。北半球にだけある。\n【寒帯】…1年中寒い。夏の短い間だけこけ類が育つツンドラや、氷雪の世界。\nこのほか、アンデス山脈などの標高の高い地域は、緯度のわりに気温が低い【高山気候】になります。',
        key: '気候は熱帯・乾燥帯・温帯・冷帯・寒帯の5つ。決め手は「緯度(太陽の当たり方)」と「海・風・山」。',
        ex: [{ q: 'ある都市の気候グラフでは、1年中、月の平均気温が25度以上あり、どの月も降水量が多い。この都市の気候帯と、そこで見られる植物のようすは?', hint: '「1年中暑い」に当てはまるのは5つのうちどれかを考えます。', steps: ['1年中気温が高いのは、赤道付近の熱帯。', '熱帯には、1年中雨が多い熱帯雨林気候と、雨季・乾季がある気候がある。', 'どの月も降水量が多いので、1年中雨が多い熱帯雨林気候と分かる。', '高温で雨が多いと植物がよく育つので、背の高い木がしげる密林(熱帯雨林)になる。'], a: '熱帯(熱帯雨林気候)。背の高い常緑の木がしげる熱帯雨林が見られる。', check: '「乾季がある」と書かれていればサバナ気候になる、と条件を入れかえて確かめましょう。' }] },
      { h: '世界の人々の暮らしと宗教', t: '人々の暮らし(衣・食・住)は、その土地の気候と深く結びついています。手に入る材料や、暑さ・寒さへの対策がちがうからです。\n住まいの例:熱帯の東南アジアでは、湿気や浸水を防ぐために床を高くした【高床の住居】があります。乾燥帯では、木が少ないので土を固めた【日干しれんが】の家が多くなります。モンゴルの遊牧民は、組み立てて運べる【ゲル】に住みます。シベリアでは、建物の熱で地面の氷(永久凍土)がとけて家がかたむかないように、高床にした建物があります。\n世界には多くの宗教があり、とくに信者が多い【キリスト教・イスラム教・仏教】を三大宗教といいます。\n【キリスト教】…ヨーロッパや南北アメリカに多い。日曜日に教会で礼拝する人が多い。\n【イスラム教】…西アジア・北アフリカ・東南アジアのインドネシアなどに多い。1日5回、聖地メッカの方向に礼拝する。豚肉を食べず、酒を飲まない。断食の月(ラマダン)がある。\n【仏教】…東南アジアや東アジアに多い。インドでは、インドで生まれた【ヒンドゥー教】の信者が最も多く、牛を神聖なものとして食べない人が多い。\n宗教のきまりは食事や服装にも表れるので、たがいの文化を知って尊重することが大切です。' },
      { h: 'アジア・ヨーロッパ・アフリカ:自然 → 産業 → 課題', t: '各地域は、「どんな自然か → だから何がさかんか → どんな課題があるか」の順に整理すると、理由ごと覚えられます。\n【アジア】…季節によって向きが変わる風【季節風(モンスーン)】が海から雨を運ぶので、東アジア・東南アジア・南アジアでは稲作がさかん。中国は沿岸部に外国の企業をまねく【経済特区】をつくって工業化が進み、「世界の工場」とよばれるようになった。インドは英語を話せる人が多く、【ICT(情報通信技術)産業】がのびている。東南アジアの国々は【ASEAN(東南アジア諸国連合)】で協力している。西アジアのペルシア湾岸は石油の大産地。\n【ヨーロッパ】…多くの国が【EU(ヨーロッパ連合)】に加わり、国境での検査をなくし、共通通貨【ユーロ】を使う国も多い。小さな国どうしがまとまることで、アメリカなどの大国に対抗しようとした。課題は、加盟国の間の経済格差。\n【アフリカ】…かつてヨーロッパの国々の植民地だったため、経線・緯線にそった直線の国境が多い。民族の分布と関係なく線が引かれたことが、紛争の原因の一つになった。\nアフリカには、特定の農産物や鉱産資源の輸出にたよる【モノカルチャー経済】の国が多い。カカオや銅などの値段は世界の市場で大きく上下するので、国の収入が安定しにくい。',
        key: 'モノカルチャー経済は、1つの品目の値段が下がると国全体の収入が大きく減るので、経済が不安定になりやすい。',
        ex: [{ q: 'ある国の輸出の約7割が銅である。この国の経済にはどんな弱点がある?', hint: '銅の値段が下がったら、国の収入はどうなるかを考えます。', steps: ['輸出の大部分を1つの品目にたよる経済を、モノカルチャー経済という。', '銅などの資源の値段は、世界全体の需要などで大きく上下する。', '銅の値段が下がると、輸出で得るお金の約7割が一度に減ってしまう。', 'だから国の収入が不安定になり、計画的に学校や道路をつくることもむずかしくなる。'], a: '輸出が銅にかたよったモノカルチャー経済なので、銅の価格が下がると国の収入が大きく減り、経済が不安定になりやすい。', check: '「いろいろな品目を輸出している国なら、1つの値下がりの影響は小さい」と比べて考えると、弱点が確かめられます。' }] },
      { h: '南北アメリカ・オセアニア:自然 → 産業 → 課題', t: '【北アメリカ】…アメリカ合衆国は、広い土地で、気温や降水量に合った作物を大規模に育てる【適地適作】を行い、「世界の食料庫」とよばれる。大型機械を使うので、少ない人数で大量に生産できる。\n工業では、北緯37度より南の温暖な地域【サンベルト】で、コンピューターなどの先端技術産業が発達した。サンフランシスコ近郊には、ICT企業が集まる【シリコンバレー】がある。\nアメリカには、メキシコなどスペイン語を話す国から移り住んだ【ヒスパニック】の人々も多く、多様な民族が暮らしている。\n【南アメリカ】…赤道付近を流れるアマゾン川の流域には、世界最大級の熱帯林が広がる。しかし、牧場や畑をつくるための開発で、熱帯林の減少が進んでいることが課題。ブラジルはさとうきびから、自動車の燃料にもなる【バイオエタノール】をつくる。\n【オセアニア】…オーストラリアは鉄鉱石・石炭などの鉱産資源が豊富で、日本は多くを輸入している。羊や牛の放牧もさかん。\nオーストラリアはかつて、ヨーロッパ系以外の移民を制限する【白豪主義】をとっていたが、これをやめ、今はアジアの国々との結びつきを強め、さまざまな文化を認め合う多文化社会をめざしている。',
        ex: [{ q: 'アメリカ合衆国の農業が「適地適作」とよばれるのはなぜ?また、それができる理由を説明しよう。', hint: '「適地」=その作物に合った土地、という意味から考えます。', steps: ['適地適作とは、その土地の気温や降水量に合った作物を選んで育てること。', 'アメリカは国土が広く、北と南、東と西で気候が大きくちがう。', 'そのため、地域ごとに小麦・とうもろこし・綿花などを分けて大規模に育てられる。', '大型機械を使って少ない人数で広い畑を耕すので、大量に生産でき、世界に輸出している。'], a: '土地の気候に合った作物を地域ごとに分けて育てているから。国土が広く地域ごとに気候がちがうので、それぞれに合った作物を大型機械で大規模に生産できる。' }] }
    ],
    faq: [
      ['なぜ経度0度はロンドンなの?', '19世紀後半に、世界の国々が集まった国際会議で、イギリスのグリニッジ天文台を通る経線を経度0度にすると決めたからです。\n当時のイギリスは海運の中心で、グリニッジを基準にした海図がすでに広く使われていました。'],
      ['東ほど時刻が進んでいるのはなぜ?', '地球は西から東へ回っているので、東にある場所ほど先に太陽がのぼります。\nたとえば日本はロンドンより東にあるので、日本のほうが先に朝をむかえます。だから日本の時刻のほうが「進んでいる」のです。'],
      ['日付変更線をこえると、日付はどう変わるの?', '西から東へ(たとえば日本からハワイへ)こえると、日付を1日もどします。東から西へこえると、1日進めます。\nただし、ふつうの時差の問題は、経度の差から時差を出して足し引きすれば、日付も自然に正しく出せます。']
    ],
    terms: [['本初子午線', 'ロンドンを通る経度0度の経線'], ['標準時子午線', 'その国の時刻の基準にする経線。日本は東経135度'], ['日付変更線', 'ほぼ180度の経線にそって引かれ、ここを越えると日付が変わる線'], ['偏西風', '中緯度の上空を、1年中西から東へふく風'], ['季節風(モンスーン)', '夏と冬で向きが変わる風。夏は海から雨を運ぶ'], ['モノカルチャー経済', '特定の農産物や鉱産資源の生産・輸出にたよる経済'], ['適地適作', '土地の気候や土に合った作物を選んで育てること']],
    miss: ['西にある国の時刻を「進んでいる」と考えてしまう。地球は西から東へ回るので、東ほど進み、西ほど遅れている、と理由ごと覚えておく。', '東経と西経の地点の時差で、経度を足さずに引いてしまう。本初子午線(0度)をはさむときは足す、と図をかいて確かめる。', '時刻が0時をまたぐのに、日付を変え忘れる。答えを出したら、マイナスや24をこえていないかを必ず見直す。', '大陸と州を同じものだと思う。ユーラシア大陸はアジア州とヨーロッパ州にまたがる、という例で区別する。'],
    sum: ['緯度は赤道が0度、経度はロンドンが0度。', '経度15度で1時間の時差。東ほど時刻が進んでいる。', '6大陸・3大洋・6州。最も広い海は太平洋。', '気候は熱帯・乾燥帯・温帯・冷帯・寒帯の5つ。暮らしは気候と結びつく。', '各地域は「自然 → 産業 → 課題」の順に、理由をつけて覚える。'],
    next: '次は「日本の地理(c_jgeo)」へ進みましょう。ここで学んだ緯度・経度や季節風の考え方を、日本の地形や気候の説明にそのまま使います。'
  };

  L.c_jgeo = {
    goal: '日本の位置と領域、地形と気候の特色を理由とともに説明でき、各地方の産業の特色を整理できるようになる。',
    intro: '日本は南北に長く、山が多く、まわりを海に囲まれた国です。この3つの特徴だけで、「なぜ日本海側は冬に雪が多いのか」「なぜ扇状地に果樹園が多いのか」など、たくさんのことが説明できます。地名は、白地図に書きこみながら場所とセットで覚えると忘れにくくなります。',
    pre: '緯度は赤道からの南北の位置、経度はロンドンを0度とした東西の位置を表す角度です。日本はおよそ北緯20〜46度、東経122〜154度にあります。\n【季節風(モンスーン)】は、季節によって向きが変わる風です。日本では、冬は大陸から北西の風、夏は太平洋から南東の風がふきます。\n地形のことば:【平野】は海に面した低く平らな土地、【盆地】は山に囲まれた平らな土地、【台地】はまわりより一段高い平らな土地、【山地】は山が集まったところです。\n【海里】は海の上の距離の単位で、1海里は約1852mです。',
    secs: [
      { h: '日本の位置と領域', t: '日本はユーラシア大陸の東にある島国で、北海道・本州・四国・九州の4つの大きな島と、多くの島々からなります。面積は約38万km²です。\n日本の端:北端は【択捉島】、南端は【沖ノ鳥島】、東端は【南鳥島】、西端は【与那国島】です。\n国の範囲(【領域】)は、陸地の【領土】、海岸線から12海里までの【領海】、領土と領海の上空の【領空】からなります。\n海岸線から200海里(約370km)までのうち領海を除く海を【排他的経済水域】といいます。ここでは、魚などの水産資源や、海底の鉱産資源を、沿岸の国が自分のものとして利用できます。ただし、ほかの国の船も自由に通ることができます。\n日本は島が多く、それぞれの島のまわりに水域ができるので、国土面積のわりに排他的経済水域がとても広い国です。沖ノ鳥島で護岸工事をしたのは、島が波でけずられて消え、広い水域を失わないようにするためです。\n領土をめぐる問題:【北方領土】(歯舞群島・色丹島・国後島・択捉島)はロシアが占拠しています。【竹島】(島根県)は韓国が不法に占拠しています。【尖閣諸島】(沖縄県)は日本が有効に支配していますが、中国などが領有を主張しています。',
        key: '領海は12海里、排他的経済水域は200海里まで。島が多い日本は、排他的経済水域がとても広い。',
        ex: [{ q: '排他的経済水域と領海のちがいを、「距離」と「できること」の2点で説明しよう。', hint: '12海里と200海里、それぞれの内側で何ができるかを比べます。', steps: ['距離:領海は海岸線から12海里まで。排他的経済水域は200海里までのうち、領海を除いた部分。', '領海はその国の領域の一部なので、その国の主権がおよぶ。', '排他的経済水域は領域ではないが、水産資源や鉱産資源を沿岸国が利用できる。', 'そのかわり、ほかの国の船や飛行機も自由に通ることができる。'], a: '領海は12海里までで、その国の領域(主権がおよぶ海)。排他的経済水域は200海里までで、資源を沿岸国が利用できるが、領域ではなく他国の船も自由に通れる。' }] },
      { h: '地形:山がちで、川は短く急', t: '日本は国土の約4分の3が山地です。日本列島は、地球の表面をおおう大きな岩の板(プレート)がぶつかり合う場所にあるため、山が高く、火山や地震が多いのです。\n山が海の近くまでせまっているので、日本の川は大陸の川に比べて短く、流れが急です。\n川が山から平地に出るところでは、流れが急にゆるやかになり、運ばれてきた土砂が扇の形に積もって【扇状地】ができます。つぶの大きい砂やれきでできていて水はけがよいので、【果樹園】に利用されることが多いです(例:山梨県の甲府盆地)。\n川が海に流れこむ河口には、細かい土砂が積もった【三角州】ができます。低く平らで水が得やすいので、水田や都市に利用されます(例:広島市)。\n海岸には、山地が海にしずんでできた、入り組んだ【リアス海岸】(例:三陸海岸・志摩半島)があります。湾の中は波がおだやかなので、かきやわかめなどの養殖業がさかんです。ただし湾の奥では津波が高くなりやすいという面もあります。',
        key: '扇状地(山のふもと・つぶが大きい・水はけがよい)は果樹園、三角州(河口・細かい土砂)は水田や都市。',
        ex: [{ q: '扇状地が水田より果樹園に利用されやすいのはなぜ?', hint: '扇状地の土のつぶの大きさと、水のしみこみやすさを考えます。', steps: ['扇状地は、川が山から出たところで、つぶの大きい砂やれきが積もってできる。', 'つぶが大きいとすき間が多く、水がしみこみやすい(水はけがよい)。', '水田は水をためる必要があるので向かない。水はけのよい土地は、根が水につかりすぎるのをきらう果樹の栽培に向く。'], a: '砂やれきでできていて水はけがよく、水をためる水田には向かないが、果樹の栽培には適しているから。' }] },
      { h: '気候:季節風と山地が決め手', t: '日本の大部分は温帯ですが、【季節風】と山地の位置の組み合わせで、地域ごとに気候がちがいます。\n【日本海側】…冬に北西の季節風が日本海の上で水分をふくみ、本州の中央の山地にぶつかって上昇し、大雪をふらせる。冬の降水量が多い。\n【太平洋側】…夏に南東の季節風がふき、夏の降水量が多い。冬は、山地をこえてきた乾いた風がふくので、晴れが多い。\n【中央高地(内陸)】…山に囲まれ、季節風がさえぎられるので降水量が少ない。海から遠いので、夏と冬の気温差が大きい。\n【瀬戸内】…北の中国山地と南の四国山地が、両方の季節風をさえぎるので、1年中降水量が少ない。水不足に備えて、ため池や用水路がつくられてきた。\n【北海道】…冬の寒さがきびしい冷帯。はっきりした梅雨がない。\n【南西諸島】…1年中温暖で降水量が多い。台風の通り道になりやすい。',
        key: '風が山地にぶつかる側は雨や雪が多く、山地にさえぎられた側は乾燥する。',
        ex: [
          { q: 'ある都市の雨温図では、12〜2月の降水量が1年でいちばん多い。この都市は日本のどの気候区に属すると考えられる?', hint: '冬に雨や雪をふらせる風はどちらからふくかを思い出します。', steps: ['冬に降水量(雪)が多いのはどこかを考える。', '冬の北西季節風が日本海で水分をふくみ、山地にぶつかって雪をふらせる。', 'それが起きるのは山地の手前の日本海側。'], a: '日本海側の気候', check: '太平洋側なら逆に冬は晴れて乾燥する、と比べると答えが確かめられます。' },
          { q: '瀬戸内の地域で、昔からため池が多くつくられてきたのはなぜ?', hint: '瀬戸内の北と南に何があるかを考えます。', steps: ['瀬戸内は、北を中国山地、南を四国山地にはさまれている。', '冬の北西の季節風は中国山地に、夏の南東の季節風は四国山地にさえぎられる。', 'そのため湿った風が届きにくく、1年を通して降水量が少ない。', '雨が少なく川の水も不足しやすいので、農業用の水をためておくため池がつくられた。'], a: '中国山地と四国山地が夏・冬の季節風をさえぎるため1年中降水量が少なく、水不足に備えて水をたくわえる必要があったから。' }
        ] },
      { h: '人口と自然災害', t: '日本の人口は約1億2千万人です。人口は東京・大阪・名古屋の【三大都市圏】に集中しています。\n人が集まりすぎて、交通渋滞や住宅不足などが起きる状態を【過密】といいます。反対に、若い人が都市に出て人口が減り、学校や病院、バスなどを保てなくなる状態を【過疎】といい、山間部や離島で深刻です。\n年齢別の人口をグラフにした【人口ピラミッド】を見ると、日本は子どもが少なく高齢者が多い「つぼ型」になっています。少子高齢化が進んでいるからです。\n日本はプレートの境目にあるため、【地震】や【津波】、火山の噴火が多く起きます。また、夏から秋には台風が来て、大雨による洪水や土砂くずれも起きます。\n災害に備えて、国や地方公共団体は、被害が予想される範囲や避難場所を示した【ハザードマップ(防災マップ)】をつくっています。自分の住む地域の危険を前もって知っておくことが大切です。' },
      { h: '日本の産業の特色', t: '日本は石油・石炭などの資源が少ないため、原料を輸入して製品をつくり、輸出する【加工貿易】で工業を発展させてきました。\n工業地帯・地域は、関東から九州北部までの海ぞいに帯のように連なっています。これを【太平洋ベルト】といいます。原料の輸入や製品の輸出に便利な港があり、人口も多く働く人を集めやすかったからです。\n1980年代ごろから、人件費の安いアジアなど海外に工場を移す企業がふえました。その結果、国内の工場が減って働く場が少なくなることを【産業の空洞化】といいます。\n農業は、山がちでせまい土地を工夫して使ってきました。米は全国でつくられますが、農家の高齢化やあとつぎ不足が課題です。外国から安い農産物が入るようになり、日本の【食料自給率】は先進国の中でも低くなっています。\n漁業は、各国が排他的経済水域を設定したことで、遠い海での漁業がしにくくなりました。そこで、育てる漁業(【養殖業】や栽培漁業)に力を入れています。' },
      { h: '各地方の特色(九州・中国・四国・近畿)', t: '各地方は、「自然条件 → だから何がさかんか」の順に覚えると、理由ごと説明できます。\n【九州】…南部には、火山の噴出物が積もった【シラス台地】が広がる。水もちが悪く稲作に向かないので、畜産(ぶた・肉牛・にわとり)や茶・さつまいもの栽培がさかん。北部は、かつて鉄鋼業で栄えた北九州工業地帯(地域)がある。\n宮崎平野などでは、冬でも暖かい気候を生かし、ビニールハウスでピーマンなどの出荷時期を早める【促成栽培】が行われる。\n【中国・四国】…瀬戸内海の沿岸には、石油化学工業などの【瀬戸内工業地域】がある。本州四国連絡橋で行き来が便利になった一方で、大都市に人が吸い寄せられるという面もある。高知平野では促成栽培、愛媛県ではみかんの栽培がさかん。\n【近畿】…大阪湾の沿岸に【阪神工業地帯】がある。中小企業の工場が多いのが特色。京都・奈良には古い都があったため、古い町なみや文化財が多く、観光客が多い。' },
      { h: '各地方の特色(中部・関東・東北・北海道)', t: '【中部】…愛知県を中心とする【中京工業地帯】は自動車などの輸送用機械が中心で、工業出荷額が全国最大。中央高地では、夏でもすずしい高原の気候を生かし、ほかの産地が出荷しにくい時期にレタスやキャベツをつくる【抑制栽培】(高原野菜)がさかん。北陸は冬の雪で農作業ができない間の副業から、伝統工芸や地場産業が発達した。\n【関東】…首都の東京を中心に人口と企業が集中する。大消費地に近い利点を生かし、新鮮な野菜などを出荷する【近郊農業】がさかん。京浜工業地帯や京葉工業地域がある。\n【東北】…夏に冷たくしめった北東の風【やませ】がふくと、太平洋側で日照不足と低温になり、稲が育たない【冷害】が起きやすい。それでも全体としては米の大産地で、りんご(青森)やさくらんぼ(山形)の栽培もさかん。\n【北海道】…冷帯で、広い土地を生かした大規模な農業が行われる。根釧台地などで【酪農】、石狩平野で稲作、十勝平野で畑作。もとは先住民族である【アイヌの人々】が暮らしていた土地で、地名にもアイヌ語に由来するものが多い。',
        ex: [{ q: '東北地方の太平洋側で、夏に冷害が起きやすいのはなぜ?', hint: '夏にふく、冷たくしめった風の名前を思い出します。', steps: ['夏に、北東から冷たくしめった風(やませ)がふくことがある。', 'やませは海の上を通ってくるので、霧や雲を生み、日光がさえぎられる。', 'その結果、気温が上がらず日照時間も短くなる。', '稲は夏の暑さと日光で育つので、育ちが悪くなり、収穫が減る(冷害)。'], a: '夏に冷たくしめった北東の風「やませ」がふくと、低温と日照不足になって稲が十分に育たないから。', check: 'やませは山地にさえぎられるので、日本海側では冷害が起きにくい、と比べると理由が確かめられます。' }] }
    ],
    faq: [
      ['促成栽培と抑制栽培のちがいは?', '促成栽培は、暖かい気候やビニールハウスで、出荷を「早める」栽培です(宮崎・高知など)。\n抑制栽培は、すずしい気候を生かして、出荷を「おくらせる」栽培です(長野などの高原野菜)。\nどちらも、ほかの産地が出荷しない時期に出して、高い値段で売るための工夫です。'],
      ['なぜ沖ノ鳥島のような小さな島が大切なの?', '島があると、そのまわり200海里までが排他的経済水域になるからです。\n沖ノ鳥島1つで、日本の国土面積(約38万km²)より広い水域が生まれます。そこで、島が波でけずられないように護岸工事をしています。'],
      ['過疎と過密は、どちらか一方だけの問題?', 'いいえ、同じ1つの動き(人が地方から都市へ移ること)の、表と裏です。\n都市では人が多すぎて過密になり、地方では人が少なすぎて過疎になります。だから、地方で働く場をつくることは、両方の解決につながります。']
    ],
    terms: [['排他的経済水域', '海岸線から200海里までのうち領海を除く、資源を沿岸国が利用できる水域'], ['扇状地', '川が山から平地に出るところに土砂が積もった、扇形の地形'], ['三角州', '河口付近に細かい土砂が積もってできた低く平らな地形'], ['季節風(モンスーン)', '夏と冬で向きが変わる風。日本では夏は南東、冬は北西からふく'], ['やませ', '東北地方の太平洋側に夏にふく、冷たくしめった北東の風'], ['太平洋ベルト', '関東から九州北部まで帯のように連なる、工業のさかんな地域'], ['近郊農業', '大都市の近くで、新鮮さを生かして野菜などを出荷する農業'], ['促成栽培', '暖かい気候などを生かし、出荷時期を早める栽培']],
    miss: ['扇状地と三角州の場所(山のふもとか、河口か)を逆に覚える。川が山を出て「ひろがる」のが扇状地、海に「出る」のが三角州、と川の流れにそって覚える。', '日本海側の雪の原因を「日本海側が寒いから」と答え、季節風と山地を書き忘れる。「風が海で水分をふくむ → 山にぶつかる」の2つを必ず書く。', '排他的経済水域を「領海」と混同する。排他的経済水域は領域ではなく、他国の船も通れる。', '促成栽培と抑制栽培を逆にする。「促」は「うながす=早める」、「抑」は「おさえる=おくらせる」と漢字の意味で覚える。'],
    sum: ['日本の端は択捉島・沖ノ鳥島・南鳥島・与那国島。領海12海里、排他的経済水域200海里。', '扇状地は果樹園、三角州は水田や都市。理由は水はけ。', '気候は季節風と山地の位置で説明する。', '資源が少ないので加工貿易。工業は太平洋ベルトに集中。', '各地方の産業は「自然条件 → だから何がさかんか」で覚える。'],
    next: '次は「地形図の読み方(c_chizu)」に進みましょう。扇状地や三角州が、地図の上で等高線や地図記号としてどう表れるかを確かめられます。'
  };

  var CONTOUR = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="等高線の間隔と土地の傾き"><ellipse cx="100" cy="55" rx="80" ry="45" class="cv"/><ellipse cx="90.5" cy="55" rx="64.5" ry="35" class="cv"/><ellipse cx="81" cy="55" rx="49" ry="25" class="cv"/><ellipse cx="71.5" cy="55" rx="33.5" ry="15" class="cv"/><circle cx="64" cy="55" r="3" class="pt"/><text x="70" y="59">山頂</text><text x="182" y="58">10</text><text x="157" y="58">20</text><text x="132" y="58">30</text><text x="107" y="58">40</text><text x="8" y="124">左:間隔がせまい→急な斜面</text><text x="8" y="140">右:間隔が広い→ゆるやかな斜面(m)</text></svg>';
  var SECTION = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="等高線から断面図をかく"><line x1="20" y1="30" x2="200" y2="30" class="ax"/><line x1="40" y1="20" x2="40" y2="40" class="cv"/><line x1="60" y1="20" x2="60" y2="40" class="cv"/><line x1="75" y1="20" x2="75" y2="40" class="cv"/><line x1="140" y1="20" x2="140" y2="40" class="cv"/><line x1="180" y1="20" x2="180" y2="40" class="cv"/><text x="22" y="15">地図上の線A-B(縦線が等高線)</text><line x1="20" y1="135" x2="200" y2="135" class="ax"/><polyline points="20,135 40,120 60,100 75,80 107,70 140,80 180,100 200,110" class="cv2"/><line x1="40" y1="40" x2="40" y2="120" class="dash"/><line x1="75" y1="40" x2="75" y2="80" class="dash"/><line x1="140" y1="40" x2="140" y2="80" class="dash"/><text x="22" y="62">急</text><text x="150" y="70">ゆるやか</text><text x="70" y="128">断面図(高さを点で結ぶ)</text></svg>';

  L.c_chizu = {
    goal: '地形図の縮尺から実際の距離や面積を計算し、等高線と地図記号から土地のようすを読み取れるようになる。',
    intro: '地形図は、本物の土地を小さく縮めて、決まった記号で表した「土地の設計図」です。縮尺が分かれば地図上の長さから実際の距離が出せ、等高線が読めれば山の高さや斜面の急さまで分かります。計算は「cm → m → km」の単位の直し方さえ気をつければむずかしくありません。',
    pre: '長さの単位の関係を確認しましょう。1m=100cm、1km=1000m です。だから 1km=1000×100=100000cm(0が5個)になります。\n面積の単位は、1m²=たて1m×よこ1m の広さ、1km²=1000m×1000m=1000000m² です。長さが1000倍になると、面積は1000×1000倍になります。\n「2万5千分の1」は、分数で書くと 1/25000 です。実際の長さを25000でわった長さが、地図上の長さになっているという意味です。\n方位は、とくに方位記号がない地図では、上が北、下が南、右が東、左が西です。',
    secs: [
      { h: '地形図とは何か', t: '【地形図】は、国の機関である【国土地理院】がつくっている、土地のようすをくわしく表した地図です。\n地形図には、建物や道路だけでなく、土地の高さ(等高線)や、田・畑などの土地の使われ方が、決まった記号でかかれています。\nよく使われるのは、【2万5千分の1】と【5万分の1】の地形図です。分母が小さいほど、実際の土地をあまり縮めていないので、せまい範囲をくわしく表せます。\n方位は、方位記号がなければ上が北です。8方位(北・北東・東・南東・南・南西・西・北西)で答えられるようにしておきましょう。\n地形図を読むときは、①縮尺を確かめる、②等高線で高さや傾きを見る、③地図記号で土地の使われ方を見る、の順に進めると整理できます。' },
      { h: '縮尺と実際の距離', t: '【縮尺】は、実際の距離をどれだけ縮めたかを表します。2万5千分の1なら、実際の距離を25000分の1にしています。\nだから地図上の長さを25000倍すれば、もとの長さにもどります。【実際の距離=地図上の長さ×縮尺の分母】です。\n反対に、実際の距離から地図上の長さを求めるときは、【地図上の長さ=実際の距離÷縮尺の分母】です。\n計算のコツは、最後に単位を直すことです。100cm=1m、1000m=1km、つまり 100000cm=1km です。\nよく使う目安:2万5千分の1では【4cmが1km】(4×25000=100000cm)。5万分の1では【2cmが1km】(2×50000=100000cm)。',
        key: '実際の距離=地図上の長さ×縮尺の分母。100000cm=1km。',
        ex: [
          { q: '2万5千分の1の地形図で、2点間の長さが6cmだった。実際の距離は何km?', hint: '地図上の長さに縮尺の分母をかけます。', steps: ['実際の距離=6×25000=150000cm。地図は25000分の1に縮めてあるので、25000倍してもとにもどす。', '100cm=1m なので 150000cm=1500m。', '1000m=1km なので 1500m=1.5km。'], a: '1.5km', check: '目安の「4cm=1km」を使うと、6cmは1.5倍なので1.5kmになり、答えと一致します。' },
          { q: '実際の距離が2.5kmの道は、5万分の1の地形図上では何cmになる?', hint: '先に km を cm に直してから、縮尺の分母でわります。', steps: ['2.5km=2500m=250000cm。単位をそろえないとわり算ができないので、先にcmにする。', '地図上の長さ=実際の距離÷縮尺の分母。地図は実際を50000分の1に縮めているから。', '250000÷50000=5。'], a: '5cm', check: '5万分の1では2cm=1kmなので、2.5kmは2×2.5=5cmで一致します。' },
          { q: 'ある地形図では、実際に2kmはなれた2地点が、地図上で4cmだった。この地図の縮尺は何分の1?', hint: '縮尺の分母=実際の距離÷地図上の長さ、と式を変形します。', steps: ['実際の距離=地図上の長さ×縮尺の分母 なので、縮尺の分母=実際の距離÷地図上の長さ。', '単位をそろえる:2km=2000m=200000cm。', '200000÷4=50000。'], a: '5万分の1', check: '4cm×50000=200000cm=2km となり、問題の条件にもどります。' }
        ] },
      { h: '面積の計算は「長さを先に直す」', t: '地形図から面積を求めるときに一番多いまちがいは、地図上の面積に縮尺の分母をかけてしまうことです。\nなぜだめなのでしょうか。縮尺はたてにもよこにも同じだけ縮めているので、面積は「分母×分母」倍に縮まっているからです。\nそこで、【たて・よこの実際の長さをそれぞれ先に出してから、かけ算】をします。こうすれば、まちがえる心配がありません。\n例:2万5千分の1で2cm×2cmの正方形。たて・よこはそれぞれ 2×25000=50000cm=500m。面積は 500m×500m=250000m²。\n1km²=1000000m² なので、250000m²=0.25km² です。',
        key: '面積は、たて・よこの実際の長さを先に出してからかける。',
        ex: [{ q: '2万5千分の1の地形図で、たて4cm・よこ8cmの長方形の土地がある。実際の面積は何km²?', hint: '4cmが何kmかをまず考えます。', steps: ['2万5千分の1では4cm=1km。だから、たては1km。', 'よこは8cmで、4cmの2倍なので2km。', '面積=1km×2km=2km²。長さを先にkmに直したので、そのままかければよい。'], a: '2km²', check: 'm²で計算すると 1000m×2000m=2000000m²=2km² となり、同じ答えになります。' }] },
      { h: '等高線の読み方', t: '地図は平らな紙なので、そのままでは土地の高さを表せません。そこで、同じ高さの地点を線で結んだ【等高線】で高さを表します。\n2万5千分の1の地形図では、細い【主曲線】が10mごと、太い【計曲線】が50mごとに引かれます(5万分の1では主曲線20mごと、計曲線100mごと)。\n等高線の【間隔がせまい】ところは、少し進むだけで高さが大きく変わるので【傾きが急】です。間隔が広いところは、なかなか高さが変わらないので傾きがゆるやかです。\n等高線の輪がいちばん小さくなる中心が、山頂です。\n下の図では、左側(山頂に近い側)の線の間隔がせまく、右側が広くなっています。左側が急な斜面、右側がゆるやかな斜面です。',
        key: '等高線の間隔がせまいほど、傾きは急。2万5千分の1は主曲線10m・計曲線50m。',
        fig: CONTOUR,
        ex: [{ q: '2万5千分の1の地形図で、ある地点は計曲線(太い線)の150mの線上にある。そこから山頂側へ細い線を2本こえた地点の標高は?', hint: '2万5千分の1の主曲線の間隔は何mかを思い出します。', steps: ['2万5千分の1の主曲線(細い線)は10mごと。', '山頂側へ進むので高くなる。1本こえると160m。', '2本こえると170m。'], a: '170m', check: '計曲線は50mごとなので、次の太い線は200m。170mはその間にあり、矛盾しません。' }] },
      { h: '尾根と谷、断面図', t: '山の斜面には、高いところが細長く続く【尾根】と、低いところが細長く続く【谷】があります。\n等高線が、【低い方へ張り出している】ところは尾根です。山の高い部分が外へつき出しているからです。\n等高線が、【高い方へ食いこんでいる】ところは谷です。低い部分が山の中へ入りこんでいるからです。谷には水が集まるので、川ができやすくなります。\n地図上に線を引き、その線にそって土地を切ったときの形を表したものを【断面図】といいます。線と等高線が交わる点の高さを、たてのめもりにとって点を打ち、なめらかに結んでかきます。\n断面図では、等高線がこみ合っていたところが急な坂、まばらなところがゆるやかな坂として表れます。',
        fig: SECTION },
      { h: 'おもな地図記号', t: '地図記号は、そのものの形や、関係する道具・文字をもとにつくられています。形のもとを知ると、覚えやすくなります。\n土地利用:【田】は稲をかりとったあとの形(||)、【畑】は植物の双葉の形(V)、【果樹園】は果実の形、【茶畑】は茶の実の形(∴)、広葉樹林・針葉樹林は木の形です。\n建物・施設:【小・中学校】は「文」の字、【郵便局】は〒のマーク、【警察署】は⊗、【交番】は×、【消防署】は昔の火消しが使った道具(さすまた)の形、【寺院】は卍、【神社】は鳥居の形、【市役所】は◎、町村役場は○。\n【工場】は機械の歯車の形、【発電所・変電所】は歯車と電気の流れを組み合わせた形、【病院】は十字の形です。\n新しい記号:【老人ホーム】(建物の中につえ)、【図書館】(本を開いた形)、【博物館】(建物の形)、自然災害の教訓を伝える【自然災害伝承碑】(記念碑の形に縦線)などがあります。' },
      { h: '地形図から土地のようすを読む', t: '地形図の問題は、等高線と地図記号を組み合わせて読みます。\n例1:等高線の間隔が広く、平らなところに田の記号が多い → 川ぞいの低地で、水が得やすい。\n例2:山のふもとの扇形に広がる土地に果樹園の記号が多い → 扇状地。川から遠く水はけのよい土地を生かしている。\n例3:川の河口付近の平らな土地に、建物が密集している → 三角州の上に町ができている。\n「昔の地形図」と「今の地形図」を比べる問題では、田が住宅地に変わった、海岸がうめ立てられた、などの変化を探します。\n答えるときは、「何の記号が(根拠)→ どこに多いか → だから何と言えるか」の順に書くと、説得力のある説明になります。',
        ex: [{ q: '地形図で、山のふもとに等高線が扇形に広がり、そこに果樹園の記号が多く見られた。この土地の地形の名前と、果樹園が多い理由を答えよう。', hint: '山のふもとで、扇の形に広がる地形を思い出します。', steps: ['山のふもとで等高線が扇形に広がる → 川が山から出たところに土砂が積もった地形。', 'この地形は扇状地。', '扇状地はつぶの大きい砂やれきでできていて、水はけがよい。', '水をためる水田には向かず、果樹の栽培に向く。'], a: '扇状地。水はけがよく、水田より果樹の栽培に向いているから。' }] }
    ],
    faq: [
      ['なぜ面積は「地図上の面積×分母」ではだめなの?', '地図は、たてもよこも同じ割合で縮めています。だから面積は「分母×分母」分の1に縮まっています。\n×分母を1回しかしないと、答えが大きく足りなくなります。たて・よこの長さを先に実際の長さに直してからかければ、この心配はありません。'],
      ['5万分の1と2万5千分の1、どちらがくわしいの?', '2万5千分の1のほうがくわしいです。分母が小さいほど、実際の土地をあまり縮めていないので、同じ大きさの紙に、せまい範囲を大きくかけるからです。\n等高線も、2万5千分の1は10mごと、5万分の1は20mごとで、2万5千分の1のほうが細かく引かれています。'],
      ['尾根と谷がいつも逆になってしまう。見分けるコツは?', '等高線の数字(高さ)を見て、「線の先が高い方を向いているか、低い方を向いているか」を考えます。\n高い方へ食いこんでいる(とがった先が山頂を向く)なら、低い土地が山に入りこんでいる=谷です。低い方へ張り出しているなら、高い土地がつき出している=尾根です。']
    ],
    terms: [['縮尺', '実際の距離を地図上でどれだけ縮めたかを表す割合'], ['等高線', '同じ高さの地点を結んだ線'], ['主曲線・計曲線', '細い線と太い線の等高線。2万5千分の1では10mごと・50mごと'], ['尾根', '等高線が低い方へ張り出した、山の高い部分の連なり'], ['谷', '等高線が高い方へ食いこんだ部分。川ができやすい'], ['断面図', '地図上の線にそって土地を切ったときの、高さの変化を表した図'], ['国土地理院', '地形図をつくっている国の機関']],
    miss: ['cm を km に直すとき、0の数をまちがえる。100000cm=1km(0が5個)を、「4cm=1km(2万5千分の1)」という目安で毎回確かめる。', '等高線の間隔がせまい=ゆるやか、と逆に覚える。「せまい間に何本も線がある=短い距離でたくさん登る=急」と理由で覚える。', '2万5千分の1と5万分の1で、等高線の間隔(10mと20m)を取りちがえる。縮尺を最初に確認するくせをつける。', '面積を「地図上の面積×25000」で計算してしまう。長さを先に直してからかける。'],
    sum: ['実際の距離=地図上の長さ×縮尺の分母。', '2万5千分の1では4cm=1km、主曲線10m・計曲線50m。', '面積は、たて・よこを実際の長さに直してからかける。', '等高線の間隔がせまいほど急な斜面。低い方へ張り出すと尾根、高い方へ食いこむと谷。', '地図記号は形のもとになったものと結びつけて覚える。'],
    next: '地理の基本がそろったら、「歴史(古代)c_ancient」に進みましょう。古代の文明が大きな川のそばで生まれた理由は、地形と水の知識で説明できます。'
  };

  // ===== 中学歴史 =====
  L.c_ancient = {
    goal: '古代文明の誕生から、律令国家の成立、貴族の政治へと移る流れを、原因と結果で説明できるようになる。',
    intro: '古代の歴史は、「ムラがクニになり、クニが国家になる」物語です。米づくりが始まると、たくわえや土地をめぐって争いが起き、強い者が人々をまとめるようになります。やがて中国にならった法律(律令)で国を治めるしくみができ、そのしくみがゆらいで貴族が力をもつ時代へと進みます。',
    pre: '歴史では、年を【西暦】で表します。キリストが生まれたとされる年を紀元1年とし、それより前を【紀元前】(B.C.)といいます。紀元前は、さかのぼるほど数字が大きくなります。\n100年ごとの区切りを【世紀】といいます。1世紀は1〜100年、7世紀は601〜700年です。\n日本の歴史は、旧石器 → 縄文 → 弥生 → 古墳 → 飛鳥 → 奈良 → 平安 → … のように、時代の名前で区切ります。時代の名前の多くは、その時代の特徴や政治の中心地からつけられています(奈良・平安は都の場所)。\n歴史を学ぶときは、「何が起きたか」だけでなく、「なぜ起きたか(原因)」「その結果どうなったか」をセットにすると、話がつながって覚えやすくなります。',
    secs: [
      { h: '人類の出現と古代文明', t: '人類は、石を打ちかいてつくった【打製石器】を使い、狩りや採集をしながら移動して暮らしていました(旧石器時代)。\nやがて、作物を育てる農耕や、家畜を飼う牧畜が始まりました。食べ物をたくわえられるようになると、人々は1か所に住みつき、表面をみがいた【磨製石器】や土器も使うようになりました(新石器時代)。\n農耕には水が必要です。そこで、大きな川のほとりで、多くの人が集まって住む文明が生まれました。\n【エジプト文明】(ナイル川)…ピラミッド、象形文字、太陽暦。\n【メソポタミア文明】(チグリス川・ユーフラテス川)…くさび形文字、太陰暦、60進法。\n【インダス文明】(インダス川)…道路や下水道が整った計画的な都市(モヘンジョ=ダロ)。\n【中国文明】(黄河・長江)…殷の時代に、うらないの結果をきざんだ甲骨文字(漢字のもと)。紀元前221年には、秦の始皇帝が中国を初めて統一しました。',
        key: '文明が大河のほとりで生まれたのは、水が得やすく土地が肥えていて、農耕で多くの人を養えたから。',
        ex: [{ q: '古代文明の多くが、大きな川の流域で生まれたのはなぜ?', hint: '農耕に必要なものは何かを考えます。', steps: ['農耕には、作物に与える水が大量に必要。大きな川の近くなら水が得やすい。', '川が洪水で運んでくる土は栄養が多く、作物がよく育つ。', '食料がたくさんとれると、多くの人が集まって住めるようになる。', '人が集まると、まとめる指導者や、記録のための文字、暦が生まれ、文明になった。'], a: '水が得やすく、川が運ぶ肥えた土で農耕がさかんになり、多くの人を養えたから。人が集まったことで、王や文字・暦が生まれた。', check: '「川から遠い乾燥した土地では、同じように人が集まれたか」と逆を考えると、理由が確かめられます。' }] },
      { h: '縄文・弥生・古墳時代:ムラからクニへ', t: '【縄文時代】…表面に縄目の文様をつけた【縄文土器】を使い、地面をほり下げて屋根をかけた【たて穴住居】に住み、狩り・漁・採集で暮らしました。食べたあとの貝がらなどを捨てた【貝塚】が各地に残っています。まだ大きな貧富の差はありませんでした。\n【弥生時代】…縄文時代の終わりごろ、大陸から【稲作】と金属器(青銅器・鉄器)が伝わりました。米は保存がきくので、たくわえの多い人と少ない人が生まれ、【貧富の差や身分の差】ができました。\n稲作には、水田にする土地と水が必要です。そのため、土地や水をめぐってムラどうしの争いが起き、強いムラがまわりを従えて【クニ】ができました。佐賀県の吉野ヶ里遺跡には、敵を防ぐための堀やさくのあとが残っています。\n中国の歴史書によると、1世紀には奴国の王が漢に使いを送って金印を授かり、3世紀には女王【卑弥呼】が治める【邪馬台国】が魏に使いを送りました(「魏志」倭人伝)。\n【古墳時代】…3世紀後半から、王や豪族の大きな墓である【古墳】がつくられました。近畿地方を中心に、大王を頂点とする【大和政権(ヤマト王権)】が各地の豪族を従えていきました。巨大な【前方後円墳】(大阪府の大仙古墳など)は、多くの人を働かせる強い力をもつ支配者がいたことを示します。\nこのころ、朝鮮半島などから移り住んだ【渡来人】が、漢字・仏教・須恵器(かたい土器)・機織りなどの技術を伝えました。',
        key: '米をたくわえられるようになったことで、貧富の差と争いが生まれ、ムラ → クニ → 大和政権へとまとまっていった。',
        ex: [{ q: '弥生時代になると、身分の差が生まれたのはなぜ?', hint: '稲作で手に入る米は、保存できるかどうかを考えます。', steps: ['弥生時代に稲作が広まり、米がとれるようになった。', '米は長く保存できるので、たくわえが多い人と少ない人の差ができた(貧富の差)。', '水田や水をめぐる争いが起き、争いを指導する人や、勝ったムラの人が上に立った。', 'こうして支配する人とされる人、つまり身分の差が生まれた。'], a: '稲作で米をたくわえられるようになり、貧富の差が生まれたうえ、土地や水をめぐる争いを通じて、人々を支配する者が現れたから。' }] },
      { h: '天皇中心の国づくり(飛鳥・奈良時代)', t: '6世紀の終わりごろ、中国では隋が国を統一し、強い国になりました。大和政権は、日本も中国に負けない国づくりをしようとします。\n【聖徳太子】(厩戸皇子)は、蘇我馬子と協力して、家がらではなく能力や功績で役人を取り立てる【冠位十二階】(603年)や、役人の心がまえを示す【十七条憲法】(604年)を定めました。また、【遣隋使】(小野妹子など)を送り、隋の進んだ制度や文化を取り入れようとしました。\n645年、【中大兄皇子】と【中臣鎌足】が、力をもちすぎた蘇我氏を倒し、【大化の改新】を始めました。豪族が持っていた土地と人々を国のものにする【公地公民】をめざします。\n663年、日本は友好国の百済を助けて朝鮮半島に兵を送りましたが、唐と新羅の連合軍に【白村江の戦い】で大敗しました。その後は国内の守りを固め、天皇中心の国づくりをさらに急ぎます。\n701年の【大宝律令】で、唐の法律にならい、【律】(刑罰のきまり)と【令】(政治のきまり)による国家のしくみが整いました。このような国を【律令国家】といいます。\n710年、都が奈良の【平城京】に移りました。唐の都・長安にならい、道路が碁盤の目のように整えられた都です。',
        key: '大化の改新(645年)でめざした公地公民が、大宝律令(701年)で法律のしくみとして完成した。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 平安京に都を移す イ 大化の改新 ウ 平城京に都を移す エ 大宝律令の制定', hint: 'まず「国づくりの出発点」→「法律ができる」→「その法律で動く都」の順を考えます。', steps: ['大化の改新は645年。蘇我氏を倒し、公地公民をめざした国づくりの出発点。', '大宝律令は701年。めざしてきた国のしくみが法律として整う。', '平城京は710年。律令にもとづいて国を治める都。', '平安京は794年。奈良時代の政治の混乱を立て直すために移した都。'], a: 'イ → エ → ウ → ア', check: '年号を並べると 645 → 701 → 710 → 794 で、小さい順になっています。' }] },
      { h: '律令のもとでの人々の暮らし', t: '律令国家では、国が人々を直接つかむために、6年ごとに【戸籍】をつくりました。\n戸籍にもとづいて、6歳以上の男女に【口分田】という田を与え、その人が死ぬと国に返させました。これを【班田収授法】といいます。土地は国のもので、人々はそれを借りて耕す、という公地公民の考え方を形にしたしくみです。\n人々は、口分田を与えられるかわりに、重い負担を負いました。【租】…収穫した稲の約3%を納める。【調】…地方の特産物(絹・塩・魚など)を都に納める。【庸】…都で働くかわりに布を納める。\nさらに、男子には兵役があり、一部は九州北部の守りにつく【防人】として、遠くまで行かされました。調・庸は自分で都まで運ばなければならず、負担はたいへん重いものでした。\n仏教の力で国を守ろうとした【聖武天皇】は、国ごとに【国分寺】・国分尼寺を建て、都には【東大寺】の大仏をつくらせました。\nこのころの文化を【天平文化】といいます。遣唐使がもたらした唐の文化や、遠く西アジアの影響も受けた国際的な文化で、【正倉院】には聖武天皇の遺品が残されています。歴史書の「古事記」「日本書紀」、和歌集の「万葉集」もつくられました。' },
      { h: '律令のゆらぎと荘園のはじまり', t: '奈良時代の中ごろになると、人口がふえて口分田が足りなくなりました。さらに、重い負担からにげ出す人も出て、田があれていきました。\n国は開墾をすすめるため、723年に【三世一身法】を出し、新しく開いた土地を3代まで私有することを認めました。しかし、期限が来ると国に返さなければならないので、あまり効果はありませんでした。\nそこで743年に【墾田永年私財法】を出し、新しく開いた土地の【永久の私有】を認めました。\nその結果、人手とお金のある貴族や寺社が、どんどん開墾して私有地を広げました。この私有地が、のちに【荘園】とよばれるようになります。\nこれは、「土地はすべて国のもの」という公地公民の原則が、くずれていくことを意味しました。',
        key: '墾田永年私財法(743年)は開墾をすすめるための法だったが、結果として私有地(荘園)を広げ、公地公民をくずした。',
        ex: [{ q: '墾田永年私財法が出されたことで、土地のしくみはどう変わった?原因と結果で説明しよう。', hint: '「なぜ出したか」と「出した結果どうなったか」を分けて考えます。', steps: ['原因:人口がふえ、口分田が不足していた。三世一身法では期限があり、開墾が進まなかった。', '国は開墾をすすめるため、新しく開いた土地の永久私有を認めた。', '結果:人手やお金のある貴族や寺社が開墾して私有地を広げ、荘園が生まれた。', 'まとめ:土地も人も国のものという公地公民の原則がくずれた。'], a: '口分田の不足を補うために開墾地の永久私有を認めた結果、貴族や寺社の私有地(荘園)が広がり、公地公民の原則がくずれていった。' }] },
      { h: '平安時代:摂関政治と国風文化', t: '794年、【桓武天皇】は、仏教勢力が政治に口を出すようになった奈良をはなれ、都を京都の【平安京】に移して、政治の立て直しをはかりました。東北地方には【坂上田村麻呂】を征夷大将軍として送り、朝廷の支配を広げました。\nその後、【藤原氏】が力をのばします。藤原氏は、娘を天皇のきさきにし、生まれた子を天皇に立てました。天皇から見ると、藤原氏は母方の祖父(外戚)にあたります。\nそして、天皇が幼いときは【摂政】、成人してからは【関白】として、天皇に代わって政治の実権をにぎりました。これを【摂関政治】といいます。11世紀前半の【藤原道長】・【頼通】の親子のころが全盛期で、頼通は宇治に【平等院鳳凰堂】を建てました。\n894年、【菅原道真】の進言で遣唐使が停止されると、中国の文化を取り入れたうえで、日本の風土や生活に合った【国風文化】が発達しました。\n漢字をくずした【かな文字】が生まれ、気持ちを細やかに表せるようになりました。紫式部の「源氏物語」、清少納言の「枕草子」はかな文字で書かれました。貴族は【寝殿造】のやしきに住みました。\nまた、死後に極楽浄土に生まれ変わることを願う【浄土信仰】が広まりました。',
        key: '摂関政治は、藤原氏が天皇の外戚(母方の親せき)となり、摂政・関白として実権をにぎった政治。',
        ex: [{ q: '藤原氏が、天皇でもないのに政治の実権をにぎれたのはなぜ?', hint: '藤原氏と天皇の「家族の関係」に注目します。', steps: ['藤原氏は、自分の娘を天皇のきさきにした。', '娘が産んだ子が天皇になると、藤原氏はその天皇の母方の祖父(外戚)になる。', '天皇が幼いと、祖父である藤原氏が摂政として政治を代わりに行い、成人後も関白として補佐した。', 'こうして天皇の権威を借りながら、実際の政治を動かした。'], a: '娘を天皇のきさきにして、生まれた子を天皇に立て、その外戚(母方の祖父など)として摂政・関白になり、天皇に代わって政治を行ったから。' }] }
    ],
    faq: [
      ['旧石器・縄文・弥生は、何で区別しているの?', '主に、使っていた道具と暮らし方で区別しています。\n旧石器時代は打製石器で狩り・採集をしていた時代。縄文時代は縄文土器を使い、狩り・漁・採集で暮らした時代。弥生時代は稲作と金属器が伝わり、弥生土器を使った時代です。'],
      ['摂政と関白は何がちがうの?', 'どちらも天皇に代わって、または天皇を助けて政治を行う役職です。\n天皇が幼いとき、または女性の天皇のときに政治を代わりに行うのが摂政、天皇が成人したあとに天皇を補佐するのが関白です。'],
      ['なぜ遣唐使をやめたの?', '唐がおとろえて国内が乱れていたことと、海をわたる危険が大きかったことが理由です。\nそれまでに唐の文化は十分に学んでいたので、その後は、それを日本の風土や生活に合わせた国風文化が育ちました。']
    ],
    terms: [['大和政権', '大王を中心に、近畿地方の豪族がつくった政権'], ['律令', '律は刑罰のきまり、令は政治のきまり。中国(唐)にならった'], ['公地公民', '土地と人々を国(天皇)のものとする原則'], ['班田収授法', '戸籍にもとづき6歳以上の男女に口分田を与え、死ぬと返させたしくみ'], ['墾田永年私財法', '743年。新しく開墾した土地の永久私有を認めた法'], ['摂関政治', '藤原氏が摂政・関白となって行った政治'], ['国風文化', '平安時代中ごろの、日本の風土や生活に合った文化']],
    miss: ['平城京(710年・奈良)と平安京(794年・京都)を取りちがえる。「奈良の平城京 → 平安京は京都で平安時代の始まり」と、時代名とセットで覚える。', '墾田永年私財法を「土地を国のものにした法」と逆に覚える。「私財」=自分の財産、ということばの意味から考える。', '摂関政治を天皇自身が行った政治と思ってしまう。実権は外戚の藤原氏にあった。', '租・調・庸の中身を取りちがえる。租=稲(田の税)、調=特産物、庸=布(労役の代わり)と、納める物で区別する。'],
    sum: ['文明は大河のほとりで生まれた。', '稲作で貧富の差が生まれ、ムラ → クニ → 大和政権へとまとまった。', '大化の改新(645年)から大宝律令(701年)で律令国家ができた。', '班田収授と租・調・庸は重い負担で、墾田永年私財法(743年)で荘園が生まれた。', '平安時代は藤原氏の摂関政治と、かな文字の国風文化。'],
    next: '次は「中世(c_medieval)」です。荘園を守るために武装した人々が「武士」になり、やがて政治の主役になっていく流れを学びます。'
  };

  L.c_medieval = {
    goal: '武士がおこり、鎌倉幕府・室町幕府が成立して戦国時代に至る流れを、原因と結果でつないで説明できるようになる。',
    intro: '中世は「武士が政治の主役になる時代」です。はじめは貴族のボディーガードにすぎなかった武士が、力をつけて幕府を開き、やがて全国を支配します。ポイントは、鎌倉と室町で「だれが・どこで・どのように」支配したかを比べることと、幕府がおとろえた原因をたどることです。',
    pre: '平安時代には、藤原氏が摂政・関白として政治を動かしました(摂関政治)。都の貴族は、地方の政治を国司にまかせていました。\n奈良時代の墾田永年私財法をきっかけに、貴族や寺社の私有地である【荘園】が広がりました。荘園は、国の役人が勝手に入れないなど、特別な権利をもつようになっていきます。\n地方では、国司の取り立てや争いから自分の土地を守る必要がありました。こうした中で、武器をもって土地を守る人々が生まれます。これが武士の始まりです。\n【幕府】とは、武士の頭である【征夷大将軍】が政治を行う役所のことです。中世には、鎌倉と室町の2つの幕府が開かれました。',
    secs: [
      { h: '武士のおこりと平氏の政治', t: '地方では、土地をめぐる争いや、盗賊から身を守るために、有力な農民や豪族が武装しました。彼らが一族や家来を率いて【武士団】をつくり、なかでも天皇の子孫である【源氏】と【平氏】が二大勢力に成長しました。\n1086年、【白河上皇】は、天皇の位を子にゆずったあとも、上皇として政治を行う【院政】を始めました。天皇の父という立場で政治を動かすことで、藤原氏(摂関家)の力をおさえたのです。\n12世紀の半ば、天皇家や藤原氏の内部の争いから【保元の乱】・【平治の乱】が起こり、争いは武士の力で決着しました。武士が政治を動かす力をもったことが、はっきりしたのです。\n平治の乱で源氏を破った【平清盛】は、武士として初めて【太政大臣】になりました。清盛は、兵庫の港(大輪田泊)を整えて宋との貿易(【日宋貿易】)を行い、富をたくわえました。\nしかし平氏は、娘を天皇のきさきにして一族で高い位を独占したため、貴族や他の武士の反発をまねきました。源頼朝・義経らが兵をあげ、1185年、【壇ノ浦の戦い】で平氏はほろびました。' },
      { h: '鎌倉幕府と御恩・奉公', t: '【源頼朝】は、武士の多い東国の鎌倉を本拠地にしました。1185年、国ごとに【守護】、荘園や公領ごとに【地頭】を置くことを朝廷に認めさせ、1192年に【征夷大将軍】になりました。\n将軍と家来の武士(【御家人】)は、【御恩と奉公】という関係で結ばれていました。\n【御恩】…将軍が、御家人の先祖からの領地を認めて守ったり、手がらに応じて新しい領地を与えたりすること。\n【奉公】…御家人が、戦いが起これば命がけで戦い、ふだんは京都や鎌倉の警備をつとめること。\nこの関係は、【土地を仲立ち】にしています。だから、将軍が御恩として与える土地がなくなると、関係がゆらいでしまいます。この点が、のちに幕府がおとろえる理由につながります。\n頼朝の死後、将軍の力は弱まり、頼朝の妻・北条政子の実家である【北条氏】が【執権】として実権をにぎりました。これを【執権政治】といいます。',
        key: '御恩と奉公は土地を仲立ちにした関係。与える土地がなくなると、関係がくずれる。',
        ex: [{ q: '鎌倉幕府の「御恩」と「奉公」とは何か。それぞれ、だれがだれに対して行うものか説明しよう。', hint: '「恩を与える側」と「仕える側」を分けて考えます。', steps: ['御恩は、将軍が御家人に対して行うもの。', '内容は、先祖からの領地の支配を認めて守ること、手がらに応じて新しい領地を与えること。', '奉公は、御家人が将軍に対して行うもの。', '内容は、戦いのときに命がけで戦い、ふだんは京都や鎌倉の警備をすること。'], a: '御恩は将軍が御家人の領地を守ったり新しい領地を与えたりすること。奉公は御家人が将軍のために戦い、警備をつとめること。', check: '「土地」を間にはさんで、矢印が両方向に向いていることを図にかいて確かめましょう。' }] },
      { h: '承久の乱と執権政治の安定', t: '鎌倉幕府ができたあとも、京都の朝廷は西日本を中心に力を残していました。\n1221年、【後鳥羽上皇】は、幕府の将軍のあとつぎがとだえた混乱を見て、幕府を倒そうと兵をあげました。これを【承久の乱】といいます。\n北条政子は、御家人たちに頼朝の御恩を説いて団結をよびかけ、幕府の大軍は京都に攻め上って上皇方を破りました。\n乱のあと、幕府は上皇を隠岐(島根県)に流し、京都に【六波羅探題】を置いて朝廷を監視しました。さらに、上皇方についた貴族や武士の土地を取り上げ、手がらのあった東国の御家人をその地の地頭にしました。こうして幕府の支配は【西日本にまで広がりました】。\n1232年、執権【北条泰時】は、武士の社会の慣習をもとに、裁判の基準を示す【御成敗式目】(貞永式目)を定めました。武士のための初めての法律で、土地をめぐる争いを公平に裁くことがねらいでした。',
        key: '承久の乱で幕府が勝ち、六波羅探題を置き、支配が西日本まで広がった。',
        ex: [{ q: '承久の乱のあと、幕府の力が強まったのはなぜ?2つの点から説明しよう。', hint: '朝廷に対して何をしたか、土地をどうしたか、の2つに分けます。', steps: ['乱に勝った幕府は、京都に六波羅探題を置いて、朝廷の動きを監視できるようにした。', '上皇方についた貴族や武士の領地を取り上げた。', 'その土地に、手がらのあった東国の御家人を地頭として置いた。御恩として新しい土地を与えられたので、御家人の幕府への信頼も高まった。', 'こうして西日本にも幕府の御家人が入り、支配が全国に広がった。'], a: '六波羅探題を置いて朝廷を監視したことと、上皇方の土地を取り上げて東国の御家人を地頭に任じ、幕府の支配を西日本に広げたことから。' }] },
      { h: '元寇と鎌倉幕府のほろび', t: '13世紀、ユーラシア大陸にモンゴル帝国が広がり、その一部である【元】の【フビライ・ハン】が、日本に従うよう求めてきました。執権【北条時宗】がこれを退けると、元軍は2度攻めてきました(1274年文永の役、1281年弘安の役=【元寇】)。\n元軍は集団戦法や火薬を使った武器で御家人を苦しめましたが、御家人の奮戦や、海岸に築いた石の防壁(防塁)、暴風雨などもあって、元軍は引きあげました。\nしかし、これは外国から守る戦いだったので、勝っても新しく手に入れた土地がありませんでした。そのため幕府は、命がけで戦った御家人に【十分な恩賞(御恩)を与えられません】でした。\nもともと御家人は、領地を子どもたちに分けて相続する【分割相続】で、領地が小さくなっていました。戦いの費用も自分持ちだったので、生活が苦しくなり、土地を手放す者も出てきました。\n幕府は1297年に、御家人の借金を帳消しにする【徳政令】を出しましたが、お金を貸す人がいなくなって、かえって経済が混乱しました。\nこうして御恩と奉公の関係がくずれ、幕府への不満が高まります。【後醍醐天皇】がこの機をとらえて兵をあげ、【足利尊氏】・新田義貞らがこれに味方して、1333年に鎌倉幕府はほろびました。',
        key: '元寇は防衛戦で恩賞の土地がなく、御恩と奉公がくずれたことが鎌倉幕府滅亡の大きな原因。',
        ex: [{ q: '元寇のあと、鎌倉幕府がおとろえたのはなぜ?因果の流れで説明しよう。', hint: '御恩と奉公が「土地」を仲立ちにしていたことを思い出します。', steps: ['元寇は防衛の戦いで、敵から奪った土地がなかった。', 'そのため幕府は御家人に十分な恩賞(土地)を与えられなかった。御恩が果たせなくなったということ。', '御家人は戦いの費用や分割相続で生活が苦しくなり、徳政令も効果がうすかった。', '御恩と奉公の関係がくずれ、幕府への不満が高まり、倒幕の動きに御家人も加わった。'], a: '元寇で恩賞の土地が与えられず、御家人が生活に苦しんで幕府への不満を強め、御恩と奉公の関係がくずれたから。' }] },
      { h: '建武の新政・南北朝と室町幕府', t: '鎌倉幕府をほろぼした後醍醐天皇は、1334年から天皇中心の政治を始めました(【建武の新政】)。しかし、恩賞が公家にかたよるなど、武士の不満をまねき、2年ほどでくずれました。\n【足利尊氏】は京都に別の天皇を立て、1338年に征夷大将軍になって、京都に幕府を開きました。後醍醐天皇は奈良の吉野にのがれ、京都の【北朝】と吉野の【南朝】に朝廷が2つに分かれた【南北朝時代】が、約60年続きました。\n3代将軍【足利義満】は、1392年に南北朝を統一し、京都の室町に「花の御所」を建てて政治を行いました。室町幕府の名前はここから来ています。\n義満は明と国交を開き、【勘合貿易(日明貿易)】を始めました。勘合という合い札(証明書)を使ったのは、正式な貿易船と、中国や朝鮮の沿岸をあらしていた海賊(【倭寇】)を区別するためです。\n室町幕府では、将軍を補佐する【管領】が置かれ、有力な守護大名がつきました。地方の【守護】は、国内の武士を家来にし、年貢の半分を取る権利なども得て力をつけ、【守護大名】とよばれるようになりました。',
        ex: [{ q: '日明貿易で「勘合」という証明書が使われたのはなぜ?', hint: '当時、中国の沿岸で何が問題になっていたかを考えます。', steps: ['このころ、中国や朝鮮の沿岸では、倭寇とよばれる海賊が船や村をおそっていた。', '明は倭寇の取りしまりを日本に求めていた。', '正式な貿易船に勘合という合い札を持たせれば、明の役所で照らし合わせて本物かどうかを確かめられる。', 'これで、正式な貿易船と倭寇の船を区別できた。'], a: '正式な貿易船と倭寇(海賊)の船を区別するため。' }] },
      { h: '民衆の成長・応仁の乱と戦国時代', t: '室町時代には、農業の技術が進み、米と麦を同じ田で年2回つくる【二毛作】が広まりました。生産がふえると、民衆の力も強くなっていきます。\n村では、農民が【惣(惣村)】という自治のしくみをつくり、寄合(話し合い)で村のおきてを決めました。団結した農民は、借金の帳消しを求めて【土一揆】を起こすこともありました(1428年の正長の土一揆など)。\n商工業者は【座】という同業者の組合をつくり、貴族や寺社に税を納めるかわりに、営業を独占する権利を得ました。お金を貸す土倉や酒屋も栄えました。\n8代将軍【足利義政】のあとつぎ問題に、有力な守護大名の対立が結びついて、1467年に【応仁の乱】が起き、11年間にわたって京都は戦場となり焼け野原になりました。\n乱のあと、幕府の力は京都の周りにしかおよばなくなりました。各地では、家来が主君を倒すなど、下の身分の者が上の者を実力で倒す【下剋上】の風潮が広がり、実力で国を支配する【戦国大名】が争う【戦国時代】になりました。\n戦国大名は、領国を治めるために独自のきまり(【分国法】)をつくり、城の周りに家来や商工業者を集めて【城下町】をつくりました。',
        key: '応仁の乱(1467年)で幕府の力が失われ、下剋上の風潮の中で戦国大名が争う戦国時代になった。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 元寇 イ 御成敗式目の制定 ウ 承久の乱 エ 永仁の徳政令', hint: '「幕府が朝廷に勝つ」→「支配を固めるきまり」→「外国との戦い」→「その後始末」の順に考えます。', steps: ['承久の乱(1221年)で幕府が朝廷に勝ち、支配が西日本に広がる。', '支配が広がって土地の争いがふえたので、裁判の基準として御成敗式目(1232年)。', '元寇(1274年・1281年)で御家人が疲れる。', '苦しむ御家人を救うために徳政令(1297年)。'], a: 'ウ → イ → ア → エ', check: '1221 → 1232 → 1274 → 1297 と、年号が小さい順になっています。' }] },
      { h: '鎌倉・室町の文化', t: '【鎌倉文化】…武士の気風を反映した、力強く写実的な文化です。東大寺南大門の【金剛力士像】(運慶・快慶ら)や、軍記物語の「平家物語」(琵琶法師が語り伝えた)が代表です。\n鎌倉時代には、戦乱やききんに苦しむ人々の心をとらえる、分かりやすく実行しやすい新しい仏教(【鎌倉仏教】)が生まれました。念仏を唱える法然の【浄土宗】、親鸞の【浄土真宗】、一遍の時宗、題目を唱える日蓮の【日蓮宗】、座禅で自分の力で悟りを開く栄西の【臨済宗】・道元の【曹洞宗】(禅宗)です。\n【北山文化】…3代将軍足利義満のころ。京都の北山に【金閣】を建てた。公家の文化と武家の文化がまじり合った。観阿弥・世阿弥が【能】を大成した。\n【東山文化】…8代将軍足利義政のころ。京都の東山に【銀閣】を建てた。たたみ・ふすま・床の間のある【書院造】が広まり、今の和風住宅のもとになった。【雪舟】が水墨画を大成した。落ち着いた、簡素で深みのある美しさが好まれた。\n民衆の間では、能の合間に演じられる【狂言】や、おとぎ草子などの物語が楽しまれました。' }
    ],
    faq: [
      ['守護と地頭は何がちがうの?', '守護は「国ごと」に1人置かれ、その国の御家人をまとめ、軍事や警察の仕事をしました。\n地頭は「荘園や公領ごと」に置かれ、年貢の取り立てや土地の管理をしました。守護のほうが広い範囲を受けもつ、と考えると分かりやすいです。'],
      ['元寇に勝ったのに、なぜ幕府はおとろえたの?', '勝ったといっても、日本の土地を守っただけで、新しい土地を奪ったわけではないからです。\n御恩と奉公は土地を与えることで成り立っていたので、恩賞の土地がないと、御家人は「命がけで戦ったのに報われない」と感じました。この不満が幕府への信頼を失わせました。'],
      ['院政と摂関政治のちがいは?', '摂関政治は、藤原氏が天皇の母方の親せき(外戚)として、摂政・関白の地位で政治を動かしました。\n院政は、位をゆずった上皇が、天皇の父(や祖父)として政治を動かしました。父方の立場で政治を行うことで、藤原氏の力をおさえたのです。']
    ],
    terms: [['院政', '天皇が位をゆずったあとも、上皇として行う政治'], ['御恩と奉公', '将軍と御家人の、土地を仲立ちにした主従関係'], ['執権', '鎌倉幕府で将軍を補佐する役職。北条氏が独占した'], ['御成敗式目', '1232年に北条泰時が定めた、武士の裁判の基準'], ['勘合貿易', '勘合という証明書を使って行った明との貿易'], ['守護大名', '室町時代に、国内の武士を家来にして力をつけた守護'], ['下剋上', '下の身分の者が、実力で上の者を倒すこと'], ['惣', '室町時代の農民の自治的な村のしくみ']],
    miss: ['承久の乱の結果を「朝廷が勝った」と逆に覚える。勝ったのは幕府で、だから六波羅探題が置かれた、と結果とセットで覚える。', '元寇で幕府がおとろえた理由を「戦いに負けたから」と答える。撃退したが恩賞の土地がなかった、が正しい。', '金閣(義満・北山)と銀閣(義政・東山)を取りちがえる。「金は満(みちる)、銀は政」「キン・キタ(北山)」と組で覚える。', '北条氏を将軍だと思う。北条氏は執権で、将軍は別にいた。'],
    sum: ['院政と平氏政権を経て、源頼朝が鎌倉幕府を開いた。', '鎌倉幕府は御恩と奉公でなりたち、北条氏が執権として支配した。', '承久の乱で幕府の力が西日本に広がり、御成敗式目で裁判の基準を示した。', '元寇で恩賞が出せず、御恩と奉公がくずれて幕府はほろんだ。', '室町幕府は勘合貿易で栄えたが、応仁の乱で力を失い、下剋上の戦国時代へ。'],
    next: '次は「近世(c_early)」です。戦国の争いを終わらせた織田信長・豊臣秀吉・徳川家康が、どのように全国をまとめたかを学びます。'
  };

  L.c_early = {
    goal: '天下統一から江戸幕府の安定、三大改革、そして幕府のゆらぎまでの流れを「だれが・何を・なぜ」で説明できるようになる。',
    intro: '近世は、戦国の争いが終わって、長く平和が続いた時代です。織田信長・豊臣秀吉が全国を統一し、徳川家康が260年以上続く江戸幕府を開きました。平和が長く続いた理由(大名をおさえるしくみ)と、時代が進むにつれて出てきた問題(幕府の財政難)に、それぞれの改革がどう取り組んだかをつかみましょう。',
    pre: '室町時代の後半、1467年の応仁の乱をきっかけに幕府の力が弱まり、各地の【戦国大名】が実力で争う戦国時代になりました。\n戦国時代には、下の者が上の者を倒す【下剋上】が広がり、身分や支配のしくみが大きくゆらいでいました。\nこのころヨーロッパでは、アジアの香辛料などを直接手に入れるため、ポルトガルやスペインが船で世界に進出していました(大航海時代)。この動きが、日本にも届きます。\n江戸時代の税は、主に【米】で納める【年貢】でした。武士の給料も米でした。この「米が経済の中心」という点が、のちの幕府の財政難を理解するカギになります。',
    secs: [
      { h: 'ヨーロッパ人の来航と天下統一', t: '1543年、種子島に流れ着いたポルトガル人が【鉄砲】を伝えました。鉄砲はすぐに堺(大阪府)などで大量につくられ、戦い方を変えました。1549年には、イエズス会の宣教師【ザビエル】が鹿児島に来て、キリスト教を伝えました。ポルトガル・スペインとの貿易を【南蛮貿易】といいます。\n【織田信長】…1573年に室町幕府をほろぼし、1575年の【長篠の戦い】で鉄砲を有効に使って武田氏に勝利しました。安土城の城下で【楽市・楽座】を行い、座の特権をなくし、税を免除して、だれでも自由に商売できるようにしました。商工業をさかんにして、経済力を高めるためです。1582年、家臣の明智光秀にそむかれ、本能寺の変でたおれます。\n【豊臣秀吉】…信長のあとをついで、1590年に全国を統一しました。\n秀吉は【太閤検地】で、全国の田畑の広さや土地のよしあしを調べ、とれる米の量(【石高】)で表しました。そして、実際に耕す農民を検地帳に登録し、年貢を納める責任を負わせました。\n1588年には【刀狩】で、農民から刀や鉄砲などの武器を取り上げました。一揆を防ぎ、農民を農業に専念させるためです。\n検地と刀狩によって、武士と農民の身分がはっきり分かれました(【兵農分離】)。また、秀吉は朝鮮に2度兵を送りましたが、失敗に終わりました。\n信長・秀吉のころの文化を【桃山文化】といい、天守閣のある大きな城や、千利休が大成した【茶の湯】が代表です。',
        key: '太閤検地と刀狩で、武士と農民の身分が分かれた(兵農分離)。',
        ex: [{ q: '豊臣秀吉が刀狩を行ったねらいは何?2つ答えよう。', hint: '武器を持った農民が何を起こすおそれがあったかを考えます。', steps: ['戦国時代には、武器を持った農民が一揆を起こすことがあった。', '武器を取り上げれば、一揆を起こしにくくなる。これが1つ目のねらい。', '武器を手放した農民は、戦いに出ず、田畑を耕すことに専念する。', 'こうして年貢を確実に納めさせることが2つ目のねらい。結果として武士と農民の身分が分かれた。'], a: '①農民の一揆を防ぐこと。②農民を農業に専念させ、年貢を確実に納めさせること。(結果として兵農分離が進んだ)' }] },
      { h: '江戸幕府のしくみ', t: '【徳川家康】は1600年の【関ヶ原の戦い】に勝ち、1603年に征夷大将軍となって江戸幕府を開きました。\n幕府は、全国の大名を、徳川家の親類(【親藩】)、関ヶ原の戦いの前からの家臣(【譜代大名】)、関ヶ原のころから従った(【外様大名】)に分けました。信用できない外様大名は、江戸から遠い場所に置きました。\n1615年に【武家諸法度】を定め、大名が城を勝手に修理することや、大名どうしが勝手に結婚することを禁じました。大名どうしが手を組んだり、戦の準備をしたりするのを防ぐためです。\n3代将軍【徳川家光】は【参勤交代】を制度にしました。大名は1年おきに江戸と領地を行き来し、妻子は江戸に住まわせられました。\n将軍が直接治める土地(幕領)と、大名が治める土地(【藩】)とで、全国の土地と人々を支配するしくみを【幕藩体制】といいます。\n人々は、武士・百姓・町人などの身分に分けられました。百姓は村ごとに年貢を納め、【五人組】で年貢の納入や犯罪に連帯して責任を負わされました。',
        key: '幕府は、大名の配置・武家諸法度・参勤交代で大名の力をおさえ、長い平和を保った。',
        ex: [{ q: '参勤交代のねらいと、その結果どうなったかを説明しよう。', hint: '大名にとって、江戸との往復や江戸での生活は、お金がかかるかどうかを考えます。', steps: ['ねらい:大名に江戸と領地を往復させ、将軍に仕える姿勢を示させた。妻子を江戸に置かせたのは、人質の意味もある。', '大名行列や江戸での生活には多くの費用がかかり、大名の財政は苦しくなった。', 'その結果、大名は幕府に反抗するだけの力をたくわえにくくなった。', '一方で、大名行列が通る街道や宿場町が発達し、江戸と地方の文化の交流も進んだ。'], a: '大名を江戸と領地に往復させて将軍に従わせるため。費用がかかって大名の力がおさえられ、また街道や宿場町が発達した。' }] },
      { h: '鎖国:なぜ国を閉じたのか', t: '江戸時代の初め、家康は朱印状という許可証を与えて東南アジアとの貿易(朱印船貿易)をすすめていました。\nしかし、キリスト教の信者がふえると、幕府は「信者が神を将軍より大切にし、団結して幕府に従わなくなる」ことをおそれ、キリスト教を禁止しました。\n1637年、重い年貢とキリスト教の取りしまりに苦しんだ人々が【島原・天草一揆】を起こしました。幕府はこれをおさえると、さらに取りしまりを強め、キリストの像などを踏ませる【絵踏】で信者を見つけ出しました。\n1639年にポルトガル船の来航を禁止し、1641年にはオランダ商館を長崎の【出島】に移しました。こうして、幕府が貿易と外国の情報を独占する体制が完成しました。これを【鎖国】といいます。\nただし、まったく国を閉じたわけではありません。【長崎】(オランダ・中国)、【対馬藩】(朝鮮)、【薩摩藩】(琉球王国)、【松前藩】(蝦夷地のアイヌの人々)の4つの窓口で交流が続きました。朝鮮からは、将軍がかわるごとに【朝鮮通信使】が来ました。\nヨーロッパの国で、オランダだけが貿易を許されたのは、キリスト教を広めず、貿易だけを目的にしていたからです。',
        key: '鎖国のねらいは、キリスト教の禁止と、幕府による貿易・情報の独占。窓口は4つあった。',
        ex: [{ q: '鎖国の中で、ヨーロッパの国ではオランダだけが貿易を許されたのはなぜ?', hint: '幕府が一番おそれていたものは何かを思い出します。', steps: ['幕府は、キリスト教が広まって人々が幕府に従わなくなることをおそれていた。', 'ポルトガルやスペインは、貿易とあわせてキリスト教の布教を行っていた。', 'オランダはプロテスタントの国で、布教をせず、貿易だけを求めた。', 'そのため、布教の心配がないオランダだけが、出島で貿易を許された。'], a: 'オランダはキリスト教の布教をせず、貿易だけを目的にしていたから。' }] },
      { h: '産業の発達と幕府の財政難・三大改革', t: '平和が続くと、新田開発や農具の改良(備中ぐわ・千歯こきなど)で米の生産がふえました。江戸・大阪・京都の【三都】が栄え、「天下の台所」とよばれた大阪には諸藩の蔵屋敷が置かれ、年貢米が集まりました。\nところが、米がたくさんとれると米の値段は下がり、商品の値段は上がります。米を収入の中心とする幕府や武士は、だんだん生活が苦しくなりました。これが改革が必要になった理由です。\n【享保の改革】(8代将軍 徳川吉宗、1716年〜)…質素・倹約、新田開発、大名に米を納めさせる上げ米、裁判の基準となる【公事方御定書】、庶民の意見を聞く【目安箱】。\n【田沼意次の政治】(18世紀後半)…米だけにたよらず、商人の力を利用しようとした。【株仲間】を奨励して税を取り、長崎貿易をさかんにした。しかし、わいろが広がったと批判され、天明のききんも重なって失脚した。\n【寛政の改革】(老中 松平定信、1787年〜)…ききんに備えて米をたくわえさせ、旗本・御家人の借金を帳消しにし、朱子学以外の学問を幕府の学校で教えることを禁じた。きびしすぎて人々の反発をまねいた。\n【天保の改革】(老中 水野忠邦、1841年〜)…物価を下げるため株仲間を解散させ、ぜいたくを禁じたが、きびしすぎて反発をまねき、2年余りで失敗した。\nききんのときには、農村で【百姓一揆】、都市で米を買いしめた商人をおそう【打ちこわし】が多く起きました。',
        key: '米が中心の財政のままでは、商業の発達についていけない。改革はこの問題に、倹約(吉宗・定信・忠邦)か商業の利用(田沼)かで取り組んだ。',
        ex: [{ q: '次の政治を古い順に並べよう。ア 天保の改革 イ 田沼意次の政治 ウ 享保の改革 エ 寛政の改革', hint: '田沼の政治を「引きしめ直した」のはだれか、という因果を使います。', steps: ['享保の改革は8代将軍吉宗(18世紀前半)。', '田沼意次の商業重視の政治(18世紀後半)。', 'わいろ政治の批判とききんで田沼が失脚し、それを引きしめ直したのが松平定信の寛政の改革。', '19世紀前半に水野忠邦の天保の改革。'], a: 'ウ → イ → エ → ア', check: '1716 → 18世紀後半 → 1787 → 1841 と、年代が進んでいるか確かめましょう。' }] },
      { h: '江戸の文化と新しい学問', t: '【元禄文化】(17世紀末〜18世紀初め、5代将軍綱吉のころ)…経済力をつけた上方(大阪・京都)の町人が中心の文化です。\n井原西鶴が町人の暮らしを描いた浮世草子、近松門左衛門が人形浄瑠璃の脚本、【松尾芭蕉】が俳諧(俳句)を芸術に高めました。菱川師宣が浮世絵を始めました。\n【化政文化】(19世紀前半、文化・文政のころ)…江戸の町人が中心の文化です。\n【葛飾北斎】(富嶽三十六景)や【歌川広重】(東海道五十三次)の風景画の浮世絵が、多色刷りの版画で大量に刷られ、庶民も買えるようになりました。十返舎一九の「東海道中膝栗毛」などの読み物も人気になりました。\n新しい学問も生まれました。【国学】は、仏教や儒教が伝わる前の日本人の考え方を、古典から明らかにしようとする学問で、【本居宣長】が「古事記伝」を書きました。\n【蘭学】は、オランダ語の書物を通してヨーロッパの学問を学ぶものです。【杉田玄白】らがオランダ語の解剖書を翻訳して「解体新書」を出版し、【伊能忠敬】は全国を測量して正確な日本地図をつくりました。\n庶民の子どもは【寺子屋】で、読み・書き・そろばんを学びました。' },
      { h: '外国船の接近と幕府のゆらぎ', t: '18世紀の終わりごろから、外国の船が日本の近くに来るようになりました。1792年にはロシアの使節【ラクスマン】が根室に来て、通商を求めました。\n幕府は鎖国を守るため、1825年に【異国船打払令】を出し、日本に近づく外国船を砲撃して追い払うよう命じました。\n国内では、1830年代の【天保のききん】で多くの人がうえ死にし、一揆や打ちこわしが相次ぎました。1837年には、大阪町奉行所の元役人の【大塩平八郎】が、ききんに苦しむ人々を救おうとして大阪で乱を起こしました。幕府の元役人が反乱を起こしたことは、幕府に大きな衝撃を与えました。\n1840年、隣の清(中国)がイギリスとの【アヘン戦争】に敗れたことが伝わると、幕府は外国の強さを知り、1842年に異国船打払令をやめて、外国船に燃料や水を与えて帰らせる方針に改めました。\nこのように、19世紀前半の幕府は、国内のききんや一揆と、外国の圧力という2つの問題をかかえていました。天保の改革は、この危機を乗りこえようとしたものでしたが、失敗に終わります。\n一方、薩摩藩や長州藩などは、藩の財政を立て直す改革に成功して力をつけ、のちに幕府を倒す中心になっていきます。',
        ex: [{ q: '幕府が1842年に、異国船打払令をやめて、外国船に燃料や水を与える方針に変えたのはなぜ?', hint: '1840〜42年に、となりの国で何が起きたかを考えます。', steps: ['1840年から、清がイギリスとアヘン戦争を戦い、敗れた。', '大国の清が負けたことで、幕府はイギリスなど外国の軍事力の強さを知った。', '外国船を砲撃し続ければ、日本も清と同じように戦争になるおそれがある。', 'そこで、争いをさけるため、燃料や水を与えておだやかに帰らせる方針に改めた。'], a: 'アヘン戦争で清がイギリスに敗れたことを知り、外国船を打ち払えば日本も戦争に巻きこまれると考えたから。' }] }
    ],
    faq: [
      ['なぜ江戸時代は260年以上も平和が続いたの?', '大名が幕府に反抗できないしくみが、何重にもあったからです。\n親藩・譜代・外様の配置、武家諸法度による城の修理や結婚の制限、参勤交代による費用の負担と妻子の江戸住まいなどです。さらに、兵農分離で身分が固定され、社会が安定しました。'],
      ['田沼意次の政治は、なぜ「改革」とよばれないの?', '享保・寛政・天保の3つは、倹約や引きしめで幕府を立て直そうとした改革として、まとめて「三大改革」とよばれます。\n田沼の政治は、商業を利用する別の方向の政策で、わいろの批判もあったため、ふつうは「田沼の政治」とよび分けます。ただし、商業の発達に目を向けた点は新しい試みでした。'],
      ['鎖国中、日本は外国の情報をまったく知らなかったの?', 'いいえ。幕府は、長崎に来るオランダ商館長から「オランダ風説書」という報告を受け、世界の情報を集めていました。\nアヘン戦争の情報も、こうした窓口を通じて伝わりました。鎖国は、情報を幕府が独占するしくみでもあったのです。']
    ],
    terms: [['太閤検地', '豊臣秀吉が行った全国の田畑の調査。石高で土地を表した'], ['兵農分離', '検地や刀狩などで、武士と農民の身分を分けたこと'], ['武家諸法度', '大名が守るべききまり。城の修理や勝手な結婚を禁じた'], ['参勤交代', '大名が1年おきに江戸と領地を行き来した制度'], ['鎖国', 'キリスト教禁止と貿易統制のため、外国との交流を制限した体制'], ['株仲間', '商工業者の同業者組合。田沼は奨励し、水野は解散させた'], ['蘭学', 'オランダ語を通してヨーロッパの学問を学ぶこと']],
    miss: ['参勤交代を始めたのを家康と答える。制度にしたのは3代将軍家光。', '鎖国で「どこの国とも交流しなかった」と思う。4つの窓口(長崎・対馬・薩摩・松前)があった。', '株仲間を「奨励した田沼」と「解散させた水野」を逆に覚える。田沼は商業を利用、水野は物価を下げるために解散、と目的で区別する。', '元禄文化(上方)と化政文化(江戸)の中心地を逆にする。「元禄=上方が先、化政=あとから江戸」と、江戸の町が育った順で覚える。'],
    sum: ['信長・秀吉が統一し、太閤検地と刀狩で兵農分離が進んだ。', '江戸幕府は大名配置・武家諸法度・参勤交代で大名をおさえた。', '鎖国はキリスト教禁止と貿易の独占のため。窓口は4つ。', '米中心の財政が苦しくなり、享保 → 田沼 → 寛政 → 天保と政治が続いた。', '19世紀前半、ききん・一揆と外国船の接近で幕府がゆらいだ。'],
    next: '次は「近代(c_modern)」です。ペリーの来航で開国した日本が、江戸幕府を終わらせ、近代国家をつくっていく流れを学びます。'
  };

  L.c_modern = {
    goal: '開国から明治維新、条約改正、日清・日露戦争、大正デモクラシー、第二次世界大戦までの流れを、因果でつないで説明できるようになる。',
    intro: '近代は、日本が「欧米に追いつけ」と、短い期間で国のしくみを大きく変えた時代です。開国で不平等な条約を結ばされたことが出発点になり、「条約を対等にするには、欧米なみの強い近代国家にならなければ」という目標が、明治の改革や戦争を動かしました。できごとを「目標に向かって何をしたか」という1本の線でつなぎましょう。',
    pre: '江戸幕府は、キリスト教の禁止と貿易の独占のために【鎖国】を行い、長崎などの限られた窓口でだけ外国と交流していました。\n19世紀前半には外国船が日本に近づくようになり、1840年からのアヘン戦争で清(中国)がイギリスに敗れたことは、幕府に大きな衝撃を与えました。\nこのころのヨーロッパやアメリカは、【産業革命】で機械による大量生産ができるようになり、原料を手に入れ、製品を売る市場を求めて、アジアに進出していました。\n【条約】とは、国と国との約束を文書にしたものです。近代の日本を理解するカギは、開国のときに結んだ条約が「不平等」だったことです。',
    secs: [
      { h: '開国と江戸幕府のおわり', t: '1853年、アメリカの【ペリー】が4隻の軍艦を率いて浦賀に来航し、開国を求めました。アメリカは、太平洋を横断する船や捕鯨船の燃料・水の補給地を必要としていたのです。\n翌1854年の【日米和親条約】で、幕府は下田・函館を開港し、200年以上続いた鎖国が終わりました。\n1858年、大老【井伊直弼】は朝廷の許可を得ないまま【日米修好通商条約】を結び、函館・神奈川(横浜)・長崎・新潟・兵庫(神戸)を開いて貿易を始めました。\nこの条約は、外国人が日本で罪をおかしても日本の法律で裁けない【領事裁判権(治外法権)】を認め、日本に輸入品の関税を自由に決める【関税自主権】がない、【不平等条約】でした。\n開国で物価が上がり、天皇を尊び外国を追いはらおうとする【尊王攘夷運動】が高まります。しかし、外国と実際に戦って力の差を知った薩摩藩と長州藩は、攘夷は無理だと考えて倒幕へと方針を変え、1866年に坂本龍馬らの仲立ちで【薩長同盟】を結びました。\n1867年、15代将軍【徳川慶喜】は政権を朝廷に返す【大政奉還】を行い、朝廷は【王政復古の大号令】を出して天皇中心の新政府をつくりました。こうして約260年続いた江戸幕府は終わりました。',
        key: '日米修好通商条約は、領事裁判権を認め、関税自主権がない不平等条約。これを改めることが、明治の大きな目標になった。' },
      { h: '明治維新:天皇中心の中央集権国家へ', t: '新政府は、1868年に【五箇条の御誓文】で、会議を開いて広く意見を聞くことなど、新しい政治の方針を示しました。同じ年、江戸を東京と改め、年号を明治としました。\nしかし、全国にはまだ藩があり、大名が土地と人々を治めていました。これでは政府の命令が全国に届きません。\nそこで、【版籍奉還】(1869年)で、大名が治めていた土地(版)と人民(籍)を天皇に返させました。\nさらに【廃藩置県】(1871年)で藩をなくして府県を置き、中央の政府から府知事・県令を送りました。これで全国を政府が直接治める【中央集権国家】になりました。\n身分制度も改められ、皇族以外は華族・士族・平民とされ、平民も名字を名のり、職業や住む場所を自由に選べるようになりました。1871年には、えた・ひにんとよばれた人々を平民と同じにする布告が出されましたが、差別はその後も根強く残りました。\nこうした、江戸幕府の終わりから始まる一連の大きな改革を【明治維新】といいます。',
        key: '廃藩置県(1871年)で藩がなくなり、政府が全国を直接治める中央集権のしくみができた。',
        ex: [{ q: '明治政府が廃藩置県を行ったねらいは何?', hint: '藩が残っていると、政府の命令はどうなるかを考えます。', steps: ['版籍奉還のあとも、もとの大名が知藩事として藩を治め、実際の支配はあまり変わらなかった。', '藩が残っていると、税の取り方や軍隊も藩ごとにばらばらで、政府の命令が全国に届きにくい。', '藩をなくして府県を置き、中央から府知事・県令を送れば、政府が全国を直接治められる。', 'こうして、全国から税を集め、軍隊をつくる近代国家の土台ができた。'], a: '藩をなくして府県を置き、政府が任命した府知事・県令に治めさせることで、政府が全国を直接支配する中央集権国家をつくるため。' }] },
      { h: '富国強兵・殖産興業と文明開化', t: '欧米に負けない国になるため、政府は【富国強兵】(経済を発展させ、軍隊を強くする)を目標にかかげ、3つの大きな改革を行いました。\n【学制】(1872年)…6歳以上のすべての男女に小学校教育を受けさせることにした。国の発展を支える人を育てるため。\n【徴兵令】(1873年)…満20歳以上の男子に兵役を義務づけた。武士だけでなく、国民全体で軍隊をつくるため。\n【地租改正】(1873年)…土地の所有者に地券を発行し、収穫高ではなく【地価の3%】を【現金】で納めさせた。米の収穫は豊作・不作で変わるが、地価を基準にすれば毎年決まった税収が入る。ねらいは【国の財政を安定させること】だった。\n【殖産興業】として、政府はお金を出して官営の【富岡製糸場】(群馬県)などの工場をつくり、外国の技術を取り入れて産業をおこしました。鉄道(1872年、新橋〜横浜)や郵便制度も始まりました。\n都市では、れんがづくりの建物、ガス灯、洋服、牛なべなどの西洋の生活様式が広まりました。これを【文明開化】といいます。【福沢諭吉】は「学問のすゝめ」で、人間の平等と学ぶことの大切さを説きました。',
        key: '地租改正は、税を「収穫高に応じた米」から「地価の3%の現金」に変え、国の税収を安定させた。',
        ex: [{ q: '地租改正で、税のしくみはどう変わった?また、そのねらいは?', hint: '「何を基準に」「何で」「だれが」納めるかの3点で比べます。', steps: ['変わる前:収穫高に応じて、主に米で年貢を納めていた。', '変わった後:土地の所有者が、地価の3%を現金で納める。', '米の量は年によって変わるが、地価を基準にした現金なら毎年同じ額が入る。', 'だから政府は、毎年の予算を立てやすくなった。'], a: '収穫高に応じた米の年貢から、地価の3%を土地所有者が現金で納める税に変わった。ねらいは、国の税収を安定させること。', check: '地価100円の土地なら、豊作でも不作でも税は3円で変わらない、と具体的な数字で確かめられます。' }] },
      { h: '自由民権運動と立憲国家の成立・条約改正', t: '新政府は、薩摩・長州など一部の藩の出身者が中心でした(藩閥政府)。これに対し、1874年、板垣退助らが、国民の選んだ議員による議会(国会)を開くよう求める【民撰議院設立の建白書】を出しました。ここから【自由民権運動】が始まります。\n1877年の西南戦争で士族の武力による反乱が終わると、政府への批判は言論による運動が中心になり、全国に広がりました。政府は1881年に、10年後に国会を開くことを約束します。板垣退助は自由党、大隈重信は立憲改進党をつくって備えました。\n【伊藤博文】は、ヨーロッパで君主の権力が強いドイツ(プロイセン)の憲法を学びました。1885年に内閣制度をつくって初代の内閣総理大臣になり、1889年に【大日本帝国憲法】が発布されました。主権は天皇にあり、国民は「臣民」とされ、権利は法律の範囲内で認められました。\n1890年には第1回帝国議会が開かれ、日本は憲法と議会をもつ【立憲国家】になりました。ただし、衆議院議員の選挙権は、直接国税を15円以上納める満25歳以上の男子に限られ、人口の約1%にすぎませんでした。\n憲法と議会が整ったことで、欧米に「近代国家」と認められやすくなり、条約改正が進みました。1894年に外務大臣【陸奥宗光】が【領事裁判権の撤廃】に成功し、1911年に【小村寿太郎】が【関税自主権を完全に回復】しました。',
        key: '条約改正は、1894年の領事裁判権撤廃(陸奥宗光)と1911年の関税自主権回復(小村寿太郎)の2段階で実現した。',
        ex: [{ q: '条約改正が、大日本帝国憲法の発布や帝国議会の開設のあとに大きく進んだのはなぜ?', hint: '欧米が「不平等な条約を改めてもよい」と考える条件は何かを考えます。', steps: ['欧米は、日本の法律や裁判のしくみが整っていないことを理由に、領事裁判権を手放そうとしなかった。', '日本は憲法を定め、議会を開き、法律を整えた。', 'これで日本は、欧米と同じような近代的な法と政治のしくみをもつ国だと認められやすくなった。', 'その結果、1894年に領事裁判権が撤廃され、1911年には関税自主権も回復した。'], a: '憲法や議会、法律の整備によって、日本が欧米と同じ近代国家だと認められやすくなったから。' }] },
      { h: '日清戦争・日露戦争', t: '朝鮮をめぐって清と対立していた日本は、1894年、朝鮮で起きた農民の反乱(甲午農民戦争)をきっかけに、清と【日清戦争】を始めました。\n勝った日本は、【下関条約】(1895年)で、清に朝鮮の独立を認めさせ、多額の賠償金と、台湾・遼東半島などを得ました。賠償金の一部は、のちに【八幡製鉄所】の建設などに使われました。\nところが、ロシア・ドイツ・フランスが、遼東半島を清に返すよう求めました(【三国干渉】)。日本はこれを受け入れましたが、その後ロシアが遼東半島の一部を借りたため、ロシアへの反感が高まりました。\nロシアの南下に対抗するため、同じくロシアを警戒していたイギリスと、1902年に【日英同盟】を結びました。そして1904年、【日露戦争】が始まります。\n日本は苦戦の末に勝ち、アメリカの仲立ちで【ポーツマス条約】(1905年)を結んで、韓国での優越権や南樺太などを得ました。しかし賠償金が取れなかったため、重い税にたえてきた国民が不満を爆発させ、【日比谷焼き打ち事件】が起きました。\n日本は1910年に韓国を併合し(【韓国併合】)、朝鮮総督府を置いて植民地支配を行いました。\nこのころ日本でも【産業革命】が進み、軽工業(製糸・紡績)に続いて、重工業もおこりました。一方で、足尾銅山の鉱毒事件のような公害問題も起きました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 日英同盟 イ 三国干渉 ウ 韓国併合 エ 日露戦争', hint: '「ロシアへの反感が生まれる → 仲間をつくる → 戦う → 戦後」の順に考えます。', steps: ['日清戦争の講和(下関条約、1895年)の直後に三国干渉。ここでロシアへの反感が生まれる。', 'ロシアの南下に対抗するため、日英同盟(1902年)。', 'その2年後に日露戦争(1904年)。', '日露戦争で韓国への優越権を得て、韓国併合(1910年)。'], a: 'イ → ア → エ → ウ', check: '1895 → 1902 → 1904 → 1910 と、年号が小さい順になっているか確かめましょう。' }] },
      { h: '第一次世界大戦と大正デモクラシー', t: '1914年にヨーロッパで【第一次世界大戦】が始まると、日本は日英同盟を理由に参戦し、中国にあったドイツの拠点を攻めました。1915年には中国に【二十一か条の要求】を出し、その多くを認めさせたので、中国の人々の反発をまねきました。\nヨーロッパが戦場になったため、日本はアジアなどへの輸出がのびて好景気(【大戦景気】)になりました。一方で物価が上がり、人々の生活は苦しくなりました。\n1918年、ロシア革命に干渉するシベリア出兵を見こして米が買い占められ、米の値段が急に上がりました。怒った人々が米の安売りを求めて【米騒動】を起こし、全国に広がりました。\n米騒動の責任をとって内閣が退陣すると、【原敬】が、大臣の大部分を衆議院の第一党(立憲政友会)の党員で占める、初めての本格的な【政党内閣】をつくりました。\n吉野作造が、政治は民衆の意見にもとづいて行うべきだとする民本主義を説くなど、民主主義を求める動きが広がりました(【大正デモクラシー】)。女性の地位向上を求める平塚らいてうらの運動や、部落差別からの解放をめざす全国水平社(1922年)の運動も起こりました。\n1925年、満25歳以上のすべての男子に選挙権を与える【普通選挙法】が成立しました。同じ年、共産主義などを取りしまる【治安維持法】も定められました。',
        key: '1925年、普通選挙法(満25歳以上の男子)と治安維持法がセットで成立した。女性の選挙権はまだない。' },
      { h: '世界恐慌から第二次世界大戦へ', t: '1929年、アメリカから【世界恐慌】が広がり、日本も深刻な不景気(昭和恐慌)になりました。会社が倒産し、農村では生糸やまゆの値段が暴落して、人々は困りはてました。\n不景気からぬけ出す道を中国東北部(満州)に求めた軍(関東軍)は、1931年に【満州事変】を起こし、翌1932年に【満州国】をつくりました。国際連盟がこれを認めなかったため、日本は1933年に【国際連盟を脱退】し、国際的に孤立していきました。\n国内では、1932年の【五・一五事件】で犬養毅首相が暗殺されて政党内閣がとだえ、1936年の【二・二六事件】などで軍部の発言力がいっそう強まりました。\n1937年に【日中戦争】が始まり、1938年には【国家総動員法】で、議会の承認なしに国民や物資を戦争に動員できるようにしました。\n1939年、ドイツがポーランドに侵攻して【第二次世界大戦】が始まりました。日本は1940年に日独伊三国同盟を結び、1941年12月、ハワイの真珠湾などを攻撃して【太平洋戦争】が始まりました。\n戦争が長引くと、都市への空襲が激しくなり、1945年には沖縄で地上戦が行われ、多くの住民が犠牲になりました。8月には広島(6日)・長崎(9日)に原子爆弾が投下され、ソ連も日本に宣戦しました。日本は【ポツダム宣言】を受け入れて降伏し、8月15日に天皇がラジオで国民に伝えました。',
        key: '世界恐慌 → 満州事変 → 国際連盟脱退 → 日中戦争 → 太平洋戦争。不景気と国際的な孤立が、戦争への道を開いた。',
        ex: [{ q: '世界恐慌のあと、日本が国際的に孤立していった流れを、3つの段階で説明しよう。', hint: '「不景気 → 満州 → 国際連盟」の順にたどります。', steps: ['世界恐慌で日本も深刻な不景気になり、とくに農村が苦しんだ。人々の間に政党への不満が高まった。', '軍(関東軍)は、資源や土地を求めて中国東北部で満州事変を起こし、満州国をつくった。', '国際連盟が満州国を認めなかったため、日本は国際連盟を脱退し、国際的に孤立した。'], a: '世界恐慌による不景気 → 満州事変を起こし満州国をつくる → 国際連盟が満州国を認めず、日本は連盟を脱退して孤立した。' }] }
    ],
    faq: [
      ['領事裁判権と関税自主権、どちらが何の問題なの?', '領事裁判権は「裁判」の問題です。外国人が日本で罪をおかしても、日本の法律で裁けませんでした。\n関税自主権は「お金(貿易)」の問題です。輸入品にかける税を日本が自由に決められないので、安い外国製品が入ってきても、国内の産業を守れませんでした。\n撤廃・回復の順番は、領事裁判権(1894年)が先、関税自主権(1911年)があとです。'],
      ['なぜ伊藤博文はドイツの憲法を手本にしたの?', 'ドイツ(プロイセン)の憲法は、君主(皇帝)の権力が強いのが特徴だったからです。\n天皇を中心にした国のしくみを保ちながら、憲法と議会をもつ国にしたかった政府にとって、イギリスなどの議会の力が強い憲法より、ドイツの憲法のほうが合っていました。'],
      ['普通選挙法で、選挙権をもつ人はどのくらいふえたの?', '納める税の額による制限がなくなったので、有権者はそれまでの約4倍にふえ、人口の約20%になりました。\nただし女性には選挙権がなく、女性の参政権が実現したのは、戦後の1945年の選挙法改正です。']
    ],
    terms: [['不平等条約', '領事裁判権を認め、関税自主権がない条約'], ['廃藩置県', '1871年、藩をなくして府県を置き、中央集権のしくみをつくった改革'], ['地租改正', '1873年、地価の3%を土地所有者が現金で納める税にした改革'], ['自由民権運動', '国会の開設や憲法の制定を求めた、言論による運動'], ['三国干渉', 'ロシア・ドイツ・フランスが、遼東半島を清に返すよう求めたこと'], ['大正デモクラシー', '大正時代に広がった、民主主義を求める風潮'], ['普通選挙法', '1925年、満25歳以上のすべての男子に選挙権を与えた法']],
    miss: ['領事裁判権の撤廃(1894年・陸奥宗光)と関税自主権の回復(1911年・小村寿太郎)の順番や人物を取りちがえる。「裁判が先、お金があと」と覚える。', 'ポーツマス条約で賠償金を得たと思ってしまう。得られなかったので日比谷焼き打ち事件が起きた、と結果とセットで覚える。', '1925年の普通選挙法で女性にも選挙権が与えられたと思う。男子のみで、女性は戦後。', '大政奉還と王政復古の大号令の順を逆にする。慶喜が政権を返す(大政奉還)→ それを受けて新政府を宣言(王政復古)の順。'],
    sum: ['開国で結んだ不平等条約を改めることが、明治の大きな目標だった。', '廃藩置県・学制・徴兵令・地租改正で近代国家のしくみを整えた。', '自由民権運動を経て憲法と議会を整え、1894年と1911年に条約改正を達成。', '日清 → 三国干渉 → 日英同盟 → 日露 → 韓国併合 → 第一次大戦 → 米騒動 → 原敬内閣。', '世界恐慌 → 満州事変 → 国際連盟脱退 → 日中戦争 → 太平洋戦争。'],
    next: '次は「現代(c_contemp)」です。敗戦後の日本が、どのように民主化し、独立を回復し、経済大国へと成長したのかを学びます。'
  };

  L.c_contemp = {
    goal: '戦後の民主化から独立回復、高度経済成長、冷戦の終結と現代の課題までの流れを、「国内」と「外交」に分けて説明できるようになる。',
    intro: '1945年の敗戦から、日本は国のしくみを大きく作りかえました。その後、焼け野原から世界有数の経済大国へと成長します。この時代は、国内の動き(民主化・経済)と、外交の動き(独立・国交回復)が、【冷戦】という世界の大きな対立と深く関わっています。2本の線に分けて整理すると、ぐっと分かりやすくなります。',
    pre: '1945年8月、日本はポツダム宣言を受け入れて降伏し、第二次世界大戦が終わりました。都市の多くは空襲で焼け、食料や物資が大きく不足していました。\n戦前の日本では、大日本帝国憲法のもとで主権は天皇にあり、軍部が政治に強い力をもっていました。また、女性には選挙権がありませんでした。\n経済では、三井・三菱などの【財閥】とよばれる大企業の集団が大きな力をもち、農村では多くの農民が地主から土地を借りる【小作人】でした。\n戦後の改革は、こうした「戦争へ向かったしくみ」を取りのぞくことをねらいとしていました。この点をおさえると、改革の中身が理由ごと分かります。',
    secs: [
      { h: '占領と戦後の民主化', t: '敗戦後、日本はマッカーサーを最高司令官とする【GHQ(連合国軍総司令部)】の占領下に置かれました。GHQは、日本が二度と戦争をしない国になるよう、【非軍事化】と【民主化】を進めました。\n軍隊は解散させられ、戦争の指導者は極東国際軍事裁判(東京裁判)で裁かれました。\n【財閥解体】…経済を支配し、戦争にも協力した大企業の集団を解体した。\n【農地改革】…政府が地主の土地を買い上げ、小作人に安く売りわたした。その結果、多くの【自作農】(自分の土地を耕す農民)が生まれ、地主が農村を支配するしくみがくずれた。\n1945年に選挙法が改正され、満20歳以上の【男女】に選挙権が与えられました(女性の参政権が初めて実現)。翌年の総選挙では、39人の女性議員が誕生しました。\n1946年11月3日に【日本国憲法】が公布され、1947年5月3日に施行されました。【国民主権・基本的人権の尊重・平和主義】が三大原則です。\nほかにも、民主的な教育のための【教育基本法】や、労働者の団結を認める【労働組合法】などが定められました。',
        key: '戦後改革の柱は、財閥解体・農地改革・男女普通選挙・日本国憲法。ねらいは非軍事化と民主化。',
        ex: [{ q: '農地改革で、農村はどう変わった?', hint: '改革の前、多くの農民はだれの土地を耕していたかを考えます。', steps: ['改革前:多くの農民は地主から土地を借りる小作人で、収穫の多くを小作料として納めていた。', '改革:政府が地主の土地を買い上げ、小作人に安く売りわたした。', '結果:自分の土地を耕す自作農が大幅にふえ、地主の力が弱まった。'], a: '地主の土地が小作人に安く売りわたされ、自作農が大幅にふえて、地主が農村を支配するしくみがくずれた。' }] },
      { h: '冷戦の始まりと占領政策の転換', t: '戦後の世界は、アメリカを中心とする資本主義の国々(西側)と、ソ連を中心とする社会主義の国々(東側)が対立するようになりました。直接大きな戦争はしないものの、きびしくにらみ合ったので【冷戦】(冷たい戦争)とよばれます。\nドイツは東西に分かれ、アジアでは1949年に中国で共産党の【中華人民共和国】が成立しました。\nこうした中で、アメリカは日本を「西側の重要な国」と考えるようになり、占領政策を、民主化中心から【経済の立て直し】中心へと切りかえました。\n1950年、朝鮮半島で北朝鮮と韓国の間に【朝鮮戦争】が始まりました。日本にいたアメリカ軍が出動したため、GHQの指示で、国内の治安を守る【警察予備隊】がつくられました。これが保安隊を経て、1954年に【自衛隊】になります。\nまた、アメリカ軍が戦争に使う物資を日本に大量に注文したため、日本は好景気(【特需景気】)になり、経済の復興が早まりました。',
        ex: [{ q: '朝鮮戦争は、日本にどんな影響を与えた?2つ答えよう。', hint: '「経済」と「防衛(安全保障)」の2つの面から考えます。', steps: ['経済:日本にいたアメリカ軍が、戦争に必要な物資を日本の企業に大量に注文した。', 'その結果、日本は特需景気とよばれる好景気になり、経済の復興が進んだ。', '防衛:日本にいたアメリカ軍が朝鮮半島に出動したため、国内の治安を守る組織が必要になった。', 'GHQの指示で警察予備隊がつくられ、のちに自衛隊になった。'], a: '①アメリカ軍の物資の注文で特需景気が起き、経済の復興が進んだ。②警察予備隊がつくられた(のちの自衛隊)。' }] },
      { h: '独立の回復と国際社会への復帰', t: '冷戦が深まると、アメリカは日本を早く独立させ、西側の一員にしようとしました。\n1951年、【吉田茂】内閣は、アメリカなど48か国と【サンフランシスコ平和条約】を結び、翌1952年に独立を回復しました。ただし、ソ連などは調印せず、中国は会議に招かれませんでした。\n平和条約と同じ日に【日米安全保障条約】を結び、独立後もアメリカ軍が日本にとどまることになりました。\n独立は回復しましたが、【沖縄】や小笠原諸島などは、引き続きアメリカの統治下に残されました。\n1956年に【日ソ共同宣言】でソ連と国交を回復すると、それまで日本の国連加盟に反対していたソ連が賛成にまわり、同じ年に日本は【国際連合に加盟】し、国際社会に復帰しました。\nなお、日ソ共同宣言のあとも平和条約は結ばれておらず、北方領土の問題は今も解決していません。',
        key: 'サンフランシスコ平和条約(1951年)で独立、日ソ共同宣言(1956年)でソ連の賛成を得て同じ年に国連加盟。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 国際連合への加盟 イ サンフランシスコ平和条約 ウ 沖縄の日本復帰 エ 日ソ共同宣言', hint: '「国連加盟にはソ連の賛成が必要だった」という因果を使います。', steps: ['サンフランシスコ平和条約は1951年(独立回復は翌年)。', '日ソ共同宣言は1956年。ソ連との国交が回復した。', 'そのためソ連が賛成し、同じ1956年に国連加盟。', '沖縄の日本復帰は1972年。'], a: 'イ → エ → ア → ウ', check: '1951 → 1956 → 1956 → 1972 で、同じ年の2つは「国交回復 → 加盟」の因果で順番が決まります。' }] },
      { h: '高度経済成長とその影', t: '1950年代半ばから1973年ごろまで、日本の経済は年平均で約10%という急成長を続けました(【高度経済成長】)。\n成長の理由には、新しい技術を取り入れた工場への投資、農村から都市へ働きに出た多くの若い労働力、安い石油、そして国民の高い貯蓄などがありました。1960年には池田勇人内閣が「所得倍増」をかかげました。\n1964年には【東京オリンピック】が開かれ、それに合わせて東海道新幹線が開通しました。家庭には、白黒テレビ・洗濯機・冷蔵庫の「三種の神器」が広まり、のちにはカラーテレビ・クーラー・自動車(3C)が広まりました。1968年には、国民総生産(GNP)が資本主義国でアメリカに次ぐ第2位になりました。\n一方で、工場の排水やけむりによる【公害】が深刻になり、水俣病・新潟水俣病・イタイイタイ病・四日市ぜんそくの【四大公害病】が起きました。政府は1967年に公害対策基本法を定め、1971年に環境庁をつくりました。\nまた、都市では人口が集中して過密になり、農村では若い人が出ていって過疎が進みました。',
        key: '高度経済成長は、生活を豊かにした一方で、公害や過密・過疎という問題を生んだ。' },
      { h: '外交の広がりと石油危機', t: '経済成長と並行して、日本は近隣の国々との関係を整えていきました。\n1965年、韓国と【日韓基本条約】を結び、韓国政府を朝鮮半島の唯一の合法的な政府と認めて国交を正常化しました。\n1972年、佐藤栄作内閣のときに【沖縄が日本に復帰】しました。しかし、復帰後もアメリカ軍の基地の多くが沖縄に残され、今も課題になっています。\n同じ1972年、田中角栄首相が中国を訪問して【日中共同声明】を出し、中国との国交を正常化しました。1978年には【日中平和友好条約】が結ばれました。\n1973年、中東での戦争(第四次中東戦争)をきっかけに、石油の価格が急に上がる【石油危機(オイル・ショック)】が起きました。安い石油にたよって成長してきた日本の経済は打撃を受け、翌年には戦後初めてのマイナス成長になり、高度経済成長は終わりました。\nその後、日本の企業は省エネルギーの技術を進め、自動車や電子機器の輸出をのばして、安定成長の時代に入りました。',
        ex: [{ q: '高度経済成長が1973年ごろに終わったのはなぜ?', hint: '日本の経済成長を支えていたエネルギーは何だったかを考えます。', steps: ['高度経済成長は、中東などから輸入する安い石油をエネルギーにして、工場を動かすことで支えられていた。', '1973年、中東での戦争をきっかけに、産油国が石油の値段を大きく引き上げた(石油危機)。', '石油の値段が上がると、工場で物をつくる費用が上がり、物価も急に上がった。', '企業の生産がのびなくなり、翌年には戦後初のマイナス成長となって、高い成長が続かなくなった。'], a: '1973年の石油危機で、成長を支えていた安い石油が手に入らなくなり、物価の上昇と生産の落ちこみが起きたから。' }] },
      { h: '冷戦の終結と現代の日本', t: '1989年、東西対立の象徴だった【ベルリンの壁】がこわされ、同じ年、地中海のマルタ島で米ソの首脳が会談して【冷戦の終結】を宣言しました。1990年に東西ドイツが統一し、1991年にソ連が解体しました。\n冷戦が終わると、世界では民族や宗教の対立による地域紛争やテロが目立つようになりました。日本は1992年にPKO協力法を定め、国連の平和維持活動に自衛隊を派遣するようになりました。\n日本では、1980年代後半に株や土地の値段が実際の価値以上に異常に上がる【バブル経済】が起き、1990年代の初めに崩壊して、長い不景気が続きました。\n1995年の【阪神・淡路大震災】、2011年の【東日本大震災】では大きな被害が出て、ボランティア活動の広がりや、防災の大切さが見直されました。\n現在の日本は、【少子高齢化】、地球環境問題、グローバル化への対応、国の財政赤字などの課題をかかえています。歴史で学んだ「原因 → 結果」の考え方は、こうした今の課題を考えるときにも役立ちます。' }
    ],
    faq: [
      ['なぜアメリカは、日本の占領政策を途中で変えたの?', '冷戦が始まり、中国で共産党の政府ができるなど、アジアで社会主義の勢力が広がったからです。\nアメリカは、日本を経済的に強くして、アジアにおける西側の拠点にしようと考えました。そのため、民主化中心から経済の立て直し中心へと方針を切りかえたのです。'],
      ['日中共同声明と日中平和友好条約は、どうちがうの?', '日中共同声明(1972年)は、日本と中国の国交を正常化した宣言です。\n日中平和友好条約(1978年)は、その上で、両国の平和と友好の関係を条約として確かなものにしたものです。順番は「国交正常化 → 条約」です。'],
      ['バブル経済の「バブル」って何のこと?', 'バブルは「あわ」のことです。株や土地の値段が、実際の価値をこえてふくらみ、あわのようにいつかはじけてしまう状態をたとえています。\n値段が上がり続けると信じた人々が、借金をしてまで株や土地を買ったため、値段が下がり始めると、多くの企業や銀行が大きな損をかかえました。']
    ],
    terms: [['GHQ', '連合国軍総司令部。戦後の日本を占領し、民主化を指示した'], ['財閥解体', '経済を支配していた大企業の集団を解体した改革'], ['農地改革', '地主の土地を小作人に安く売りわたし、自作農をふやした改革'], ['冷戦', 'アメリカ中心の西側とソ連中心の東側の、直接戦火を交えない対立'], ['サンフランシスコ平和条約', '1951年、日本が連合国の多くと結んだ講和条約。翌年独立を回復'], ['高度経済成長', '1950年代半ばから1973年ごろまでの、日本経済の急成長'], ['石油危機', '1973年、石油価格の急上昇で世界経済が混乱したこと'], ['バブル経済', '1980年代後半、株や土地の値段が異常に上がった好景気']],
    miss: ['サンフランシスコ平和条約で沖縄も返ったと思う。沖縄の復帰は1972年で、それまではアメリカの統治下だった。', '国連加盟を平和条約と同じ年と思う。加盟には常任理事国ソ連の賛成が必要で、日ソ共同宣言と同じ1956年。', '日中共同声明(1972年)と日中平和友好条約(1978年)を混同する。「声明で国交 → 条約で友好」の順。', '女性の参政権を日本国憲法の施行(1947年)で始まったと思う。選挙法の改正は1945年で、憲法より前。'],
    sum: ['戦後改革:財閥解体・農地改革・男女普通選挙・日本国憲法。', '冷戦と朝鮮戦争で占領政策が変わり、特需景気と警察予備隊が生まれた。', '1951年に平和条約と安保条約、1956年の日ソ共同宣言で国連加盟。', '高度経済成長は石油危機(1973年)で終わり、公害や過密・過疎が課題に。', '1989年に冷戦が終結、1991年にソ連が解体。日本はバブル崩壊後の長い不景気へ。'],
    next: '中学の歴史を一通り学んだら、「歴史の総まとめ(c_m2)」で、時代の順番と各時代の特徴を1枚の地図のように整理しましょう。'
  };

  L.c_m2 = {
    goal: '時代の順番と各時代の特徴をつかみ、できごとや文化を正しい時代に当てはめて並べかえられるようになる。',
    intro: '歴史の問題でいちばん多いのは、「どれが先?」という並べかえです。年号を全部覚えていなくても、【時代の順番】と【各時代の特徴】(だれが政治をしたか、都はどこか、どんな文化か)が分かっていれば、ほとんどの問題は解けます。この単元は、中学歴史全体の「地図」をつくるつもりで読みましょう。',
    pre: '日本の歴史は、時代の名前で区切って学びます。時代の名前は、政治の中心地(奈良・平安・鎌倉・室町・江戸など)や、その時代の特徴(縄文土器・弥生土器・古墳など)、元号(明治・大正・昭和など)からつけられています。\n年は【西暦】で表します。西暦1年より前を【紀元前】といい、紀元前は、さかのぼるほど数字が大きくなります。\n100年ごとの区切りが【世紀】です。たとえば「16世紀」は1501〜1600年のことです。\nできごとどうしには、「Aが原因でBが起きた」という【因果関係】があることが多く、これが並べかえの最大の手がかりになります。',
    secs: [
      { h: '時代の順番を口で言えるようにする', t: '旧石器 → 縄文 → 弥生 → 古墳 → 飛鳥 → 奈良 → 平安 → 鎌倉 → 室町(南北朝・戦国をふくむ)→ 安土桃山 → 江戸 → 明治 → 大正 → 昭和 → 平成 → 令和\nこれを、何も見ずに口で言えるまで練習します。並べかえ問題は、まず「どの時代か」が分かれば、ほとんど解けるからです。\n大きなまとまりでは、【原始・古代】(〜平安)、【中世】(鎌倉・室町)、【近世】(安土桃山・江戸)、【近代】(明治〜第二次世界大戦の終わり)、【現代】(戦後)に分けます。\n都(政治の中心地)の移り変わりも、時代とセットにします:飛鳥 → 平城京(奈良)→ 平安京(京都)→ 鎌倉 → 京都(室町)→ 安土・大阪 → 江戸 → 東京。\n各時代の始まりのできごとを1つずつ言えるようにすると、さらに強くなります。例:奈良=710年平城京、平安=794年平安京、鎌倉=1185年守護・地頭(1192年将軍)、江戸=1603年家康が将軍に。',
        key: '時代の順番を口で言えることが、並べかえ問題の出発点。' },
      { h: '世紀の数え方', t: 'なぜ1600年は17世紀ではなく16世紀なのでしょうか。1世紀が「1年〜100年」で、0年から始まらないからです。100年目までが1世紀なので、100の倍数の年は、その世紀の最後の年になります。\nだから、【下2けたが00でなければ、百の位より上の数に1を足す】。例:1543年 → 15+1=16世紀。\n【下2けたが00なら、そのまま】。例:1600年 → 16世紀(16世紀の最後の年)。\n紀元前(B.C.)も同じように数えますが、さかのぼるほど数が大きくなります。紀元前221年は、紀元前3世紀です。\n「〇世紀前半」は前の50年、「〇世紀後半」は後ろの50年です。19世紀後半なら1851〜1900年です。',
        key: '下2けたが00でなければ百の位より上に+1、00ならそのまま。',
        ex: [
          { q: '1192年、1600年、1868年は、それぞれ何世紀?', hint: 'まず下2けたが00かどうかを確かめます。', steps: ['1192年:下2けたは92(00でない)→ 11+1=12世紀。', '1600年:下2けたが00 → そのまま16世紀。', '1868年:下2けたは68 → 18+1=19世紀。'], a: '12世紀、16世紀、19世紀', check: '12世紀は1101〜1200年なので、1192年はその中に入っています。' },
          { q: '秦の始皇帝が中国を統一した紀元前221年は、紀元前何世紀?', hint: '紀元前でも、数え方は西暦と同じです。', steps: ['紀元前1世紀は紀元前100年〜紀元前1年。紀元前でも100年ずつ区切る。', '221は下2けたが21(00でない)なので、百の位の2に1を足して3。', 'だから紀元前3世紀(紀元前300年〜紀元前201年)。'], a: '紀元前3世紀', check: '紀元前300年〜紀元前201年の間に221が入っていることを確かめましょう。' }
        ] },
      { h: '政治の中心の移り変わり', t: '時代ごとに「だれが政治の中心にいたか」を追うと、時代の特徴がはっきりします。\n大王と豪族(古墳)→ 天皇と貴族による律令政治(飛鳥・奈良)→ 藤原氏の摂関政治(平安中期)→ 上皇の院政(平安後期)→ 平氏政権\n→ 鎌倉幕府(将軍、のちに北条氏の執権)→ 室町幕府(将軍と守護大名)→ 戦国大名 → 織田・豊臣の統一政権 → 江戸幕府(将軍と大名の幕藩体制)\n→ 明治政府(薩長などの藩閥)→ 政党内閣(大正〜昭和初期)→ 軍部の台頭(昭和戦前)→ 戦後は国民主権の民主政治(日本国憲法)\n政治の担い手が交代するときには、必ず「前の担い手が力を失った理由」があります。例:元寇で恩賞が出せず御家人の不満が高まった → 鎌倉幕府がほろびた。\nこの「交代の理由」を説明できると、記述問題にも強くなります。' },
      { h: '文化で時代を見分ける', t: '文化の名前と時代をセットにすると、並べかえの強い手がかりになります。文化は、その時代に力をもった人々の好みを映しているからです。\n【飛鳥文化】(飛鳥・法隆寺、日本初の仏教文化)→【天平文化】(奈良・東大寺の大仏、正倉院、唐の影響)→【国風文化】(平安・かな文字、源氏物語、日本風)\n→【鎌倉文化】(武士の力強い文化、金剛力士像)→【北山文化】(室町・金閣、能)→【東山文化】(室町・銀閣、書院造、水墨画)\n→【桃山文化】(安土桃山・天守閣のある城、茶の湯)→【元禄文化】(江戸前期・上方の町人)→【化政文化】(江戸後期・江戸の町人、浮世絵)\n担い手で見ると、貴族(飛鳥〜国風)→ 武士(鎌倉〜桃山)→ 町人(元禄・化政)と移っていきます。\n人物も、その人が生きた時代とセットで覚えましょう。例:紫式部=平安、雪舟=室町、松尾芭蕉=江戸(元禄)。',
        ex: [{ q: '次の文化を古い順に並べよう。ア 元禄文化 イ 国風文化 ウ 北山文化 エ 天平文化', hint: 'それぞれの文化が「どの時代」かを先に決めます。', steps: ['天平文化は奈良時代(聖武天皇のころ)。', '国風文化は平安時代(遣唐使の停止後)。', '北山文化は室町時代(足利義満)。', '元禄文化は江戸時代前期。'], a: 'エ → イ → ウ → ア', check: '奈良 → 平安 → 室町 → 江戸 と、時代の順番どおりになっています。' }] },
      { h: '外国とのつながりの流れ', t: '外交(外国とのつきあい)も、1本の流れにしておくと、並べかえの手がかりになります。\n古代:遣隋使(飛鳥)→ 遣唐使(飛鳥〜平安)→ 遣唐使の停止(894年)\n中世:日宋貿易(平清盛)→ 元寇(1274・1281年)→ 日明貿易(勘合貿易、足利義満)\n近世:南蛮貿易(ポルトガル・スペイン)→ 朱印船貿易(江戸初期)→ 鎖国(4つの窓口)→ 外国船の接近\n近代:開国(1854年・1858年)→ 条約改正(1894年・1911年)→ 日清・日露戦争 → 国際連盟脱退(1933年)→ 太平洋戦争\n現代:サンフランシスコ平和条約(1951年)→ 国連加盟(1956年)→ 日韓基本条約(1965年)→ 日中共同声明(1972年)\n外交は国内の政治と結びついています。たとえば、鎖国はキリスト教の禁止のため、開国は外国の軍事的な圧力のため、という理由もセットで覚えましょう。',
        ex: [{ q: '次の貿易を古い順に並べよう。ア 日明貿易 イ 朱印船貿易 ウ 日宋貿易 エ 南蛮貿易', hint: '貿易を行った人物や国から、時代を決めます。', steps: ['日宋貿易は、平安時代の終わりに平清盛が行った。', '日明貿易(勘合貿易)は、室町時代に足利義満が始めた。', '南蛮貿易は、16世紀にポルトガル人・スペイン人が来るようになってから(戦国〜安土桃山)。', '朱印船貿易は、江戸時代の初めに徳川家康が許可証を与えてすすめた。'], a: 'ウ → ア → エ → イ' }] },
      { h: '並べかえ問題と記述問題の解き方', t: '並べかえ問題は、次の3段階で考えます。\n①まず、それぞれのできごとが【どの時代】かを決める。時代がちがえば、それで順番が決まります。\n②同じ時代の中なら、【原因 → 結果】の関係で並べる。例:元寇 → 御家人の生活苦 → 徳政令。\n③それでも迷ったら、年号を思い出す。年号は最後の手段です。\n「なぜ〜したのか」という記述問題には、「背景(どんな状況だったか)→ できごと → ねらい・結果」の順で答えると、筋の通った答えになります。\n記述では、教科書に出てくる重要語句(例:御恩と奉公、公地公民)を使うと、採点者に伝わりやすくなります。',
        key: '並べかえは「時代 → 因果 → 年号」の順で考える。',
        ex: [{ q: '徳川慶喜が大政奉還を行ったのはなぜ?', hint: '当時、薩摩藩・長州藩はどんな動きをしていたかを考えます。', steps: ['背景:薩摩藩・長州藩が薩長同盟を結び、武力で幕府を倒そうとする動きが強まっていた。', '慶喜は、このまま戦えば幕府が武力で倒されると考えた。', 'ねらい:自分から政権を朝廷に返せば、倒幕の理由をなくせる。新しい政治の中でも、最大の大名である徳川家の影響力を残そうとした。'], a: '倒幕の動きが強まる中、武力で倒される前に政権を朝廷に返し、新しい政治の中でも徳川家の力を保とうとしたから。' }] }
    ],
    faq: [
      ['年号はどこまで覚えればいいの?', '全部を覚える必要はありません。まずは各時代の始まりと、大きな転換点(645・710・794・1192・1338・1467・1603・1868・1945など)を覚えましょう。\nこれが「目印」になり、ほかのできごとは「目印の少し前か後か」と、因果の流れで位置を決められます。'],
      ['「中世」「近世」はどこで区切るの?', '中学では、鎌倉時代と室町時代を中世、安土桃山時代と江戸時代を近世とするのが一般的です。\n中世は「武士が力をのばし、支配が各地に分かれていた時代」、近世は「全国が統一され、1つの政権のもとで平和が続いた時代」と、特徴で区別すると覚えやすいです。'],
      ['南北朝や戦国は、独立した時代なの?', '多くの教科書では、南北朝時代と戦国時代は、室町時代の中にふくめて考えます。\nどちらも室町幕府があった時期ですが、南北朝は朝廷が2つに分かれていた時期、戦国は幕府の力が弱まり戦国大名が争った時期、という特徴でよび分けています。']
    ],
    terms: [['時代区分', '歴史を、特徴によっていくつかの時代に分けること'], ['世紀', '100年ごとの区切り。1世紀は1〜100年'], ['紀元前', '西暦1年より前。B.C.と書く'], ['中世', '鎌倉・室町時代。武士が力をのばした時代'], ['近世', '安土桃山・江戸時代。全国が統一された時代'], ['因果関係', 'あるできごと(原因)が別のできごと(結果)を引き起こす関係']],
    miss: ['1600年を17世紀と答える。100の倍数の年はその世紀の最後の年なので、そのまま16世紀。', '北山文化(金閣)と東山文化(銀閣)を逆にする。将軍の順(3代義満 → 8代義政)と同じく、北山が先。', '年号の数字だけで並べようとして、時代の判断をとばしてしまう。まず時代を決めれば、年号を忘れていても解ける。', '紀元前の数字が大きいほど新しいと思う。紀元前は、数字が大きいほど古い。'],
    sum: ['時代の順番は、口で言えるまで練習する。', '世紀は「下2けたが00でなければ百の位より上に+1」。', '政治の担い手・文化・外交を、それぞれ1本の流れにする。', '文化名と時代、人物と時代はセットで覚える。', '並べかえは「時代 → 因果 → 年号」の順で考える。'],
    next: '次は「難関:中学社会(歴史の流れと因果関係)cx_jh3」に挑戦しましょう。年代の近いできごとの並べかえや、「その結果どうなったか」を、因果の鎖で解く練習をします。'
  };

  L.cx_jh3 = {
    goal: '難関校レベルの、年代の近いできごとの並べかえや「その結果どうなったか」を問う問題を、因果の流れから解けるようになる。',
    intro: '難関校の歴史は、年号を覚えているだけでは解けない問題が出ます。「Aの結果、何が起きたか」「BとC、どちらが先か(数年しかちがわない)」という問いです。これらは、できごとを【原因 → 結果】の矢印でつないで覚えていれば、年号を忘れても筋道で答えられます。この単元では、入試によく出る因果の鎖を練習します。',
    pre: '【因果関係】とは、「Aが起きたから、Bが起きた」という原因と結果のつながりのことです。歴史のできごとは、ほとんどがこのつながりの中にあります。\n原因には、長い間たまっていた問題である【背景】と、直接の引き金になった【きっかけ】の2種類があります。たとえば、鎌倉幕府の滅亡の背景は御家人の生活苦、きっかけは後醍醐天皇の挙兵です。\n結果にも、すぐに起きた【直後の変化】と、長い時間をかけて表れた【長期の影響】の2種類があります。\nこの単元は、中学歴史の時代の順番(c_m2)を知っていることを前提にしています。時代の順番に自信がない人は、先にそちらで確認しておきましょう。',
    secs: [
      { h: '因果の鎖をつくる3つの型', t: '因果は、次の3つの型でとらえると整理しやすくなります。型を知っていると、初めて見るできごとでも「たぶんこうつながる」と予想できます。\n【型1:しくみがくずれる】…土地やお金のしくみが変わり、支配がゆらぐ。例:墾田永年私財法 → 荘園の広がり → 公地公民の崩壊。元寇 → 恩賞不足 → 御恩と奉公の崩壊 → 鎌倉幕府の滅亡。\n【型2:外の動き → 国内の変化】…外交や戦争が国内の政治や経済を変える。例:開国 → 物価上昇 → 尊王攘夷 → 倒幕。世界恐慌 → 不景気 → 軍部の台頭。\n【型3:失敗 → 次の改革】…前の政治への反省から次の政治が生まれる。例:田沼の政治(わいろ・ききん)→ 寛政の改革。建武の新政(武士の不満)→ 室町幕府。\n年表を見たら、できごとどうしを矢印でつないでみる習慣をつけましょう。矢印の間に「なぜ」を一言書きこむと、記述問題の答えがそのままできあがります。',
        key: '因果の3つの型:しくみがくずれる/外の動き → 国内の変化/失敗 → 次の改革。',
        ex: [{ q: '次のA・Bの因果の鎖は、3つの型のどれにあたる?\nA「アヘン戦争で清がイギリスに敗れる → 幕府が異国船打払令をやめる」\nB「太閤検地で、1つの土地の耕作者を1人に決める → 荘園のしくみが消える」', hint: '鎖の出発点が「外国のできごと」か「国内のしくみの変化」かに注目します。', steps: ['A:出発点は、となりの国・清で起きた戦争(外の動き)。', 'その情報を受けて、幕府が外国船への方針(国内の政治)を変えた → 型2(外の動き → 国内の変化)。', 'B:出発点は、土地を調べて耕作者を決めるという、土地のしくみの変更。', 'その結果、貴族や寺社が土地から年貢を取る荘園のしくみがなくなった → 型1(しくみがくずれる)。'], a: 'A=型2(外の動き → 国内の変化)、B=型1(しくみがくずれる)', check: '鎖の「最初の矢印の出発点」がどこにあるかを言いかえてみると、型の判断が確かめられます。' }] },
      { h: '古代〜中世の「その結果」の鎖', t: '古代・中世でよく問われる鎖を、「直後」と「長期」に分けて整理します。\n【墾田永年私財法(743年)】直後:貴族や寺社が開墾を進める。長期:私有地が荘園となり、公地公民がくずれる。さらに荘園を守るために武装する人々が現れ、武士の成長につながる。\n【承久の乱(1221年)】直後:六波羅探題を置いて朝廷を監視する。長期:上皇方の土地に東国の御家人が地頭として入り、幕府の支配が西日本に広がる。\n【元寇(1274・1281年)】直後:御家人に十分な恩賞を与えられない。長期:御家人の生活苦 → 徳政令(1297年)→ 幕府への不満 → 鎌倉幕府の滅亡(1333年)。\n【応仁の乱(1467年)】直後:京都が焼け、幕府の力が失われる。長期:下剋上が広がり、戦国大名が各地を支配する戦国時代になる。\nこのように、1つのできごとが、何十年、何百年先の大きな変化の出発点になっていることがよくあります。',
        ex: [{ q: '応仁の乱(1467年)の結果を、「直後の変化」と「長期の影響」に分けて説明しよう。', hint: '乱の舞台がどこだったか、そのあと各地で何が起きたかを考えます。', steps: ['応仁の乱は、将軍のあとつぎ問題と守護大名の対立から起き、京都が主な戦場になった。', '直後:11年続いた戦いで京都は焼け野原になり、将軍・幕府の力はほとんど失われた。', '守護大名が京都で戦っている間に、地元では家来などが実力をつけた。', '長期:下の者が上の者を倒す下剋上が広がり、実力で国を治める戦国大名が争う戦国時代になった。'], a: '直後:京都が焼け、幕府の力が失われた。長期:下剋上の風潮が広がり、戦国大名が各地を支配する戦国時代になった。' }] },
      { h: '年代の近いできごと:幕末の鎖', t: '数年しかちがわないできごとは、「なぜ起きたか」から順番を決めます。幕末は、とくに数年おきに大きなできごとが続く時期です。\n日米修好通商条約(1858年)→ 安政の大獄(1858〜59年)→ 桜田門外の変(1860年)\n条約を朝廷の許可なく結んだ井伊直弼に、反対する大名・公家・武士が多くいました。井伊は彼らをきびしく処罰しました(安政の大獄)。その反発から、井伊は江戸城の桜田門外で水戸藩などの浪士に暗殺されました。\nその後の流れ:攘夷の実行と外国の反撃(薩英戦争1863年・四国艦隊の下関砲撃1864年)→ 薩長同盟(1866年)→ 大政奉還(1867年10月)→ 王政復古の大号令(1867年12月)。\n薩摩藩・長州藩は、外国と戦って負けたことで、攘夷は無理だと知りました。そこで、外国を追いはらうより、まず幕府を倒して強い国をつくる方向に切りかえたのです。',
        key: '幕末の順番は「条約 → 処罰(安政の大獄)→ 反発(桜田門外の変)→ 攘夷の失敗 → 薩長同盟 → 大政奉還」。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 桜田門外の変 イ 薩長同盟 ウ 日米修好通商条約 エ 安政の大獄', hint: '井伊直弼がしたことを出発点にします。', steps: ['出発点は、井伊直弼が朝廷の許可なく結んだ日米修好通商条約(1858年)。', 'これに反対する人々を処罰したのが安政の大獄。', 'その反発で井伊直弼が暗殺されたのが桜田門外の変(1860年)。', '攘夷が難しいと知った薩摩・長州が倒幕に向けて結んだのが薩長同盟(1866年)。'], a: 'ウ → エ → ア → イ', check: '「処罰した人(井伊)が暗殺される」順なので、安政の大獄は必ず桜田門外の変より前になります。' }] },
      { h: '年代の近いできごと:明治〜昭和の鎖', t: '【日清戦争から日露戦争へ】下関条約(1895年)→ 三国干渉(1895年)→ 日英同盟(1902年)→ 日露戦争(1904年)→ ポーツマス条約(1905年)→ 韓国併合(1910年)\n三国干渉で遼東半島を返させたロシアへの警戒が日英同盟を生み、日露戦争へつながりました。\n【大正期】第一次世界大戦(1914年)→ 大戦景気と物価上昇 → 米騒動(1918年)→ 原敬内閣(1918年)→ 普通選挙法・治安維持法(1925年)\n【昭和初期】世界恐慌(1929年)→ 満州事変(1931年)→ 満州国の建国(1932年3月)→ 五・一五事件(1932年5月)→ 国際連盟脱退の通告(1933年)→ 二・二六事件(1936年)→ 日中戦争(1937年)\n同じ年のできごとは、「どちらが原因か」で前後を決めます。たとえば1895年の下関条約と三国干渉は、条約で得た遼東半島を返させたのが三国干渉なので、条約が先です。',
        ex: [{ q: '世界恐慌(1929年)のあと、日本が国際的に孤立していった流れを説明しよう。', hint: '「不景気 → 満州 → 国際連盟」の3段階を、つなぎのことばで結びます。', steps: ['世界恐慌で日本も深刻な不景気になり、人々の不満が高まった。', '軍(関東軍)は活路を中国東北部に求め、1931年に満州事変を起こし、満州国をつくった。', '国際連盟が満州国を認めなかったため、日本は1933年に国際連盟を脱退した。', 'こうして日本は国際的に孤立し、軍部の力が強まって日中戦争へ向かった。'], a: '世界恐慌による不景気 → 満州事変・満州国の建国 → 国際連盟が認めず連盟を脱退 → 国際的な孤立と軍部の台頭、という流れ。' }] },
      { h: '「その結果どうなったか」に答える', t: '結果を問われたら、【直後に起きた変化】と【長い目で見た影響】の2段階で考えます。1段階だけだと、答えが浅くなりがちです。\n例:地租改正(1873年)の結果 → 直後:政府の税収が安定した。一方、負担が軽くならない農民が反対一揆を起こし、1877年に税率が3%から2.5%に下げられた。→ 長期:近代的な税のしくみの土台になった。\n例:米騒動(1918年)の結果 → 直後:寺内内閣が退陣した。→ 長期:原敬の本格的な政党内閣が生まれ、政党政治の時代が始まった。\n例:日露戦争(1904〜05年)の結果 → 直後:賠償金が取れず、日比谷焼き打ち事件。→ 長期:韓国への支配を強め、1910年の韓国併合へ。\n結果を書くときは、「その結果」「そのため」「こうして」などのつなぎのことばを使うと、因果がはっきり伝わります。' },
      { h: '入試での答え方のコツ', t: '①記述では「〜だったので、〜した。その結果、〜になった」と、【原因・できごと・結果】を1文ずつ書く。1文に全部つめこむと、因果がぼやけます。\n②選択肢の問題では、「原因と結果が逆になっている」選択肢や、「時代がずれた人物」が入っている選択肢を消していく。\n③「なぜ」と聞かれたら、できごとの説明ではなく【理由】を答える。例:「大政奉還とは何か」ではなく「なぜ行ったか」を書く。\n④資料(グラフ・年表)が出たら、資料から読み取れる事実と、自分の知識を組み合わせる。資料だけ、知識だけの答えは減点されやすい。\n⑤最後に、答えを読み返して「主語(だれが)」が書かれているか確かめる。歴史の記述は、主語がないと意味が通らないことが多い。',
        key: '記述は「原因・できごと・結果」を1文ずつ。「なぜ」には理由で答える。',
        ex: [{ q: '次の文のうち、因果関係が正しいものはどれ?ア 御家人の生活が苦しくなったので、元寇が起きた。イ 元寇で恩賞が不足したので、御家人の生活が苦しくなった。ウ 徳政令が出されたので、元寇が起きた。', hint: 'それぞれのできごとの年代を並べ、原因が結果より前にあるかを確かめます。', steps: ['元寇は1274年・1281年、徳政令は1297年。', 'ア:元寇はモンゴル(元)が攻めてきたことで起きた。御家人の生活苦は元寇の結果なので、原因と結果が逆。', 'ウ:徳政令(1297年)は元寇より後なので、元寇の原因にはなれない。', 'イ:元寇(原因)→ 恩賞不足 → 生活苦(結果)と、時間の順にも合っている。'], a: 'イ', check: '「原因は必ず結果より前に起きる」という当たり前のルールで、年代を確かめれば誤りの選択肢を消せます。' }] }
    ],
    faq: [
      ['年号を覚えていなくても、本当に並べかえは解けるの?', 'すべてではありませんが、多くは解けます。たとえば「処罰した人が暗殺される」「条約で得た土地を返させられる」のように、片方がもう片方の原因なら、順番は自然に決まります。\nただし、まったく関係のない2つのできごとの前後は、年号の知識が必要です。目印になる年号はいくつか覚えておきましょう。'],
      ['背景ときっかけは、どう区別するの?', '背景は「長い間たまっていた問題」、きっかけは「直接の引き金になった1つの事件」です。\nたとえば米騒動なら、背景は大戦景気による物価の上昇、きっかけはシベリア出兵を見こした米の買い占めによる米価の急上昇です。「その事件がなくても、いずれ何か起きたか?」と考えると、背景かどうかが分かります。'],
      ['記述問題で、どこまで書けば満点になるの?', '問われていることに対して、「原因」と「結果」の両方、または「理由」が、重要語句を使って書けていれば、多くの場合は得点になります。\n字数の指定がある場合は、その8割以上を目安に書きましょう。短すぎると、因果の一部がぬけていると判断されやすくなります。']
    ],
    terms: [['因果関係', '原因と結果のつながり'], ['背景', 'できごとが起きる前から長い間たまっていた問題'], ['きっかけ', 'できごとの直接の引き金になった事件'], ['安政の大獄', '井伊直弼が、条約や将軍のあとつぎに反対した大名・公家・武士を処罰したこと'], ['桜田門外の変', '1860年、井伊直弼が江戸城桜田門の外で暗殺された事件'], ['下剋上', '下の者が実力で上の者を倒すこと。応仁の乱の後に広がった']],
    miss: ['原因と結果を逆にした選択肢を選んでしまう(例:「御家人が困ったので元寇が起きた」)。年代を並べて、原因が先にあるかを確かめる。', '「なぜ」と聞かれているのに、できごとの内容だけを書いてしまう。答えの最後が「〜から。」「〜ため。」で終わっているか見直す。', '同じ年のできごとの順番を、因果を考えずにあてずっぽうで決める。「片方がもう片方の原因になっていないか」をまず考える。', '結果を「直後」だけで答えて、長期の影響を書き落とす。2段階で考えるくせをつける。'],
    sum: ['因果は「しくみの崩壊」「外の動き → 国内」「失敗 → 次の改革」の3つの型。', '結果は「直後の変化」と「長期の影響」の2段階で答える。', '年代の近いできごとは「なぜ起きたか」で順番を決める。', '幕末:条約 → 安政の大獄 → 桜田門外の変 → 薩長同盟 → 大政奉還。', '記述は原因・できごと・結果を1文ずつ書く。'],
    next: '高校に進んだら、「日本史探究(c_h1)」で、同じ因果の考え方を使って、土地制度や外交などのテーマごとに日本史を通して学びましょう。'
  };

  // ===== 世界史探究 =====
  L.c_h2 = {
    goal: '古代から現代までの世界の大きな流れを、地域ごとの縦の流れと、同じ時代の横のつながりの両方で説明できるようになる。',
    intro: '世界史がむずかしく感じるのは、地域が多く、話がとびとびに見えるからです。でも、【「縦」=ある地域の流れ】と【「横」=同じ時代にほかの地域で起きていたこと】の2つを意識すると、1枚の大きな地図のようにつながってきます。たとえば、ヨーロッパの大航海時代は、アジアの明やオスマン帝国の豊かさを求めて始まりました。',
    pre: '世界史では、地域を大きく【ヨーロッパ】【西アジア】【南アジア(インド)】【東アジア(中国など)】に分けて考えると整理しやすくなります。\n年は西暦で表し、100年ごとの区切りを【世紀】といいます。「18世紀後半」は1751〜1800年です。\n【帝国】とは、多くの民族や地域を、1人の皇帝や1つの国がまとめて支配する大きな国のことです。\n中学の歴史で学んだ日本のできごと(大化の改新、元寇、鎖国、明治維新など)は、世界史の年表の「目印」として使えます。同じころ世界で何が起きていたかを結びつけると、覚えやすくなります。',
    secs: [
      { h: '古代:文明と大帝国', t: '大河の流域でオリエント(メソポタミア・エジプト)・インダス・中国の文明が生まれ、その後、広い地域をまとめる大帝国ができました。\n【ギリシア】…山が多く平野がせまいため、統一国家ではなく、アテネやスパルタなどの【ポリス】(都市国家)が分かれて発達した。アテネでは、成年男性の市民が民会に集まって政治を決める【民主政】が行われた。ただし、女性や奴隷、外国人には参政権がなかった。\n【ローマ】…イタリア半島の都市国家から始まり、地中海を囲む大帝国をつくった。道路や水道を整え、ローマ法を定めた。ローマ帝国の中で生まれた【キリスト教】は、はじめ迫害されたが、のちに国の宗教となり、ヨーロッパの土台になった。\n【中国】…紀元前221年、秦の【始皇帝】が初めて中国を統一し、文字・貨幣・度量衡(長さや重さの単位)をそろえた。次の【漢】がそのしくみを受けつぎ、儒教を国の学問とした。\n東西を結ぶ交易路【シルクロード(絹の道)】を通って、中国の絹が西方へ、西方の文物が中国へ運ばれました。\nインドでは、紀元前5世紀ごろにシャカ(ガウタマ=シッダールタ)が【仏教】を開き、のちに東南アジアや東アジアに広まりました。',
        ex: [{ q: '古代アテネの民主政は、今の日本の民主政治とどこがちがう?2つ答えよう。', hint: '「だれが参加できたか」と「どうやって決めたか」の2つで比べます。', steps: ['参加できた人:アテネでは成年男性の市民だけで、女性・奴隷・外国人は参加できなかった。今の日本は18歳以上の男女すべてに選挙権がある。', '決め方:アテネでは、市民が民会に直接集まって政治を決めた(直接民主政)。', '今の日本は、選挙で選んだ代表者が国会で決める(間接民主政・代議制)。', 'この2点が大きなちがい。'], a: '①参加できたのが成年男性の市民だけで、女性や奴隷は除かれていた。②市民が民会に集まって直接決める直接民主政だった(今の日本は代表者を選ぶ間接民主政)。' }] },
      { h: '中世:イスラーム世界とヨーロッパ', t: '7世紀、アラビア半島で【ムハンマド】がイスラーム教を開きました。イスラーム教を信じる人々の国は、西アジアから北アフリカ・イベリア半島(今のスペイン)、さらに中央アジアへと広がりました。\nイスラーム世界では、ギリシアの学問が受けつがれ、数学・天文学・医学が大きく発達しました。今の算用数字(アラビア数字)も、インドの数字がイスラーム世界を通じてヨーロッパに伝わったものです。\n西ヨーロッパでは、ローマ帝国が分裂・おとろえたあと、国王・諸侯・騎士が土地を仲立ちに主従関係を結ぶ【封建社会】ができました。農民は領主の荘園で働き、税を納めました。\nまた、ローマ教皇を頂点とする【カトリック教会】が大きな力をもち、国王さえ従わせるほどでした。東ヨーロッパでは、ビザンツ帝国(東ローマ帝国)が続き、ギリシア正教が広まりました。\n11世紀末からの【十字軍】は、イスラーム勢力から聖地イェルサレムを取り返すことを目的にくり返されましたが、最終的には失敗し、教皇の権威が低下するきっかけになりました。',
        key: '中世のヨーロッパは、封建社会とカトリック教会が柱。十字軍の失敗で教皇の権威がゆらいだ。' },
      { h: 'アジアの大帝国:モンゴル帝国から明・清へ', t: '13世紀の初め、モンゴル高原の遊牧民を【チンギス・ハン】が統一しました。モンゴルは騎馬の機動力を生かして東西に勢力を広げ、ユーラシア大陸の大部分にまたがる【モンゴル帝国】をつくりました。\nモンゴル帝国は、13世紀後半には、中国を支配する【元】(都は大都=今の北京)と、西方のいくつかのハン国に分かれました。分かれたあともゆるやかにまとまり、道路や駅伝制が整えられたので、東西の交易や文化の交流がさかんになりました。\n元の【フビライ・ハン】は日本にも服属を求め、2度にわたって攻めてきました(元寇)。\n14世紀後半、元が北に追われると、漢民族の【明】(1368年〜)が中国を治めました。明は民間の海外貿易を制限し、周りの国々に、皇帝にみつぎ物を送らせる【朝貢】の形で貿易を認めました。日本の足利義満が始めた日明貿易も、この朝貢の形をとっています。\n17世紀、中国東北部の女真(満州人)が建てた【清】が中国全土を支配しました。清は、康熙帝・雍正帝・乾隆帝のころに最盛期をむかえ、モンゴル・チベット・新疆までを領域に入れました。\n清は、地域によって支配のしかたを変えました。中国本土は皇帝が直接治め、モンゴルなどは現地の有力者や宗教を認めながら間接的に治めました。広い領域を、むりなくまとめるための工夫です。',
        key: 'モンゴル帝国はユーラシアの東西を結び、そのあと中国では明・清が朝貢のしくみで周りの国々と関係を結んだ。',
        ex: [{ q: '清が、中国本土とモンゴル・チベットなどで支配のしかたを変えたのはなぜだと考えられる?', hint: '言語・宗教・暮らし方がちがう地域を、1つのやり方で治めるとどうなるかを考えます。', steps: ['清の領域は非常に広く、漢民族の農耕地域、モンゴルの遊牧地域、チベット仏教の地域など、暮らし方や宗教がちがう人々がいた。', '全部を中国本土と同じやり方で治めようとすると、反発が起き、支配に多くの費用もかかる。', 'そこで中国本土は皇帝が直接治め、モンゴル・チベット・新疆は現地の有力者や宗教を認めながら管理した。', 'こうすることで、反発をおさえながら広い領域を安定して支配できた。'], a: '暮らし方や宗教のちがう人々が住む広い領域を、反発をおさえて安定して治めるため。現地のしくみを認めて間接的に治めるほうが、むりが少なかった。' }] },
      { h: '近世ヨーロッパ:ルネサンス・大航海時代・宗教改革', t: '【ルネサンス】…14世紀に、東方貿易で栄えたイタリアの都市から始まった文化運動です。教会の教えを中心とする考え方から、ギリシア・ローマの文化を手本に、人間らしさを重んじる考え方へと変わりました。レオナルド・ダ・ヴィンチやミケランジェロが活躍しました。\n【大航海時代】…15世紀末から、ポルトガル・スペインが新しい航路を開きました。アジアの香辛料などを、イスラーム商人やイタリア商人を通さずに直接手に入れるためです。羅針盤の改良や、キリスト教を広めたいという思いも、航海を後押ししました。\n1492年にコロンブスがアメリカ大陸近くの島に到達し、1498年にバスコ・ダ・ガマがアフリカ南端を回ってインドに到達しました。マゼランの一行は世界一周を果たしました。\nスペインは、アメリカ大陸の【アステカ王国】や【インカ帝国】をほろぼして植民地にし、銀山を開発しました。先住民は、きびしい労働やヨーロッパから持ちこまれた病気で大きく減り、アフリカから多くの人々が奴隷として連れてこられました。\n【宗教改革】…1517年、ドイツの【ルター】が、教会がお金で罪の許しを与える贖宥状(免罪符)の販売を批判し、聖書だけを信仰のよりどころにすべきだと説きました。こうして【プロテスタント】が生まれました。カトリック側も立て直しをはかり、イエズス会がアジアなどで布教しました。ザビエルが日本に来たのもこの流れです。\n16〜17世紀のヨーロッパでは、はっきりした国境と、ほかの国から干渉されない主権をもつ国家どうしが並び立つ【主権国家体制】ができていきました。',
        ex: [{ q: 'ポルトガルやスペインが、15世紀末に新しい航路を開こうとしたのはなぜ?', hint: 'アジアの香辛料が、それまでどのような道すじでヨーロッパに届いていたかを考えます。', steps: ['ヨーロッパでは、肉の保存や味つけに使うアジアの香辛料が、とても高く取り引きされていた。', 'それまでは、西アジアのイスラーム商人や、地中海のイタリア商人を通して手に入れていたため、値段が高くなっていた。', '海を通ってアジアに直接行ければ、間の商人を通さずに安く手に入れ、大きな利益が得られる。', 'さらに、キリスト教を広めたいという思いや、羅針盤など航海技術の進歩も後押しした。'], a: 'アジアの香辛料などを、イスラーム商人やイタリア商人を通さずに直接手に入れ、大きな利益を得るため。キリスト教の布教や航海技術の進歩も背景にあった。' }] },
      { h: '近代:二つの革命と国民国家', t: '【市民革命】…王の権力をおさえ、市民の権利を広げる革命です。イギリスの名誉革命(1688年、翌年に権利の章典)、アメリカ独立宣言(1776年)、【フランス革命】(1789年)が代表です。\nフランス革命の「自由・平等」の考えは、ナポレオンの遠征を通じてヨーロッパ各地に広がり、各地で同じ言語や文化をもつ人々が国民としてまとまろうとする動き(【ナショナリズム】)を生みました。19世紀には、イタリアやドイツが統一を果たし、【国民国家】がつくられていきます。\n【産業革命】…18世紀後半のイギリスで、綿工業から始まりました。紡績機や織機が改良され、ワットが改良した【蒸気機関】を動力にして、工場で大量生産ができるようになりました。\nイギリスで最初に起きた理由:①植民地との貿易などで【資本】がたくわえられていた、②農業の変化で土地を失った人々が都市に流れこみ【労働力】があった、③【石炭・鉄鉱石】が豊富だった、④広い植民地を【市場】としてもっていた。\n産業革命によって、資本家が労働者をやとって利益を求める【資本主義】の社会が広まりました。一方で、長時間労働や子どもの労働などの社会問題も生まれ、労働者を守ろうとする社会主義の考え方も現れました。',
        key: '近代は「市民革命(政治の変化)」と「産業革命(経済の変化)」の二つの革命から始まった。',
        ex: [{ q: '産業革命が最初にイギリスで起きたのはなぜ?3つ以上の理由で説明しよう。', hint: '工場を動かすのに必要なもの(お金・人・資源・売り先)を順に考えます。', steps: ['資本:海外貿易などでお金(資本)がたくわえられていた。工場や機械をつくるにはお金が必要。', '労働力:農業の変化で土地を失った農民が都市に集まり、工場で働く人がいた。', '資源:機械や燃料に必要な石炭・鉄鉱石が国内で豊富にとれた。', '市場:広い植民地があり、つくった製品を売る先があった。'], a: '資本のたくわえ、都市に集まった労働力、豊富な石炭・鉄鉱石、製品を売る植民地という市場がそろっていたから。', check: '4つのうちどれか1つが欠けると、工場での大量生産は続かないことを確かめましょう。' }] },
      { h: '帝国主義とアジア・アフリカ', t: '19世紀後半になると、工業化した欧米の国々は、工業の原料と、製品を売る市場を求めて、アジア・アフリカを植民地や勢力範囲にしていきました。この動きを【帝国主義】といいます。\nアフリカは、19世紀末までにエチオピアとリベリアを除くほぼ全域が、ヨーロッパの国々に分割されました。\nインドでは、イギリスの東インド会社が支配を広げ、1857年に始まったインドの人々の大反乱(インド大反乱)をおさえたあと、イギリスが直接支配する【インド帝国】(1877年)をつくりました。\n中国(清)は、【アヘン戦争】(1840〜42年)でイギリスに敗れ、南京条約で香港島をゆずり、上海などを開港しました。その後も列強の進出が続き、清の力は弱まっていきました。\n日本は、同じように欧米の圧力を受けて開国しましたが、明治維新で近代化を進め、のちに日清・日露戦争を経て、自らも植民地をもつ国になりました。\nこうした植民地の争奪をめぐる列強どうしの対立が、やがて第一次世界大戦の背景になります。' },
      { h: '現代:二つの世界大戦から冷戦、グローバル化へ', t: '帝国主義の国どうしの対立から【第一次世界大戦】(1914〜18年)が起こりました。戦車や飛行機などの新兵器が使われ、国民全体をまきこむ総力戦になりました。\n戦中の1917年には【ロシア革命】で、世界初の社会主義の政府が生まれました(のちのソ連)。戦後はヴェルサイユ条約で講和し、平和を守るための【国際連盟】がつくられました。\n1929年の【世界恐慌】で各国の経済が混乱し、ドイツやイタリアでは、個人の自由より国家を優先し、武力で領土を広げようとする【ファシズム】が台頭しました。こうして【第二次世界大戦】(1939〜45年)が起こりました。\n戦後は、国際連盟が戦争を防げなかった反省から【国際連合】がつくられました。一方で、アメリカとソ連が対立する【冷戦】が続きました。アジア・アフリカでは多くの植民地が独立し、とくに1960年はアフリカで17か国が独立して「アフリカの年」とよばれました。\n1989年に冷戦が終わり、1991年にソ連が解体すると、人・もの・お金・情報が国境をこえて動く【グローバル化】が進みました。一方で、地域紛争、テロ、経済格差、地球環境問題など、国をこえて取り組むべき課題がふえています。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア フランス革命 イ 名誉革命 ウ ナポレオンが皇帝になる エ アメリカ独立宣言', hint: 'イギリス → アメリカ → フランス の順に、革命が大西洋をわたっていったと考えます。', steps: ['イギリスの名誉革命は1688年(17世紀)。', 'アメリカ独立宣言は1776年。', 'フランス革命は1789年。アメリカ独立戦争への支援による財政難も原因の一つ。', 'フランス革命後の混乱をおさめたナポレオンが1804年に皇帝に。'], a: 'イ → エ → ア → ウ', check: '1688 → 1776 → 1789 → 1804 と、年号が小さい順になっています。' }] }
    ],
    faq: [
      ['世界史は地域が多すぎて覚えられない。どうすればいい?', 'まず、地域ごとの「縦の流れ」を1本ずつ言えるようにしましょう。たとえば中国なら「秦 → 漢 → 隋 → 唐 → 宋 → 元 → 明 → 清」です。\nそのうえで、モンゴル帝国・産業革命・世界大戦のように多くの地域を一度に変えたできごとを「横の柱」にして、縦の流れどうしをつなぎます。'],
      ['ルネサンスはなぜイタリアから始まったの?', 'イタリアの都市は、十字軍のころから東方貿易で栄え、お金持ちの商人がいて、芸術家を支援できたからです。\nまた、イタリアには古代ローマの遺跡が多く残り、イスラーム世界やビザンツ帝国を通じて、ギリシアの古典も伝わってきていました。'],
      ['冷戦はなぜ「冷たい」戦争なの?', 'アメリカとソ連が、直接は戦火を交えなかったからです。両国とも核兵器をもっていたので、直接戦えば世界がほろびるおそれがありました。\nただし、朝鮮戦争やベトナム戦争のように、両国が支援する側に分かれて戦う「代理戦争」は、アジアなどで実際に起きました。']
    ],
    terms: [['ポリス', '古代ギリシアの都市国家。アテネでは民主政が行われた'], ['封建社会', '土地を仲立ちにした主従関係で成り立つ社会'], ['朝貢', '周りの国が中国の皇帝にみつぎ物を送り、皇帝が返礼を与える関係'], ['ルネサンス', 'イタリアから始まった、人間らしさを重んじる文化運動'], ['宗教改革', '1517年にルターが始めた、カトリック教会の改革運動'], ['主権国家体制', '主権をもつ国家どうしが対等に並び立つしくみ'], ['産業革命', '機械と動力による大量生産への変化。18世紀後半のイギリスから'], ['帝国主義', '工業国が原料と市場を求めて植民地を広げた動き']],
    miss: ['ルネサンスがイギリスやドイツから始まったと思う。始まりはイタリアで、理由は東方貿易の富と古典の伝統。', '産業革命の理由を「技術があったから」だけで答える。資本・労働力・資源・市場の4つを挙げる。', '名誉革命(1688年)とフランス革命(1789年)の世紀を取りちがえる。イギリス(17世紀)→ アメリカ・フランス(18世紀後半)と、国の順で覚える。', '元と明の順番を逆にする。モンゴル人の元が北に追われて、漢民族の明ができた。'],
    sum: ['地域ごとの「縦」と、同時代の「横」の両方で見る。', '古代はギリシア・ローマ・秦漢、中世はイスラーム世界の拡大とヨーロッパの封建社会。', 'モンゴル帝国が東西を結び、中国では元 → 明 → 清と続いた。', '近世:ルネサンス・大航海時代・宗教改革、主権国家体制。近代:市民革命と産業革命から帝国主義へ。', '現代:二つの世界大戦 → 冷戦 → グローバル化。'],
    next: '次は「入試レベル:世界史の因果関係(hx_whist)」に進みましょう。ここで見た大きな流れを、「背景 → できごと → 結果」の鎖にして、地域をこえる影響まで追いかけます。'
  };

  L.hx_whist = {
    goal: '入試レベルの世界史で、できごとを「背景 → できごと → 結果」でつなぎ、地域をこえて広がる影響まで説明できるようになる。',
    intro: '入試の世界史では、「このできごとの結果、何が起きたか」「なぜこのできごとが起きたか」が問われます。世界史のできごとは、ある地域で起きたことが、海をこえて別の地域を動かしていることがよくあります。アメリカの独立がフランス革命につながり、イギリスの産業革命がインドや中国の運命を変えました。こうした「影響のドミノ」を追えるようになりましょう。',
    pre: 'この単元は、世界史探究(c_h2)で学んだ大きな流れ(古代 → 中世 → 近世 → 近代 → 現代)を知っていることを前提にしています。\n【背景】は、できごとが起きる前から長い間たまっていた問題、【きっかけ】は直接の引き金になった事件です。\n【結果】には、すぐに表れた変化と、長い時間をかけて表れた影響があります。\n世界史では、ある地域の変化が、貿易・戦争・思想の伝わりを通じて、遠い別の地域を変えることがあります。この「地域をこえる矢印」を意識して読みましょう。',
    secs: [
      { h: '因果をとらえる3つの視点', t: 'できごとを見たら、次の3つを確認します。\n【背景(なぜ起きたか)】…長い間たまっていた問題。経済的な苦しさ、身分への不満、国どうしの対立など。\n【きっかけ】…直接の引き金になった事件。\n【結果と影響】…すぐに起きた変化と、ほかの地域や後の時代への影響。\n例:第一次世界大戦。背景=列強が植民地や勢力範囲をめぐって対立し、三国同盟と三国協商の2つの陣営に分かれていた。バルカン半島では民族どうしの対立が強く、「ヨーロッパの火薬庫」とよばれていた。\nきっかけ=1914年、ボスニアのサラエボで、オーストリアの帝位継承者夫妻がセルビア人の青年に暗殺された(サラエボ事件)。\n入試の選択肢では、「背景ときっかけの取りちがえ」や「結果を原因として書いた文」がよく誤りとして出されます。',
        key: 'できごとは「背景(長い問題)→ きっかけ(直接の事件)→ 結果・影響」の3つに分けて見る。',
        ex: [{ q: '第一次世界大戦について、次のア・イは「背景」と「きっかけ」のどちらにあたる?ア サラエボ事件 イ 三国同盟と三国協商の対立', hint: '「その事件がなくても、いずれ戦争の火種になったか」を考えます。', steps: ['背景は、長い間たまっていた問題。きっかけは、直接の引き金になった1つの事件。', 'イ:列強が2つの陣営に分かれて対立していたのは、何年も前から続いていた状態 → 背景。', 'ア:1914年に起きた1つの暗殺事件で、これをきっかけにオーストリアがセルビアに宣戦し、各国が次々に参戦した → きっかけ。'], a: 'ア=きっかけ、イ=背景', check: '「サラエボ事件がなくても、対立はいずれ何かの形で戦争につながったかもしれない」と考えられるので、対立のほうが背景だと確かめられます。' }] },
      { h: '十字軍の結果', t: '十字軍(11世紀末〜13世紀)は失敗に終わりましたが、ヨーロッパ社会を大きく変えました。\n①くり返し失敗したことで、呼びかけた【ローマ教皇の権威が低下】した。\n②遠征に参加した【諸侯・騎士が没落】し、相対的に【国王の権力が強まった】。\n③軍や物資の輸送でイタリアの都市が栄え、東方との貿易(【東方貿易】)がさかんになった。\n④イスラーム世界やビザンツ帝国の進んだ学問や文物が、ヨーロッパに伝わった。\nこのイタリア都市の繁栄と、伝わってきた古典の学問が、のちにイタリアで【ルネサンス】が始まる土台になりました。\nこのように、「失敗したできごと」でも、長い目で見ると社会を大きく変えることがあります。',
        key: '十字軍の結果:教皇権の低下・諸侯騎士の没落と王権の強化・東方貿易の発展 → ルネサンスの土台。',
        ex: [{ q: '十字軍の結果として誤っているものはどれ?ア 教皇の権威が低下した イ 国王の権力が弱まった ウ 東方貿易がさかんになった エ 諸侯・騎士が没落した', hint: '諸侯・騎士が没落すると、そのぶん力が強くなるのはだれかを考えます。', steps: ['教皇:失敗をくり返したので権威が低下した → 正しい。', '諸侯・騎士:遠征で財産や命を失い没落した → 正しい。', 'そのぶん、国王の力は相対的に強まった → イの「弱まった」は逆。', '東方貿易:輸送を担ったイタリア都市が栄えた → 正しい。'], a: 'イ' }] },
      { h: '大航海時代が世界を結んだ', t: '大航海時代(15世紀末〜)は、ヨーロッパ・アメリカ・アフリカ・アジアを、初めて海の道で1つに結びました。\n【アメリカ大陸の変化】スペインはアステカ王国・インカ帝国をほろぼして植民地にし、先住民を鉱山や農園で働かせました。きびしい労働とヨーロッパから持ちこまれた病気で、先住民の人口は激減しました。\n【アフリカの変化】労働力が足りなくなったアメリカ大陸に、アフリカから多くの人々が奴隷として運ばれました。ヨーロッパの武器や雑貨をアフリカへ、アフリカの奴隷をアメリカへ、アメリカの砂糖や綿花をヨーロッパへ運ぶ【大西洋の三角貿易】が行われました。\n【ヨーロッパの変化】アメリカ大陸から大量の銀が流れこみ、物価が大きく上がりました(価格革命)。また、貿易の中心が地中海から大西洋岸に移り、イタリアの都市はおとろえ、スペイン・ポルトガル、のちにオランダ・イギリスが栄えました(商業革命)。\n【アジアとのつながり】アメリカ大陸の銀は、アジアの絹や陶磁器、茶を買うためにも使われ、明や清に大量に流れこみました。\nこのように、大航海時代は、遠くはなれた地域どうしを、もの・人・お金の流れで結びつけました。これが、のちの世界経済の出発点になります。' },
      { h: '大西洋をこえる革命のドミノ', t: '【背景】イギリスは七年戦争(フランスとの植民地をめぐる争い)などで多額の借金をかかえ、北アメリカの植民地に新しい税をかけました(1765年の印紙法など)。\n【反発】植民地の人々は、本国の議会に代表を送っていないのに課税されることに反発しました(「代表なくして課税なし」)。\n【できごと】1775年に独立戦争が始まり、1776年に【独立宣言】を発表。フランスなどが植民地側を支援し、1783年のパリ条約でアメリカの独立が認められました。\n【影響1:財政】アメリカを支援したフランスは、もともと苦しかった財政がさらに悪化しました。ルイ16世は特権身分にも課税しようとして、1789年に【三部会】を開きます。三部会での対立をきっかけに【フランス革命】が始まりました。\n【影響2:思想】アメリカ独立宣言の考え方(人は生まれながらに自由で平等な権利をもち、権利をおかす政府は変えられる)は、ロックの思想を受けついだもので、フランスの人権宣言にも影響を与えました。\nさらにフランス革命の影響は、カリブ海のハイチの独立(1804年)や、19世紀前半のラテンアメリカ諸国の独立にも広がりました。',
        ex: [{ q: 'アメリカの独立が、フランス革命の原因の一つになったのはなぜ?', hint: '「お金(財政)」と「考え方(思想)」の2つの道すじを考えます。', steps: ['フランスは、イギリスと対立していたこともあり、アメリカ独立戦争で植民地側を支援した。', 'その戦費で、もともと苦しかったフランスの財政がさらに悪化した。', '財政を立て直すため、国王は特権身分への課税を議論する三部会を開いた。三部会での対立から国民議会がつくられ、革命が始まった。', 'また、アメリカ独立宣言の自由・平等の思想も、フランスの人々に影響を与えた。'], a: 'アメリカ独立戦争の支援でフランスの財政が悪化し、その立て直しのために開いた三部会が革命のきっかけになったから。独立宣言の自由・平等の思想も影響した。' }] },
      { h: '産業革命がアジアを変えた', t: 'イギリスで産業革命が進むと、機械でつくった安い綿織物がインドに大量に流れこみ、インドの手織りの綿織物業は大きな打撃を受けました。インドは、イギリスに綿花などの原料を売り、イギリスの工業製品を買う立場に変えられていきました。\nまた、イギリスは中国(清)から茶を大量に買っていました。しかし清はイギリスの製品をあまり買わなかったため、代金の【銀】が中国へ流出していました。\nそこでイギリスは、インドでつくった【アヘン】(麻薬)を清に売り、イギリスの綿製品をインドへ、インドのアヘンを清へ、清の茶をイギリスへ、という【三角貿易】を行いました。これで、銀の流れは逆に清から流れ出すようになりました。\nアヘンの害が広がり、銀も流出したため、清がアヘンをきびしく取りしまると、イギリスは【アヘン戦争】(1840〜42年)を起こしました。勝ったイギリスは南京条約で香港島を手に入れ、上海など5港を開港させました。\nこのように、ヨーロッパの工業化は、アジアを原料の供給地・製品の市場へと組みこんでいきました。アヘン戦争の情報は日本にも伝わり、江戸幕府の外交方針を変えることになります。',
        key: '三角貿易:イギリスの綿製品 → インド、インドのアヘン → 清、清の茶 → イギリス。',
        ex: [{ q: 'イギリスが、インド・清との間で三角貿易を始めたのはなぜ?', hint: 'イギリスと清の貿易で、銀がどちらに流れていたかを考えます。', steps: ['イギリスは清から茶を大量に買っていたが、清はイギリスの製品をあまり買わなかった。', 'そのため、茶の代金として、イギリスから清へ大量の銀が流出していた。', 'イギリスは、インドでつくったアヘンを清に売れば、その代金として清から銀を取りもどせると考えた。', 'こうして、イギリスの綿製品 → インド、インドのアヘン → 清、清の茶 → イギリス、という三角貿易が始まった。'], a: '茶の輸入で清へ流出していた銀を取りもどすため。インド産のアヘンを清に売ることで、銀の流れを逆にしようとした。' }] },
      { h: '世界恐慌から第二次世界大戦へ', t: '1929年、ニューヨークの株式市場での株価の大暴落から【世界恐慌】が始まりました。アメリカの資金にたよっていたヨーロッパにも不況が広がり、各国の対応は分かれます。\n【アメリカ】…フランクリン=ローズヴェルト大統領が【ニューディール政策】で、公共事業などにより政府が経済に積極的に関わった。\n【イギリス・フランス】…広い植民地と本国を囲いこみ、外国の商品に高い関税をかける【ブロック経済】をとった。\n【ドイツ・イタリア・日本】…植民地や資源が少なく、ブロック経済からしめ出されて行きづまり、軍事力で領土を広げようとする動きが強まった。ドイツでは、ヴェルサイユ条約への不満も背景に、ヒトラーのナチスが政権をにぎった。\n【ソ連】…計画経済(五か年計画)を進めていたため、恐慌の影響をあまり受けなかった。\nブロック経済で世界経済が分断されたことが、「持てる国」と「持たざる国」の対立を深め、第二次世界大戦の背景になりました。この反省から、戦後は自由な貿易を進めるためのしくみ(GATT、のちのWTO)がつくられました。',
        ex: [{ q: '世界恐慌のあと、ブロック経済が第二次世界大戦の背景の一つになったといわれるのはなぜ?', hint: 'ブロック経済でしめ出された国はどう考えたかを考えます。', steps: ['イギリスやフランスは、広い植民地と本国でブロックをつくり、外国の商品に高い関税をかけた。', '植民地の少ないドイツ・イタリア・日本は、製品を売る市場や資源を手に入れにくくなった。', 'そこでこれらの国は、軍事力で新しい領土や勢力範囲を手に入れようとした。', '「持てる国」と「持たざる国」の対立が深まり、戦争につながった。'], a: 'ブロック経済で市場や資源からしめ出されたドイツ・イタリア・日本が、軍事力で領土を広げようとし、植民地を多くもつ国々との対立が深まったから。', check: '戦後、自由貿易を進めるGATTがつくられたことは、この反省の裏返しだと確かめられます。' }] }
    ],
    faq: [
      ['「影響のドミノ」は、どうやって見つければいいの?', '「もの(貿易)」「お金(財政・銀)」「人(移民・奴隷)」「考え方(思想)」の4つの通り道を意識します。\nたとえばアメリカ独立 → フランス革命は、お金(財政難)と考え方(自由・平等)の2つの通り道でつながっています。'],
      ['三角貿易は、大西洋のものとアジアのものと、2つあるの?', 'はい、入試では両方出ます。大西洋の三角貿易は、ヨーロッパ・アフリカ・アメリカの間で、武器や雑貨・奴隷・砂糖などを運んだものです(17〜18世紀が中心)。\nアジアの三角貿易は、イギリス・インド・清の間で、綿製品・アヘン・茶を運んだものです(19世紀前半)。地域と商品の組み合わせで区別しましょう。'],
      ['なぜソ連は世界恐慌の影響をあまり受けなかったの?', 'ソ連は、国が生産の計画を立てる計画経済をとっていて、資本主義の国々との貿易や金融のつながりが小さかったからです。\nただし、その計画経済の中では、農業の強制的な集団化などによって、多くの人々が大きな苦しみを受けました。']
    ],
    terms: [['三部会', 'フランスの身分制議会。1789年の招集が革命のきっかけになった'], ['東方貿易', '十字軍のころからさかんになった、イタリア都市と東方との貿易'], ['価格革命', 'アメリカ大陸の銀が流れこみ、ヨーロッパの物価が大きく上がったこと'], ['三角貿易', 'イギリス・インド・清の間で、綿製品・アヘン・茶を回した貿易'], ['サラエボ事件', '1914年、オーストリアの帝位継承者夫妻が暗殺された事件。第一次世界大戦のきっかけ'], ['ニューディール政策', '世界恐慌に対しアメリカが行った、公共事業などによる経済政策'], ['ブロック経済', '本国と植民地で経済圏をつくり、外国商品をしめ出す政策']],
    miss: ['十字軍の結果を「教皇の権威が高まった」と逆に覚える。失敗をくり返したので低下した、と理由ごと覚える。', 'アヘン戦争を「清がイギリスにアヘンを売った」と取りちがえる。売ったのはイギリス(インド産)で、取りしまったのが清。', '世界恐慌でソ連も大きな打撃を受けたと思う。計画経済で影響が小さかった。', '第一次世界大戦の原因を「サラエボ事件だけ」と答える。それはきっかけで、背景には列強の対立とバルカン半島の民族問題がある。'],
    sum: ['できごとは「背景 → きっかけ → 結果・影響」で整理する。', '十字軍 → 教皇権の低下・王権の強化・東方貿易 → ルネサンスの土台。', '大航海時代 → 先住民の激減・大西洋の三角貿易・価格革命 → 世界の一体化。', 'アメリカ独立 → フランスの財政難 → 三部会 → フランス革命。産業革命 → 三角貿易 → アヘン戦争。', '世界恐慌 → 各国の対応の差(ブロック経済など)→ 第二次世界大戦の背景。'],
    next: '次は「難関:世界史(hd_wsoc)」に進みましょう。数年ちがいのできごとの並べかえや、地域をまたぐ同時代の比較を、因果と年表の重ね合わせで解く練習をします。'
  };

  L.hd_wsoc = {
    goal: '難関大レベルの、年代の近いできごとの並べかえや、地域をまたぐ同時代の比較を、因果と年表の整理で正確に解けるようになる。',
    intro: '難関大の世界史では、「数年ちがい」「同じ年のうちの前後」まで問われます。これを年号の丸暗記だけで乗りきるのは大変です。コツは、①1つの国の中のできごとを因果の鎖でつなぐこと、②地域ごとの年表を1本に重ねて「同じころ、別の地域では何が起きていたか」を見ることです。',
    pre: 'この単元は、世界史の大きな流れ(c_h2)と、「背景 → きっかけ → 結果」で因果をつなぐ方法(hx_whist)を学んだことを前提にしています。\n【体制】とは、国の政治のしくみのことです。たとえば、国王が治める【王政】、王がいない【共和政】、憲法で王の権力をしばる【立憲君主政】などがあります。\n【急進的】は、変化を一気に、徹底的に進めようとする立場、【穏健的】は、変化をゆるやかに進めようとする立場です。革命の時代には、この2つが入れかわりながら進むことが多くあります。\n並べかえ問題では、「年号」よりも先に「どちらがどちらの原因か」を考えるのが基本です。',
    secs: [
      { h: '1つの国の流れを鎖にする:フランス革命とナポレオン', t: '1789年 三部会 → 国民議会 → バスティーユ牢獄襲撃 → 人権宣言\n1791年 憲法制定(立憲君主政)\n1792年 王政の廃止(第一共和政)\n1793年 ルイ16世の処刑 → ロベスピエールらの恐怖政治\n1794年 テルミドールのクーデタで恐怖政治が終わる → 1795年 総裁政府\n1799年 ナポレオンのブリュメール18日のクーデタ(統領政府)\n1804年 ナポレオン法典(民法典)の公布、ナポレオンが皇帝に即位 → 1814〜15年 ウィーン会議\n「王の権力をおさえる → 王政をやめる → 急進化する → 反動で穏健化 → 混乱をおさめる強い指導者が登場」という流れで理解すると、順番が自然に決まります。',
        key: 'フランス:革命(1789)→ 共和政(1792)→ 総裁政府(1795)→ 統領政府(1799)→ 皇帝(1804)。',
        ex: [{ q: 'フランス革命の始まり(1789年)とナポレオンの皇帝即位(1804年)は何年ちがう?また、その間の政治体制を順に並べよう(ア 総裁政府 イ 第一共和政の成立 ウ 統領政府)。', hint: '「王がいなくなる → 不安定な政府 → 強い指導者」の順を考えます。', steps: ['1804−1789=15年。', '1792年に王政が廃止され、第一共和政が成立。', '恐怖政治のあと、反動で穏健な1795年の総裁政府。', '総裁政府が不安定だったので、1799年のクーデタで統領政府ができ、ナポレオンが実権をにぎった。'], a: '15年。イ → ア → ウ', check: '統領政府でナポレオンが実権をにぎったあとに皇帝になる、という流れが1804年の即位とつながります。' }] },
      { h: 'ウィーン体制から国民国家の成立へ', t: '1814〜15年の【ウィーン会議】では、オーストリアのメッテルニヒが中心となり、ヨーロッパをフランス革命前の状態にもどそうとする【正統主義】がとられました。こうしてできた、自由主義やナショナリズムをおさえる国際秩序を【ウィーン体制】といいます。\nしかし、革命で広まった自由と平等の考えは消えませんでした。1830年、フランスで【七月革命】が起き、国王が追放されました。\n1848年、フランスで【二月革命】が起き、王政が倒れて第二共和政が成立しました。これがドイツやオーストリアに広がって【三月革命】が起き、メッテルニヒが失脚して、ウィーン体制は崩壊しました。この年の各地の革命を「1848年革命」「諸国民の春」とよぶことがあります。\n19世紀後半には、ナショナリズムの高まりの中で、ばらばらだった国々が統一されました。1861年に【イタリア王国】が成立し、1871年にはプロイセンの首相【ビスマルク】の指導で、【ドイツ帝国】が成立しました。\n流れの型:「おさえつける体制(ウィーン体制)→ 小さな反発(七月革命)→ 大きな反発で体制崩壊(1848年)→ 国民国家の成立(統一)」。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 二月革命 イ ウィーン会議 ウ 七月革命 エ ドイツ帝国の成立', hint: '「体制をつくる → 反発 → 体制が倒れる → 新しい国」の型に当てはめます。', steps: ['ナポレオンの敗北後、ヨーロッパの秩序をつくり直したのがウィーン会議(1814〜15年)。', 'その体制に対する最初の大きな反発がフランスの七月革命(1830年)。', 'さらに大きな反発がフランスの二月革命(1848年)で、各地に広がりウィーン体制が崩壊。', 'ナショナリズムが高まり、ドイツ帝国が成立(1871年)。'], a: 'イ → ウ → ア → エ', check: '「七月(1830年)」と「二月(1848年)」は、月の名前ではなく年で並べることに注意します。' }] },
      { h: '19世紀の中国:外からの圧力と内の動揺', t: '1840〜42年 アヘン戦争(南京条約)\n1851年 太平天国の乱(〜1864年)\n1856年 アロー戦争(〜1860年)→ 北京条約\n1894年 日清戦争 → 1895年 下関条約 → 列強による中国分割の進行\n1900年 義和団事件(義和団戦争)\n1911年 辛亥革命 → 1912年 中華民国の成立、清の滅亡\n「外国との戦争に負けて負担が増える → 国内の反乱 → さらに外国の進出 → 外国を排除しようとする運動 → 王朝そのものを倒す革命」と、外と内の動きが交互に起きる流れです。\nアヘン戦争の賠償金などで重い税がかかり、人々の不満が太平天国の乱につながりました。その反乱でゆれている最中に、イギリス・フランスはアロー戦争を起こして、さらに権益を広げました。',
        key: '19世紀の中国は「外の戦争 → 内の反乱」が交互に起き、最後に辛亥革命で清がほろびた。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 義和団事件 イ 太平天国の乱 ウ アヘン戦争 エ 辛亥革命', hint: '「外の戦争 → 内の反乱 → 外国の排除運動 → 革命」の型を使います。', steps: ['出発点は、イギリスとのアヘン戦争(1840〜42年)。', '敗戦後の重い負担と社会の混乱から、太平天国の乱(1851年〜)が起きた。', '日清戦争後に列強の進出が強まり、外国を追い出そうとする義和団事件(1900年)が起きた。', '清の改革が間に合わず、清そのものを倒す辛亥革命(1911年)が起きた。'], a: 'ウ → イ → ア → エ' }] },
      { h: '対立の深まりを鎖にする:冷戦の始まり', t: '1947年 トルーマン・ドクトリン(共産主義の拡大をおさえる「封じこめ政策」)→ マーシャル・プラン(ヨーロッパの経済復興援助)\n1948年 ソ連が西ベルリンへの交通をふさぐ(ベルリン封鎖)\n1949年 西側の軍事同盟【NATO(北大西洋条約機構)】→ 東西ドイツの分立 → 中華人民共和国の成立\n1950年 朝鮮戦争\n1955年 東側の軍事同盟【ワルシャワ条約機構】\n「方針の表明 → 経済援助 → 対立の具体化(封鎖)→ 軍事同盟 → 実際の戦争」と、対立が段階的に深まる流れで並べます。\nワルシャワ条約機構が1955年と遅いのは、西ドイツのNATO加盟(1955年)への対抗としてつくられたからです。「東側の同盟は、西側の動きへの反応」と考えると、順番を取りちがえません。',
        key: '冷戦の始まり:マーシャル・プラン(1947)→ NATO(1949)→ 朝鮮戦争(1950)→ ワルシャワ条約機構(1955)。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 朝鮮戦争の開始 イ NATOの結成 ウ マーシャル・プランの発表 エ ワルシャワ条約機構の結成', hint: '「方針・援助 → 同盟 → 戦争 → 対抗の同盟」の順に考えます。', steps: ['1947年、アメリカがヨーロッパ復興のためマーシャル・プランを発表。', '1948年のベルリン封鎖などで対立が深まり、1949年にNATO結成。', '1950年、朝鮮半島で実際の戦争(朝鮮戦争)が始まる。', '1955年、西ドイツのNATO加盟に対抗して、ワルシャワ条約機構。'], a: 'ウ → イ → ア → エ' }] },
      { h: '冷戦の展開と終結', t: '1961年 東ドイツが【ベルリンの壁】を築く(東から西への人の流出を止めるため)\n1962年 【キューバ危機】(ソ連がキューバにミサイル基地をつくろうとし、米ソが核戦争の寸前までいく)→ 1963年 部分的核実験禁止条約(緊張をやわらげる動き)\n1960年代〜70年代 ベトナム戦争。アメリカが介入したが、1973年に撤退した\n1985年 ソ連で【ゴルバチョフ】が指導者になり、ペレストロイカ(改革)を進める\n1989年 東ヨーロッパで民主化が進み、【ベルリンの壁】が開放される → 同年12月 米ソ首脳の【マルタ会談】で冷戦の終結を宣言\n1990年 東西ドイツの統一 → 1991年 ソ連の解体\n流れの型:「緊張の頂点(キューバ危機)→ 緊張緩和(核実験の制限)→ 東側の改革(ゴルバチョフ)→ 東側の体制の崩壊」。壁が「築かれた年(1961年)」と「開放された年(1989年)」を区別しましょう。' },
      { h: '横のつながりで並べる', t: '別々の地域のできごとを並べる問題では、各地域の年表を1本に重ねます。\n例:1789年(フランス革命)のころ、アメリカでは合衆国憲法にもとづいてワシントンが初代大統領に就任し、日本では松平定信が寛政の改革を進めていた。\n例:1840年代、中国ではアヘン戦争、日本では天保の改革、ヨーロッパでは1848年に各地で革命が起きた(フランスの二月革命など)。\n例:1860年代、アメリカでは南北戦争(1861〜65年)、イタリアでは王国の成立(1861年)、日本では幕末の動乱から明治維新(1868年)。\n例:1917年、ロシアでは二月革命と十月革命、アメリカは第一次世界大戦に参戦。\n日本史で知っている年号を「目印」にして、同じころの世界を思いうかべる練習が効果的です。',
        key: '別の地域のできごとは、日本史の年号を目印にして、年表を1本に重ねて並べる。',
        ex: [{ q: 'フランス革命が始まった1789年に最も近い時期に行われた日本の政治はどれ?ア 享保の改革 イ 寛政の改革 ウ 天保の改革', hint: '3つの改革が、それぞれ18世紀前半・後半、19世紀前半のどれかを思い出します。', steps: ['享保の改革は1716年から(18世紀前半)。', '寛政の改革は1787年から(18世紀後半)。', '天保の改革は1841年から(19世紀前半)。', '1789年に最も近いのは、1787年から始まった寛政の改革。'], a: 'イ', check: '寛政の改革は松平定信が田沼の政治を引きしめ直したもので、フランス革命とほぼ同じ時期、と日本史の因果からも確かめられます。' }] }
    ],
    faq: [
      ['フランス革命の細かい年号は、全部覚える必要があるの?', '1789(革命)、1792(共和政)、1793(国王処刑)、1799(ナポレオンのクーデタ)、1804(皇帝)の5つは覚えましょう。\nそのほかは「急進化 → 反動 → 強い指導者」という流れの型に当てはめれば、順番が決められることが多いです。'],
      ['ベルリンの壁は、いつできて、いつなくなったの?', '1961年に東ドイツが築き、1989年11月に開放されました。\n壁ができた理由は、東ドイツから西ベルリンを通って西側へにげる人が多かったからです。壁の開放は、東ヨーロッパの民主化の象徴となり、翌1990年の東西ドイツ統一につながりました。'],
      ['横のつながりの問題は、どうやって練習すればいい?', '日本史の主な年号(1600、1688ごろの元禄、1789ごろの寛政、1840年代の天保、1868、1894、1904、1914、1931、1945など)を目印にした、自分用の「世界と日本の比較年表」をつくるのがおすすめです。\n1つの行に「日本/ヨーロッパ/中国/アメリカ」を並べて書くと、同時代のできごとが一目で分かります。']
    ],
    terms: [['恐怖政治', 'ロベスピエールらが反対派を次々に処刑した政治'], ['総裁政府', '1795年からの、5人の総裁による不安定な政府'], ['ウィーン体制', 'ウィーン会議で生まれた、革命前の秩序にもどそうとする国際体制'], ['封じこめ政策', 'アメリカが共産主義の拡大をおさえるためにとった政策'], ['NATO', '1949年に結成された、アメリカ中心の西側の軍事同盟'], ['キューバ危機', '1962年、ソ連のキューバへのミサイル配備をめぐり、米ソが核戦争の寸前までいった事件'], ['辛亥革命', '1911年に始まり、清をほろぼして中華民国をつくった革命']],
    miss: ['王政廃止(1792年)とルイ16世の処刑(1793年)の順を逆にする。王政をやめたから、元の国王を裁けるようになった、と因果で覚える。', 'ワルシャワ条約機構をNATOと同じ1949年と思う。西ドイツのNATO加盟への対抗で1955年。', '太平天国の乱とアロー戦争を、アヘン戦争より前に置く。アヘン戦争の負担が太平天国の原因、と考える。', 'ベルリンの壁の建設(1961年)と開放(1989年)を混同する。'],
    sum: ['1つの国の流れは、因果の鎖で順番を決める。', 'フランス:革命(1789)→ 共和政(1792)→ 総裁政府(1795)→ 統領政府(1799)→ 皇帝(1804)。', 'ウィーン体制(1815)→ 七月革命(1830)→ 1848年革命 → イタリア(1861)・ドイツ(1871)の統一。', '冷戦:マーシャル・プラン → NATO → 朝鮮戦争 → ワルシャワ条約機構 → キューバ危機 → マルタ会談(1989)。', '別地域は年表を重ね、日本史の年号を目印にする。'],
    next: '世界史の流れがつながったら、「日本史探究(c_h1)」も同じ見方で整理しましょう。横のつながりの目印にする日本史の年号が、より確かになります。'
  };

  // ===== 日本史探究 =====
  L.c_h1 = {
    goal: '日本史の流れを、政治の担い手・土地と税・外交という「テーマ」ごとに通して説明でき、政策を「だれが・なぜ・結果どうなったか」で整理できるようになる。',
    intro: '日本史探究は、中学の歴史をくわしくしたものです。ただ覚える量が多いので、時代ごとに分けて覚えるだけでは、つながりが見えなくなります。そこで、【テーマ史】という見方を使います。たとえば「土地と税のしくみ」を古代から近代まで1本の線でたどると、それぞれの政策がなぜ必要だったのかがよく分かります。',
    pre: '中学で学んだ時代の順番(旧石器 → 縄文 → 弥生 → 古墳 → 飛鳥 → 奈良 → 平安 → 鎌倉 → 室町 → 安土桃山 → 江戸 → 明治 → 大正 → 昭和 → 平成 → 令和)を、まず口で言えるようにしておきましょう。\n国の財政(お金のやりくり)は、昔も今も「税」で支えられています。だから、土地と税のしくみが変わると、政治の担い手も変わることが多いのです。\n【荘園】とは、貴族や寺社などが持っていた私有地のことです。奈良時代の墾田永年私財法をきっかけに広がり、豊臣秀吉の太閤検地で、そのしくみがなくなりました。\n【テーマ史】とは、時代を横切って、1つのテーマ(土地制度・外交・文化など)だけを追いかける見方です。時代ごとの学習を「縦糸」とすると、テーマ史は「横糸」にあたります。',
    secs: [
      { h: '政治の担い手の移り変わり', t: '大王と豪族(古墳)→ 天皇中心の律令国家(飛鳥・奈良)→ 藤原氏の摂関政治(平安中期)→ 上皇の院政(平安後期)→ 平氏政権\n→ 鎌倉幕府(将軍 → 北条氏の執権)→ 室町幕府(将軍と守護大名)→ 戦国大名 → 織豊政権 → 江戸幕府(幕藩体制)\n→ 明治政府(藩閥)→ 政党内閣(大正〜昭和初期)→ 軍部の台頭 → 戦後の民主政治(国民主権)\n大切なのは、「前の担い手がなぜ力を失い、次の担い手がなぜ力をにぎれたのか」を説明できることです。\nたとえば院政は、上皇が天皇の父という立場で政治を行ったものです。藤原氏は天皇の母方の親せき(外戚)として力をもっていたので、父方の上皇が直接政治を動かすことで、藤原氏の力をおさえることができました。\nまた、平氏や鎌倉幕府が力をもてたのは、保元・平治の乱などの争いを武力で決着させた武士の力が、朝廷にとって欠かせなくなったからです。',
        key: '担い手が交代するときは、必ず「前の担い手が力を失った理由」と「次の担い手が力をにぎれた理由」がある。',
        ex: [{ q: '院政によって、藤原氏(摂関家)の力がおさえられたのはなぜ?', hint: '藤原氏と上皇は、それぞれ天皇とどんな関係だったかを比べます。', steps: ['藤原氏は、娘を天皇のきさきにし、天皇の母方の祖父(外戚)として摂政・関白になって力をもっていた。', '後三条天皇は藤原氏を外戚としない天皇で、その子の白河天皇は位をゆずったあと上皇として政治を行った。', '上皇は天皇の父(父方)なので、外戚である藤原氏よりも天皇に近い立場から政治を動かせた。', 'そのため、摂政・関白の地位にあっても、藤原氏は政治の実権をにぎりにくくなった。'], a: '天皇の父である上皇が直接政治を行ったため、天皇の母方の親せき(外戚)として力をふるっていた藤原氏が、実権をにぎれなくなったから。' }] },
      { h: 'テーマ史:土地と税(古代〜中世)', t: '【班田収授法】(律令国家)…戸籍にもとづき口分田を与え、租・調・庸を課す。土地も人も国のもの(公地公民)。\n【三世一身法】(723年)…開墾した土地を3代まで私有できる。期限が来ると返すので、効果はうすかった。\n【墾田永年私財法】(743年)…開墾地の永久私有を認めた。ねらいは開墾の促進。結果、貴族・寺社の私有地(のちの荘園)が広がった。\n【寄進地系荘園】(平安中期以降)…地方の有力者が、国司の重い税をのがれるために、自分の土地を中央の有力な貴族や寺社に寄進(寄付)した。税を納めない【不輸の権】、国の役人を入れない【不入の権】を得る荘園が広がり、国の財政がゆらいだ。\n【延久の荘園整理令】(1069年、後三条天皇)…基準に合わない荘園を整理し、天皇の力を取りもどそうとした。\n鎌倉時代には、荘園や公領に【地頭】が置かれ、年貢の取り立てをめぐって荘園領主と争うようになりました。こうして、1つの土地に何重もの権利が重なる複雑なしくみになっていきます。',
        key: '律令の公地公民が、墾田永年私財法と寄進地系荘園で私有地中心のしくみに変わっていった。',
        ex: [{ q: '平安時代、地方の有力者が自分の土地を、わざわざ中央の貴族や寺社に寄進したのはなぜ?', hint: '寄進すると、どんな「権利」が得られたかを考えます。', steps: ['地方の有力者は、開発した土地に国司から重い税をかけられたり、土地を取り上げられたりするおそれがあった。', '有力な貴族や寺社の名前を借りて土地を寄進すると、その荘園は税を納めない不輸の権や、役人を入れない不入の権を認められることがあった。', '寄進した有力者は、現地の管理者(荘官)として、実際には土地の支配を続けられた。', 'つまり、名目上の持ち主を有力者に変えることで、税をのがれ、土地を守ったのである。'], a: '有力な貴族や寺社の権威を借りて、不輸・不入の権を得て国司の税や干渉をのがれ、現地の管理者として実際の支配を続けるため。' }] },
      { h: 'テーマ史:土地と税(近世〜現代)', t: '【太閤検地】(豊臣秀吉)…全国の土地を同じ基準で調べ、石高で表した。1つの土地の耕作者を1人に決め(【一地一作人】)、その農民に年貢を納める責任を負わせた。こうして、1つの土地に何重もの権利が重なっていた荘園のしくみが最終的に消えた。\n【江戸時代の年貢】…村ごとに年貢を納める(村請制)。年貢は米が中心で、武士の給料も米(石高)で表された。\n【地租改正】(1873年)…地券を発行して土地の所有者を決め、地価の3%を現金で納める。米の豊作・不作に左右されない、税収の安定がねらい。\n【農地改革】(戦後)…政府が地主の土地を買い上げて小作人に売りわたし、自作農をふやした。地主が小作人を支配する農村のしくみがなくなった。\nこのように、土地と税のしくみは、「国のもの → 私有地(荘園)→ 一地一作人 → 近代的な土地所有 → 自作農」と変わってきました。\n変化のたびに、「支配する側が、確実に税を取りたい」というねらいと、「土地を持つ側が、自分の権利を守りたい」という思いがぶつかっていたことが分かります。',
        ex: [{ q: '次の政策を古い順に並べよう。ア 太閤検地 イ 三世一身法 ウ 地租改正 エ 墾田永年私財法', hint: '「期限つきの私有 → 永久の私有 → 荘園の消滅 → 近代の税」の順に考えます。', steps: ['三世一身法(723年)は、開墾地を3代に限って私有させた。', 'それでも開墾が進まず、墾田永年私財法(743年)で永久私有を認めた。', '太閤検地(16世紀末)で荘園のしくみが消え、石高制になった。', '地租改正(1873年)で近代的な税制になった。'], a: 'イ → エ → ア → ウ', check: '「3代まで」で効果がうすかったから「永久に」した、という因果で、イとエの順番が決まります。' }] },
      { h: 'テーマ史:外交の流れ', t: '古代:遣隋使・遣唐使で大陸の制度・文化を学ぶ → 白村江の戦い(663年)で唐・新羅に敗れ、国防と律令国家づくりを急ぐ → 遣唐使の停止(894年)\n中世:日宋貿易(平清盛)→ 元寇(1274・1281年)→ 日明貿易(勘合貿易、足利義満)\n近世:南蛮貿易(ポルトガル・スペイン)→ 朱印船貿易 → 鎖国(4つの窓口)→ 外国船の接近と異国船打払令(1825年)\n近代:開国(1854年・1858年)→ 条約改正(1894年・1911年)→ 日清・日露戦争 → 第一次世界大戦 → 国際連盟脱退(1933年)→ 第二次世界大戦\n現代:サンフランシスコ平和条約(1951年)→ 国連加盟(1956年)→ 日韓基本条約(1965年)→ 日中共同声明(1972年)\n外交は、その時代の国内の政治と結びついています。たとえば鎖国は、キリスト教の禁止と、幕府が貿易の利益と情報を独占するためのものでした。白村江の敗戦は、国内では律令国家づくりを急がせる原因になりました。',
        ex: [{ q: '白村江の戦い(663年)での敗戦は、日本の国内の政治にどんな影響を与えた?', hint: '敗れた相手が、大国の唐だったことに注目します。', steps: ['日本は百済を助けるため朝鮮半島に兵を送ったが、唐と新羅の連合軍に大敗した。', '唐・新羅が日本に攻めてくるおそれが生まれたので、九州北部に水城や山城を築き、防人を置いて守りを固めた。', 'また、大国に対抗できる強い国をつくるため、天皇を中心に全国の人々や土地を直接つかむしくみづくりを急いだ。', 'これが戸籍の作成などを経て、701年の大宝律令による律令国家の完成へとつながった。'], a: '唐・新羅の侵攻に備えて九州北部などの防備を固めるとともに、強い国家をつくるため、天皇中心の律令国家づくりを急ぐきっかけになった。' }] },
      { h: 'テーマ史:文化の担い手', t: '文化も、「だれが担い手だったか」で1本の線にできます。担い手は、その時代に経済力や権力をもっていた人々です。\n【古代】…天皇・貴族・寺院が中心。飛鳥文化(法隆寺)・天平文化(東大寺・正倉院、唐の影響)・国風文化(かな文字、源氏物語)。\n【中世】…武士と僧が加わる。鎌倉文化(金剛力士像、鎌倉仏教)・北山文化(金閣、能)・東山文化(銀閣、書院造、水墨画)。民衆の間にも、狂言やおとぎ草子が広まった。\n【近世】…大名・豪商、そして町人が中心になる。桃山文化(天守閣、茶の湯)・元禄文化(上方の町人、浮世草子・人形浄瑠璃)・化政文化(江戸の町人、浮世絵の多色刷り版画)。\n【近代】…西洋の文化を取り入れた文明開化 → 明治の文学・美術 → 大正期には、新聞・雑誌・ラジオで、多くの人々が楽しむ【大衆文化】が生まれた。\n【現代】…テレビの普及などで、全国の人々が同じ文化を楽しむようになった。\n担い手が、貴族 → 武士・僧 → 町人 → 大衆と、だんだん広がっていくことが、日本の文化史の大きな流れです。' },
      { h: '政策は「だれが・なぜ・結果どうなったか」', t: '入試では、政策の名前よりも、そのねらいと結果が問われます。次の3点を必ずセットにしましょう。\n①【だれが】…人物・政権。時代を特定する手がかりになる。\n②【なぜ】…背景にある問題(財政難、ききん、外国の圧力など)。\n③【結果】…成功したか、どんな反発や新しい問題が生まれたか。\n例:天保の改革(水野忠邦)…なぜ:ききんや一揆、外国船の接近で幕府の危機が深まった。何を:株仲間の解散、倹約令など。結果:反発が強く、2年余りで失敗し、幕府の権威が低下した。\n例:墾田永年私財法(聖武天皇のころ)…なぜ:口分田の不足。何を:開墾地の永久私有を認めた。結果:私有地が広がり、荘園が生まれた。\nこの3点セットのノートをつくると、時代をまたいだ比較問題(「Aの改革とBの改革の共通点は?」など)にも答えやすくなります。',
        key: '政策は「だれが・なぜ・結果どうなったか」の3点セットで覚える。',
        ex: [{ q: '地租改正(1873年)の「なぜ」と「結果」を説明しよう。', hint: '江戸時代の年貢の何が、明治政府にとって困ったのかを考えます。', steps: ['なぜ:江戸時代の年貢は米で、豊作・不作で収入が変わり、明治政府の財政が安定しなかった。', '何を:地券を発行して土地所有者を決め、地価の3%を現金で納めさせた。', '結果1:国の税収は安定した。', '結果2:しかし農民の負担は軽くならず、各地で地租改正反対一揆が起き、1877年に税率は2.5%に引き下げられた。'], a: '税収を安定させるため、地価の3%を土地所有者に現金で納めさせた。税収は安定したが、負担の重さに反対一揆が起き、税率が2.5%に引き下げられた。' }] }
    ],
    faq: [
      ['テーマ史と時代ごとの学習、どちらを先にやればいい?', 'まずは時代ごとの流れ(縦糸)を一通り学び、そのあとでテーマ史(横糸)で整理するのがおすすめです。\nテーマ史は、すでに知っている知識を「つなぎ直す」作業なので、時代の知識がある程度ないと効果が出にくいからです。'],
      ['不輸の権と不入の権は、どうちがうの?', '不輸の権は「税を納めなくてよい」権利、不入の権は「国の役人(検田使など)を荘園に入れなくてよい」権利です。\n「輸」は運ぶ・納めるという意味、「入」は入るという意味だと考えると区別しやすくなります。'],
      ['太閤検地で、なぜ荘園のしくみが消えたの?', '荘園では、1つの土地に、荘園領主・荘官・地頭・耕作者など、何人もの権利が重なっていました。\n太閤検地は、実際に耕している農民1人を検地帳に登録し、その人だけが年貢を納めることにしました(一地一作人)。そのため、間にいた人々の権利がなくなり、荘園のしくみが消えたのです。']
    ],
    terms: [['テーマ史', '土地制度・外交など、1つのテーマで時代を通して見る見方'], ['外戚', '母方の親せき。藤原氏は天皇の外戚として力をもった'], ['寄進地系荘園', '有力者が土地を貴族や寺社に寄進してできた荘園'], ['不輸・不入の権', '税を納めない権利と、国の役人を立ち入らせない権利'], ['一地一作人', '太閤検地で、1つの土地の耕作者を1人に決めたこと'], ['幕藩体制', '将軍(幕府)と大名(藩)が土地と人々を支配するしくみ'], ['大衆文化', '大正期以降、新聞・雑誌・ラジオなどを通じて多くの人々が楽しんだ文化']],
    miss: ['三世一身法と墾田永年私財法の順番・内容を逆にする。「3代まで」で効果がうすかったから「永久に」した、と因果で覚える。', '太閤検地で荘園が「広がった」と思う。荘園のしくみは消えた。', '政策の名前だけ覚えて、ねらいと結果を答えられない。3点セットのノートをつくる。', '院政を藤原氏が行った政治だと思う。院政は上皇の政治で、藤原氏の力をおさえるものだった。'],
    sum: ['政治の担い手の移り変わりを1本の線で言えるようにする。', '土地と税は 班田収授 → 墾田永年私財法 → 荘園 → 太閤検地 → 地租改正 → 農地改革。', '外交は国内の政治と結びつけて理解する。', '文化の担い手は 貴族 → 武士・僧 → 町人 → 大衆 と広がる。', '政策は「だれが・なぜ・結果どうなったか」の3点セット。'],
    next: '次は「入試レベル:日本史の因果関係(hx_jhist)」に進みましょう。ここで整理したテーマを、「背景 → できごと → 結果」の鎖にして、結果から原因をたどる練習をします。'
  };

  L.hx_jhist = {
    goal: '入試レベルの日本史で、できごとを「背景 → できごと → 結果」でつなぎ、結果から原因をたどる問題にも答えられるようになる。',
    intro: '入試の日本史では、「〜の結果として正しいものは?」「〜が起きた背景は?」という問題がたくさん出ます。できごとを1つずつ覚えるのではなく、【前のできごとが原因になって次のできごとが起き、それがまた次の原因になる】という鎖で覚えると、知らない形の問題でも筋道で考えられます。',
    pre: 'この単元は、日本史探究(c_h1)で学んだ時代の流れとテーマ史を知っていることを前提にしています。\n【背景】は長い間たまっていた問題、【きっかけ】は直接の引き金になった事件、【結果】はそのできごとのあとに起きた変化です。\n入試では、「Aの結果として正しいものを選べ」のように前から後ろへたどる問題と、「Bの原因となったできごとを選べ」のように後ろから前へたどる問題の、両方が出ます。\n因果の鎖は、1本の矢印で終わらず、「結果」がまた次の「原因」になってつながっていきます。この「つながり続ける」感覚をつかむことが、この単元のねらいです。',
    secs: [
      { h: '因果をたどる練習の型', t: '①【前に向かってたどる】…「このできごとはなぜ起きたか」→ 背景(長い間の問題)ときっかけ(直接の事件)に分ける。\n②【後ろに向かってたどる】…「このできごとの結果、何が起きたか」→ 直後の変化と、その後の影響。\n③【結果から原因をさがす】…入試では、結果が書かれていて「その原因となったできごと」を選ばせる問題もある。年表を逆向きに読む練習が効く。\nたとえば「田沼意次の失脚」なら、背景=わいろ政治への批判、きっかけ=天明のききんと打ちこわしの広がり、結果=松平定信の寛政の改革、とつながります。\n鎖をつくるときは、矢印の間に「なぜそうなったか」を一言書きこみます。これがそのまま、記述問題の答えの材料になります。',
        key: '因果は「前へ(なぜ)」「後ろへ(結果)」「結果から原因へ」の3方向で練習する。',
        ex: [{ q: '田沼意次が失脚したあとに行われた政治と、それが行われた理由を答えよう。', hint: '田沼の政治のどこが批判されたのかを考え、その反対の方向の政治を思い出します。', steps: ['田沼意次は、株仲間の奨励など商業を利用する政治を行ったが、わいろが広がったと批判された。', 'さらに天明のききんで一揆や打ちこわしが広がり、田沼は失脚した。', 'そのあと老中になった松平定信は、ゆるんだ政治を引きしめ直そうとした。', 'こうして、倹約やききんへの備えを重んじる寛政の改革が行われた。'], a: '松平定信の寛政の改革。田沼の政治でゆるんだ政治と社会を引きしめ直し、ききんで苦しむ社会を立て直すため。' }] },
      { h: '開国が国内に与えた影響', t: '1858年の日米修好通商条約で、翌年から貿易が始まりました。最大の貿易港は横浜、最大の相手国はイギリスでした。\n【生糸・茶が大量に輸出】され、国内で品不足になって物価が上がりました。とくに生糸は輸出の中心で、国内の絹織物業は原料不足に苦しみました。\n【金の流出】…日本では金と銀の交換比率が約1:5、外国では約1:15でした。外国人は銀を日本に持ちこんで金に換え、大量の金が海外に流出しました。\n幕府は、金の量を減らした小判(万延小判)をつくって流出を止めようとしましたが、お金の価値が下がったことで、物価の上昇をさらに強めました。\nこうした生活の苦しさから、外国を追いはらえという【攘夷運動】が強まり、外国人を殺傷する事件も起きました。また、条約を結んだ幕府への批判にもつながっていきました。',
        ex: [{ q: '開国後に攘夷運動が強まったのはなぜ?経済の面から説明しよう。', hint: '「品不足」「金の流出」「小判」の3つがどう物価につながったかを考えます。', steps: ['貿易が始まり、生糸などが大量に輸出されて国内で品不足になった。', '金銀の交換比率のちがいから金が海外に流出し、幕府が質を下げた小判を出したことで物価がさらに上がった。', '人々の生活が苦しくなり、その原因である外国と、条約を結んだ幕府への不満が高まった。'], a: '輸出による品不足や金の流出、質を下げた小判の発行で物価が急に上がり、生活が苦しくなった人々の不満が外国と幕府に向かったから。' }] },
      { h: '明治の改革への反発と政府の対応', t: '【地租改正】(1873年)→ 負担が軽くならないことへの反発から各地で【地租改正反対一揆】→ 政府は1877年に地租を地価の3%から【2.5%】に引き下げた。\n【徴兵令・廃刀令・秩禄処分】で、武士だった士族は、戦う役目、刀を持つ特権、国から受け取る給料(秩禄)をつぎつぎに失いました。\n不満をもつ士族は各地で反乱を起こし、最大の反乱が1877年の【西南戦争】(西郷隆盛)でした。徴兵でつくられた政府軍がこれに勝ち、武力による反乱は終わりました。\n「武力での反抗が無理だと分かった → 言論で戦う方向へ」と、政府への批判は言論による【自由民権運動】が中心になりました。\n自由民権運動は、新聞や演説会を通じて全国に広がり、国会期成同盟が国会の開設を求めました。政府は1881年に国会開設の勅諭を出し、1890年までに国会を開くことを約束しました。\nこれが、1889年の大日本帝国憲法の発布と、1890年の帝国議会の開設につながりました。',
        key: '西南戦争(1877年)で武力の反乱が終わり、政府批判は言論の自由民権運動へ。それが国会開設・憲法制定につながった。',
        ex: [{ q: '1877年に、地租の税率が地価の3%から2.5%に引き下げられた。この結果をもたらした原因となったできごとは何?', hint: '「結果から原因をさがす」問題です。税の負担に反対した人々の動きを考えます。', steps: ['結果は「地租の引き下げ」。政府がわざわざ税収を減らしたのだから、強い反対があったはず。', '地租改正後も、農民の負担は江戸時代とあまり変わらなかった。', 'そのため、各地の農民が地租改正反対一揆を起こした。', '同じころ士族の反乱も続いており、政府は農民と士族が結びつくのをおそれて、税率を下げた。'], a: '地租改正反対一揆(各地の農民による反対運動)。', check: '引き下げた年(1877年)が西南戦争と同じ年であることから、政府が国内の不満を何とかおさえようとしていたことも確かめられます。' }] },
      { h: '戦争・恐慌と国内政治', t: '【日露戦争】(1904〜05年)…国民は増税にたえて戦ったが、ポーツマス条約で賠償金が得られず → 【日比谷焼き打ち事件】。\n【第一次世界大戦】(1914〜18年)…輸出がのびて好景気(大戦景気)→ 物価が上がる → シベリア出兵を見こした米の買い占めで米価が急上昇 → 1918年の【米騒動】→ 寺内内閣が退陣し、【原敬】の本格的な政党内閣が成立。\n【関東大震災】(1923年)…多くの企業が打撃を受け、その後の不景気の原因の一つになった。1927年には銀行の経営不安から金融恐慌が起きた。\n【世界恐慌】(1929年)…1930年に浜口雄幸内閣が行った金解禁(金の輸出を自由にすること)と重なり、日本は【昭和恐慌】におちいった。\nアメリカ向けの生糸の輸出が激減し、まゆの値段が暴落して、農村が特に苦しんだ → 政党や財閥への不満が高まる → 軍部が満州に活路を求め、1931年に満州事変。\nこのように、戦争や恐慌という「外からの衝撃」が、国内の生活を苦しめ、政治の担い手を変えていきました。',
        ex: [{ q: '米騒動(1918年)の背景と、その結果を説明しよう。', hint: '背景(長い問題)・きっかけ(直接の事件)・結果の3つに分けます。', steps: ['背景:第一次世界大戦の好景気で物価が上がっていた。', 'きっかけ:シベリア出兵を見こした米の買い占めで、米の値段が急に上がった。', 'できごと:富山県から始まり、米の安売りを求める騒動が全国に広がった。', '結果:責任をとって内閣が退陣し、原敬による本格的な政党内閣が成立した。'], a: '大戦景気による物価上昇と、シベリア出兵を見こした米の買い占めで米価が急上昇したことから米騒動が全国に広がり、その結果、原敬の本格的な政党内閣が成立した。' }] },
      { h: '古代〜近世の因果をつなぐ', t: '近代だけでなく、古い時代にも入試によく出る因果の鎖があります。\n【白村江の戦い】(663年)→ 唐・新羅の侵攻に備えて九州北部に水城や山城を築き、防人を置く → 全国の戸籍をつくるなど、天皇中心の国づくりを急ぐ → 大宝律令(701年)で律令国家が完成。\n【承久の乱】(1221年)→ 六波羅探題の設置、上皇方の土地に東国の御家人を地頭として置く → 幕府の支配が西日本に広がる → 土地の争いがふえ、御成敗式目(1232年)で裁判の基準を示す。\n【応仁の乱】(1467年)→ 幕府と守護大名の力がおとろえる → 下剋上の風潮 → 戦国大名が分国法で領国を治める。\n【島原・天草一揆】(1637年)→ キリスト教の取りしまりの強化 → ポルトガル船の来航禁止(1639年)→ 鎖国の完成。\nどの鎖も、「1つの事件 → 支配する側の対策 → 新しいしくみ」という形をしています。この形を覚えておくと、ほかの時代にも応用できます。',
        key: '鎖の基本形は「事件 → 支配する側の対策 → 新しいしくみ」。' },
      { h: '戦後の因果をつなぐ', t: '【冷戦の始まり】→ アメリカが占領政策を、民主化中心から経済の立て直し中心に切りかえる → 1950年の朝鮮戦争 → 特需景気で経済が復興、警察予備隊の設置 → 1951年のサンフランシスコ平和条約で独立(同時に日米安全保障条約)。\n【日ソ共同宣言】(1956年)→ 常任理事国ソ連の反対がなくなる → 同年、国際連合に加盟。\n【高度経済成長】→ 公害の深刻化 → 公害反対運動や裁判 → 公害対策基本法(1967年)、環境庁の設置(1971年)。\n【石油危機】(1973年)→ 物価の急上昇と戦後初のマイナス成長 → 高度経済成長の終わり → 省エネルギー技術の開発と安定成長へ。\n【バブル経済の崩壊】(1990年代初め)→ 企業の倒産と銀行の不良債権 → 長い不景気(「失われた10年」ともいわれる)。\n戦後の鎖も、「外からの動き(冷戦・石油危機)」が国内の政治や経済を動かす、という型がくり返し出てきます。',
        ex: [{ q: '冷戦の始まりが、日本の独立の回復を早めたといわれるのはなぜ?', hint: 'アメリカにとって、日本はどんな国になってほしかったかを考えます。', steps: ['冷戦でアメリカとソ連の対立が深まり、1949年には中国で共産党の政府ができ、1950年には朝鮮戦争が始まった。', 'アメリカは、アジアで社会主義の勢力が広がるのをおさえるため、日本を西側の重要な拠点にしたいと考えた。', 'そのためには、占領を続けるより、日本を独立させて経済を立て直し、西側の一員とするほうがよいと判断した。', 'こうして1951年にサンフランシスコ平和条約が結ばれ、同時に日米安全保障条約でアメリカ軍の駐留も続くことになった。'], a: 'アジアで社会主義の勢力が広がる中、アメリカが日本を西側の拠点とするため、早く独立させて経済を立て直させようとしたから。' }] }
    ],
    faq: [
      ['「結果から原因」の問題が苦手。どう練習すればいい?', '年表を下(新しい方)から上へ読み、各できごとに「これはなぜ起きた?」と問いかける練習が効果的です。\nたとえば「原敬内閣の成立」を見たら「米騒動で前の内閣が退陣したから」、「米騒動」を見たら「米の値段が上がったから」と、1つずつさかのぼります。'],
      ['金の流出は、なぜ起きたの?', '日本では金1に対して銀約5、外国では金1に対して銀約15で交換されていました。つまり、日本では金が外国より安かったのです。\n外国人は、外国で銀を用意して日本で金に換え、その金を外国で銀に換えれば、銀を約3倍にふやせました。このため、大量の金が日本から流れ出しました。'],
      ['自由民権運動と大正デモクラシーは、何がちがうの?', '自由民権運動(明治前期)は、国会の開設や憲法の制定を求めた運動です。\n大正デモクラシー(大正期)は、すでにある憲法と議会のもとで、政党内閣や普通選挙など、政治をより民衆の意見にもとづくものにしようとした動きです。「議会をつくる運動」と「議会を民主的に動かす運動」と区別しましょう。']
    ],
    terms: [['攘夷', '外国を追いはらおうとする考え'], ['金の流出', '金銀の交換比率のちがいから、開国後に大量の金が海外へ出たこと'], ['秩禄処分', '1876年、士族などに支給していた給料(秩禄)を打ち切った政策'], ['西南戦争', '1877年、西郷隆盛を中心とする士族の最大の反乱'], ['米騒動', '1918年、米価の急上昇に対して全国に広がった騒動'], ['金解禁', '金の輸出を自由にすること。1930年に実施され、昭和恐慌を深刻にした'], ['昭和恐慌', '世界恐慌と金解禁が重なって起きた、昭和初期の深刻な不景気']],
    miss: ['米騒動の結果を「政党内閣が終わった」と逆に覚える。本格的な政党内閣(原敬)が始まった。', '開国後の物価上昇の原因を「輸入が増えたから」とだけ答える。輸出による品不足と金の流出、質を下げた小判が重要。', '西南戦争の後も士族の武力反乱が続いたと思う。以後は言論による自由民権運動が中心に。', '昭和恐慌の原因を世界恐慌だけと答える。金解禁(1930年)が重なったことも書く。'],
    sum: ['因果は「前へ(なぜ)」「後ろへ(結果)」「結果から原因へ」の3方向で練習する。', '開国 → 品不足・金の流出・物価上昇 → 攘夷運動。', '地租改正反対一揆 → 2.5%に引き下げ。西南戦争 → 言論の自由民権運動 → 国会開設。', '大戦景気 → 米騒動 → 原敬内閣。世界恐慌+金解禁 → 昭和恐慌 → 満州事変。', '冷戦 → 占領政策の転換 → 朝鮮戦争・特需 → 独立回復。'],
    next: '次は「難関:日本史(hd_jsoc)」に進みましょう。数年・数か月ちがいのできごとを、「起点 → 反応 → 決着」の型で並べる練習をします。'
  };

  L.hd_jsoc = {
    goal: '難関大レベルの、数年・数か月ちがいのできごとの並べかえを、因果と政治の流れから正確に判断できるようになる。',
    intro: '難関大の日本史では、「大政奉還と王政復古の大号令、どちらが先?」のように、とても近いできごとの順番が問われます。これは、年号だけでなく「何が起きたから、次に何が起きたのか」を理解しているかを試す問題です。この単元では、入試に出やすい「近いできごとのかたまり」を、因果で並べる練習をします。',
    pre: 'この単元は、日本史の因果関係(hx_jhist)を学んだことを前提にしています。\n入試に出る「近いできごと」は、多くの場合、ある1つのできごとをきっかけに、数か月から数年の間に次々と起きた連続したできごとです。これを「かたまり」とよぶことにします。\nかたまりの中では、【起点】(最初のできごと)→【反応】(それに対するだれかの行動)→【決着】(新しいしくみや結論)の順に並ぶことがほとんどです。\n月まで覚えている必要があるのは、ごく一部です。まずは因果で並べ、それでも決まらないときだけ月の知識を使いましょう。',
    secs: [
      { h: '幕末から明治初めのかたまり', t: '1866年 薩長同盟\n1867年10月 【大政奉還】(徳川慶喜が政権を朝廷に返す)\n1867年12月 【王政復古の大号令】(幕府を廃止し、天皇中心の新政府をつくる宣言)\n1868年1月 鳥羽・伏見の戦い(戊辰戦争の始まり)→ 3月 五箇条の御誓文 → 4月 江戸城の無血開城\n1869年 箱館の五稜郭の戦いで戊辰戦争が終わる/版籍奉還\n1871年 廃藩置県\n因果:慶喜は大政奉還で新政府の中に徳川家の力を残そうとした → 倒幕派はそれを防ぐため王政復古の大号令で慶喜を新政府から外し、官職と領地の返上も求めた → 旧幕府側が反発して戊辰戦争。\n五箇条の御誓文は、戦争が始まったあと、新政府が「これからの政治の方針」を内外に示して、人々の支持を集めようとしたものです。',
        key: '大政奉還(1867.10)→ 王政復古の大号令(1867.12)→ 鳥羽・伏見の戦い(1868.1)→ 五箇条の御誓文(1868.3)。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 鳥羽・伏見の戦い イ 王政復古の大号令 ウ 大政奉還 エ 五箇条の御誓文', hint: '慶喜の行動(起点)→ 倒幕派の反応 → 旧幕府の反発 → 新政府の方針、の順です。', steps: ['まず慶喜が政権を朝廷に返す(大政奉還、1867年10月)。これが起点。', 'それに対し、倒幕派が慶喜をはずした天皇中心の新政府を宣言(王政復古の大号令、1867年12月)。', '新政府の処置に旧幕府側が反発し、戦いになる(鳥羽・伏見の戦い、1868年1月)。', '戦いが続く中で、新政府が政治の方針を示す(五箇条の御誓文、1868年3月)。'], a: 'ウ → イ → ア → エ' }] },
      { h: '満州事変から国際連盟脱退までのかたまり', t: '1931年9月 【満州事変】(柳条湖事件がきっかけ)\n1932年3月 【満州国】の建国宣言\n1932年5月 【五・一五事件】(犬養毅首相が暗殺され、政党内閣がとだえる)\n1932年9月 日満議定書(日本が満州国を承認)\n1932年10月 リットン調査団の報告書が公表される → 1933年2月 国際連盟の総会で、満州国を認めない勧告が可決\n1933年3月 【国際連盟脱退】を通告\n因果:満州国を承認することに慎重だった犬養首相が暗殺される → 次の内閣が満州国を承認(日満議定書)→ 国際連盟はリットン報告書にもとづき満州国を認めない → 日本は連盟を脱退。\n日満議定書(9月)がリットン報告書の公表(10月)より前であることに注意しましょう。日本は、国際連盟の判断が出る前に、承認という既成事実をつくったのです。',
        key: '満州事変 → 満州国 → 五・一五事件 → 日満議定書 → リットン報告書 → 連盟脱退(1933年)。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 国際連盟脱退の通告 イ 五・一五事件 ウ 満州事変 エ 日満議定書', hint: '「承認に慎重な首相がいなくなる → 承認 → 国際的な反発」の順を考えます。', steps: ['出発点は満州事変(1931年)。', '満州国が建国され、その承認に慎重だった犬養首相が五・一五事件(1932年5月)で暗殺される。', '次の内閣が日満議定書(1932年9月)で満州国を承認。', '国際連盟が満州国を認めず、日本は脱退を通告(1933年)。'], a: 'ウ → イ → エ → ア' }] },
      { h: '大正期のかたまり', t: '1912〜13年 第一次護憲運動(藩閥の桂太郎内閣が退陣=大正政変)\n1914年 第一次世界大戦に参戦 → 1915年 中国に二十一か条の要求\n1918年 シベリア出兵を見こした米の買い占め → 米騒動 → 原敬内閣\n1923年 関東大震災\n1924年 第二次護憲運動 → 加藤高明内閣(護憲三派)\n1925年 普通選挙法と治安維持法\n普通選挙法と治安維持法は同じ1925年です。選挙権を広げると社会主義の運動が強まることを政府がおそれ、取りしまりの法律をセットでつくった、という因果で覚えます。\n「護憲運動」が2回あることに注意しましょう。1回目は大正のはじめ(藩閥内閣を倒した)、2回目は大正の終わり(普通選挙法を実現する内閣を生んだ)です。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 米騒動 イ 二十一か条の要求 ウ 普通選挙法の成立 エ 第一次護憲運動', hint: '第一次世界大戦の「前・中・後」で分けます。', steps: ['第一次護憲運動は大正のはじめ(1912〜13年)で、大戦の前。', '二十一か条の要求は、大戦に参戦した翌年(1915年)で、大戦中。', '米騒動は、大戦景気による物価上昇とシベリア出兵を見こした買い占めから起きた(1918年)。', '普通選挙法は、第二次護憲運動で生まれた加藤高明内閣のもとで成立(1925年)。'], a: 'エ → イ → ア → ウ' }] },
      { h: '明治前期のかたまり', t: '1871年 廃藩置県 → 岩倉使節団が欧米へ出発\n1873年 徴兵令・地租改正 → 征韓論をめぐる対立で西郷隆盛・板垣退助らが政府を去る(明治六年の政変)\n1874年 板垣らが【民撰議院設立の建白書】を提出(自由民権運動の始まり)\n1877年 【西南戦争】(西郷隆盛が中心の士族の反乱)\n1881年 【国会開設の勅諭】(10年後の国会開設を約束)→ 自由党の結成\n1885年 内閣制度(初代内閣総理大臣は伊藤博文)→ 1889年 大日本帝国憲法の発布 → 1890年 第1回帝国議会\n因果:政府を去った人々のうち、板垣は言論で(建白書)、西郷は武力で(西南戦争)政府と対立した → 武力の反乱が終わり、言論の運動が全国に広がる → 政府が国会開設を約束 → 内閣・憲法・議会の順に、近代国家のしくみが整う。',
        key: '明治六年の政変(1873)→ 民撰議院設立建白書(1874)→ 西南戦争(1877)→ 国会開設の勅諭(1881)→ 内閣制度(1885)→ 憲法(1889)→ 議会(1890)。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 西南戦争 イ 民撰議院設立の建白書 ウ 国会開設の勅諭 エ 内閣制度の創設', hint: '「政府を去った人々の行動 → 政府の約束 → 約束を実現する準備」の順に考えます。', steps: ['1873年に政府を去った板垣退助らが、国会を開くよう求める建白書を出した(1874年)。', '同じく政府を去った西郷隆盛を中心に、士族が西南戦争を起こした(1877年)。', '武力の反乱が終わり、言論の運動が高まると、政府は国会開設の勅諭で国会を開くことを約束した(1881年)。', '国会と憲法に備えて、政府は内閣制度をつくった(1885年)。'], a: 'イ → ア → ウ → エ' }] },
      { h: '戦後占領期のかたまり', t: '1945年8月 ポツダム宣言を受け入れて降伏 → 10月 GHQが民主化を指示(五大改革指令など)\n1945年12月 選挙法の改正(満20歳以上の男女に選挙権)\n1946年4月 戦後初の総選挙(女性議員が誕生)→ 11月3日 【日本国憲法】の公布\n1947年5月3日 日本国憲法の施行\n1950年6月 【朝鮮戦争】の開始 → 8月 【警察予備隊】の設置\n1951年9月 【サンフランシスコ平和条約】・日米安全保障条約の調印 → 1952年4月 発効(独立の回復)\n因果:憲法を審議した帝国議会の衆議院議員は、新しい選挙法による総選挙で選ばれた → だから「選挙法改正 → 総選挙 → 憲法公布」の順。\n朝鮮戦争で日本にいたアメリカ軍が出動 → 国内の治安のために警察予備隊 → 冷戦の中で日本の独立を急ぐ → 平和条約、という順です。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 日本国憲法の公布 イ 女性に選挙権を認めた選挙法の改正 ウ サンフランシスコ平和条約の調印 エ 警察予備隊の設置', hint: '「憲法を審議した議員はどの選挙で選ばれたか」と「朝鮮戦争との関係」を考えます。', steps: ['選挙法が改正され(1945年12月)、女性も投票した総選挙(1946年4月)が行われた。', 'その選挙で選ばれた議員がいる議会で憲法が審議され、1946年11月3日に公布された。', '朝鮮戦争(1950年6月)でアメリカ軍が出動したため、警察予備隊が設置された(1950年8月)。', '冷戦の中で日本の独立が急がれ、サンフランシスコ平和条約が調印された(1951年9月)。'], a: 'イ → ア → エ → ウ' }] },
      { h: '近いできごとを並べるときの手順', t: '①【起点】をさがす…ほかのできごとの原因になっている最初のできごと(多くは条約・戦争・事件)。\n②【反応】を並べる…起点に対して、だれがどう反応したか(賛成・反対・処罰・反乱)。\n③【決着】を最後に置く…条約の締結、内閣の交代、制度の成立など。\nこの「起点 → 反応 → 決着」の型は、どの時代のかたまりにも使えます。\n注意点:「同じ年」のできごとが2つあるときは、片方がもう片方の原因になっていないかを先に考えます。例:1956年の日ソ共同宣言 → 国連加盟。1925年の普通選挙法と治安維持法(ほぼ同時期で、セットで考える)。\nどうしても判断できないときだけ、月まで覚えている知識にたよりましょう。月まで覚える価値があるのは、この単元で見た幕末・満州事変・戦後占領期などのかたまりです。',
        key: '近いできごとは「起点 → 反応 → 決着」で並べる。月の知識は最後の手段。' }
    ],
    faq: [
      ['大政奉還をしたのに、なぜ戊辰戦争が起きたの?', '慶喜は政権を返しても、最大の大名として新しい政治の中心に残るつもりでした。\nしかし倒幕派は、王政復古の大号令で慶喜を新政府から外し、官職や領地の返上まで求めました。これに旧幕府側が反発し、鳥羽・伏見の戦いが起きたのです。'],
      ['日満議定書とリットン報告書、どちらが先?', '日満議定書(1932年9月)が先で、リットン報告書の公表(1932年10月)があとです。\n日本は、国際連盟の調査結果が出る前に満州国を正式に承認し、「すでに認めた国」という既成事実をつくりました。'],
      ['月まで全部覚えないといけないの?', 'いいえ。ほとんどの問題は、因果の流れで順番が決まります。\n月まで覚えておくと有利なのは、幕末(1867〜68年)、満州事変から連盟脱退(1931〜33年)、戦後占領期(1945〜52年)など、因果だけでは決めにくい部分があるかたまりに限られます。']
    ],
    terms: [['王政復古の大号令', '1867年12月、幕府を廃止し天皇中心の新政府をつくると宣言したもの'], ['戊辰戦争', '1868〜69年、新政府軍と旧幕府側との戦い'], ['明治六年の政変', '1873年、征韓論をめぐる対立で西郷隆盛・板垣退助らが政府を去ったこと'], ['日満議定書', '1932年、日本が満州国を承認した取り決め'], ['リットン調査団', '国際連盟が満州事変の調査のために送った調査団'], ['護憲運動', '藩閥や官僚の政治に反対し、憲法にもとづく政党政治を求めた運動']],
    miss: ['王政復古の大号令を大政奉還より前に置く。慶喜の行動(大政奉還)が起点で、王政復古はそれへの反応。', '五箇条の御誓文を戊辰戦争の前に置く。鳥羽・伏見の戦いのあと(1868年3月)。', '国際連盟脱退を満州国建国と同じ1932年にしてしまう。脱退の通告は1933年。', '日本国憲法の公布を選挙法改正より前に置く。改正後の選挙で選ばれた議会が憲法を審議した。'],
    sum: ['近いできごとは「起点 → 反応 → 決着」で並べる。', '大政奉還(1867.10)→ 王政復古(1867.12)→ 鳥羽・伏見(1868.1)→ 五箇条の御誓文(1868.3)。', '満州事変 → 満州国 → 五・一五事件 → 日満議定書 → 連盟脱退(1933)。', '明治六年の政変 → 建白書 → 西南戦争 → 国会開設の勅諭 → 内閣 → 憲法 → 議会。', '選挙法改正 → 総選挙 → 憲法公布。朝鮮戦争 → 警察予備隊 → 平和条約。'],
    next: '歴史の因果がつかめたら、「公民:現代社会とわたしたち(c_gendai)」に進みましょう。歴史で見た社会の変化が、今の日本の課題にどうつながっているかが分かります。'
  };

  // ===== 中学公民 =====
  L.c_gendai = {
    goal: '現代社会の特色(少子高齢化・グローバル化・情報化)を説明でき、「効率」と「公正」の考え方で、対立を合意にみちびく方法を考えられるようになる。',
    intro: '公民は「今の社会のしくみ」を学ぶ科目です。その入り口として、まず今の日本がどんな社会なのかを見ます。そして、人が集まって暮らせば必ず意見の対立が起きます。そのときに、みんなが納得できる決め方を考える道具が【効率】と【公正】です。これは学級会の話し合いから国の政治まで、同じように使えます。',
    pre: '【割合】は、全体をもとにして、ある部分がどれだけにあたるかを表す数です。割合=部分÷全体 で求め、100をかけると百分率(%)になります。\n【人口】は、ある地域に住む人の数です。人口は、生まれる人と亡くなる人、移り住む人と出ていく人の差で、ふえたり減ったりします。\n戦後の日本は、高度経済成長で豊かになり、医療の進歩で平均寿命がのびました。一方で、1970年代半ばから、生まれる子どもの数は減り続けています。\n公民で学ぶ「社会」は、家族・学校・地域・国・世界など、人が集まってつくる集団のことです。どの集団にも、みんなが気持ちよく暮らすための「きまり」があります。',
    secs: [
      { h: '少子高齢化', t: '【少子化】…生まれる子どもの数が減ること。1人の女性が一生のうちに産む子どもの数の平均を【合計特殊出生率】といいます。およそ2.1を下回り続けると、親の世代より子の世代のほうが少なくなり、人口は減っていきます。日本はこれを大きく下回っています。\n少子化の理由には、結婚する年齢が上がったこと、子育てや教育にかかる費用が大きいこと、仕事と子育ての両立がむずかしいことなどがあります。\n【高齢化】…総人口にしめる65歳以上の人の割合(【高齢化率】)が高まること。医療の進歩などで平均寿命がのびたことが主な理由です。日本の高齢化率は約3割に達しています。\nこの2つが同時に進むと、働く世代が減り、年金や医療などの社会保障を支える人1人あたりの負担が重くなります。\n対策として、保育サービスの充実や育児休業の取りやすさなど子育ての支援、高齢者が元気に働き続けられるしくみづくりなどが進められています。\n家族の形も変わり、夫婦と子ども、または夫婦だけ、親1人と子どもの【核家族】や、1人で暮らす【単独世帯】がふえています。',
        key: '少子化と高齢化が同時に進むと、社会保障を支える働く世代1人あたりの負担が重くなる。',
        ex: [
          { q: 'ある町の人口は2000人で、そのうち65歳以上が500人。高齢化率は何%?', hint: '割合=部分÷全体 です。', steps: ['高齢化率=65歳以上の人口÷総人口×100。高齢化率は「総人口のうち、高齢者がどれだけか」を表す割合だから。', '500÷2000=0.25。', '0.25×100=25%。'], a: '25%', check: '2000人の25%は 2000×0.25=500人で、問題の数と一致します。' },
          { q: '高齢者1人を、働く世代3人で支える社会と、1.5人で支える社会がある。働く世代1人あたりの負担は、あとの社会では前の社会の何倍になる?', hint: '高齢者1人分の負担を、何人で分けるかを考えます。', steps: ['高齢者1人を支える負担を「1」とする。', '3人で支えるとき、1人あたりの負担は 1÷3=1/3。', '1.5人で支えるとき、1人あたりの負担は 1÷1.5=2/3。', '(2/3)÷(1/3)=2。'], a: '2倍', check: '支える人数が半分(3人 → 1.5人)になれば、1人あたりの負担は2倍になる、と言いかえて確かめられます。' }
        ] },
      { h: 'グローバル化', t: '【グローバル化】とは、人・もの・お金・情報が国境をこえて行き来し、世界の一体化が進むことです。交通や通信の発達が、これを後押ししました。\nグローバル化が進むと、各国が得意なもの(安く、上手につくれるもの)を生産して、たがいに交換し合う【国際分業】が進みます。こうすると、それぞれが全部を自分でつくるより、全体として多くのものが手に入ります。\n一方で、国内の工場が人件費の安い海外に移り、国内の働く場が減る(産業の空洞化)心配や、外国産の安い農産物が入って国内の農業がおとろえ、【食料自給率】が下がる心配もあります。\n世界の国々との競争が激しくなる(【国際競争】)ので、企業は新しい技術や品質で勝負する必要があります。\nまた、外国から来た人々がふえ、ちがう文化をもつ人々がたがいを認め合ってともに暮らす【多文化共生】も大切になっています。',
        ex: [{ q: 'A国は自動車づくりが、B国は小麦づくりが得意である。両国がそれぞれ得意なものだけをつくって交換し合うと、どんな利点がある?', hint: '「得意なもの」をつくると、同じ時間や人手でどれだけたくさんつくれるかを考えます。', steps: ['得意なものは、少ない時間・人手・費用で、たくさん・上手につくれる。', 'A国が自動車、B国が小麦に集中すると、両国合わせた生産量は、それぞれが両方をつくるときより多くなる。', 'できたものを交換すれば、両国とも、自動車も小麦も、自分でつくるより多く(または安く)手に入る。', 'このように、得意なものを分担して交換することを国際分業という。'], a: '両国とも得意なものに集中するので全体の生産量がふえ、交換すれば、両方の国が自分だけでつくるより多くの自動車と小麦を手に入れられる(国際分業の利点)。' }] },
      { h: '情報化', t: '【情報化】とは、情報通信技術(【ICT】)が発達し、情報が社会の中で大きな役割をもつようになることです。\nインターネットの普及で、だれでも世界中の情報を手に入れたり、自分から発信したりできるようになりました。買い物や銀行の手続きもインターネットでできるようになり、生活は便利になりました。\n【AI(人工知能)】は、大量のデータから学んで、判断や予測を行う技術です。自動運転や医療の診断など、さまざまな分野で使われ始めています。\n一方で、個人情報の流出、インターネット上の誹謗中傷、うその情報(フェイクニュース)の拡散などの問題もあります。また、情報機器を使える人と使えない人の間の格差(デジタル・デバイド)も課題です。\n情報を正しく選び、活用する力を【情報リテラシー】といいます。発信者はだれか、いつの情報か、ほかの情報源でも確かめられるか、をチェックするくせをつけましょう。\n情報を発信するときは、他人の権利を守り、責任をもって発信する【情報モラル】も大切です。' },
      { h: '社会集団ときまり', t: '人は、家族・学校・地域・会社など、さまざまな【社会集団】の中で暮らしています。人間は1人では生きていけず、集団の中で助け合って暮らす「社会的存在」だといわれます。\nなかでも【家族】は、最も身近な社会集団です。日本国憲法は、家族の生活において、【個人の尊厳と両性の本質的平等】を定めています。\n集団の中では、考え方や利害のちがいから、意見の【対立】が起きることがあります。対立をそのままにすると、集団がまとまらなくなります。\nそこで、話し合いによって、みんなが納得できる【合意】をめざします。合意した内容は、【きまり(ルール)】として守ります。\nきまりには、何をしてよいか、してはいけないか(権利と義務)が書かれています。きまりがあることで、人々はたがいの行動を予測でき、安心して暮らせます。\nきまりは、つくったら終わりではありません。状況が変われば、みんなで見直して変えることもできます。',
        key: '対立 → 話し合い → 合意 → きまり。きまりは、状況に合わせて見直すこともできる。' },
      { h: '対立から合意へ:効率と公正', t: '話し合いで合意をめざすとき、解決策がよいかどうかを、次の2つの考え方で確かめます。\n【効率】…お金・時間・労力・ものなどを、むだなく使えているか。みんなの満足が、より大きくなっているか。\n【公正】…一部の人だけが不利になっていないか。公正には2種類あります。\n・【手続きの公正さ】…関係する全員が話し合いに参加し、意見を言える機会があったか。\n・【機会や結果の公正さ】…立場によって機会や結果が不当に差別されていないか。\n決め方には、全員が賛成するまで話し合う【全会一致】(全員が納得しやすいが、時間がかかり、決まらないこともある)と、【多数決】(早く決まるが、少数意見が反映されにくい)があります。\n多数決をとる前には、少数の人の意見もよく聞き、できるだけ取り入れる【少数意見の尊重】を十分に行うことが大切です。',
        key: '効率=むだがないか。公正=手続き・機会・結果で、一部の人が不利になっていないか。',
        ex: [
          { q: '体育館を使う時間を、部員数に関係なく、すべての部に同じ時間ずつ割り当てた。その結果、人数の少ない部では使われない時間ができた。この決め方は、効率と公正のどちらの面で問題がある?', hint: '「使われない時間」は、何がむだになっているのかを考えます。', steps: ['使われない時間ができている=体育館という資源がむだになっている。', 'むだがないかを見るのは「効率」の考え方。', '全部の部に同じ時間なので、機会の点では一見公正だが、むだが生じている。'], a: '効率の面で問題がある(体育館の時間がむだになっている)。' },
          { q: 'クラスの合唱曲を、学級委員3人だけで話し合って決め、ほかの生徒には結果だけを伝えた。この決め方は、どの点で問題がある?また、どう改めればよい?', hint: '「だれが話し合いに参加できたか」に注目します。', steps: ['決めるときに話し合いに参加できたのは3人だけで、ほかの生徒は意見を言う機会がなかった。', '関係する全員が参加し、意見を言える機会があるかを見るのは「手続きの公正さ」。', 'したがって、手続きの公正さの面で問題がある。', '改め方:クラス全員から希望の曲を集める、話し合いの場を設けるなど、全員が意見を言える機会をつくってから決める。'], a: '手続きの公正さの面で問題がある。クラス全員が意見を出せる機会(アンケートや話し合い)をつくってから決めればよい。' }
        ] },
      { h: '持続可能な社会をめざして', t: '今の世代の豊かさのために、将来の世代の環境や資源を使いつくしてはいけません。将来の世代の必要を満たす力をそこなわずに、今の世代の必要を満たす社会を【持続可能な社会】といいます。\n2015年に国連で採択された【SDGs(持続可能な開発目標)】は、貧困・飢餓・教育・ジェンダー平等・気候変動など【17の目標】を、2030年までに達成することをめざしています。\nSDGsのスローガンは「だれ一人取り残さない」です。発展途上国だけでなく、先進国もふくめたすべての国が取り組む目標です。\n身近な生活の中でも、ごみを減らす(リデュース)、くり返し使う(リユース)、資源として再利用する(リサイクル)の【3R】や、エネルギーを節約するなどの行動が、持続可能な社会につながります。\nこれからの社会をつくるのは、みなさん自身です。社会の課題に関心をもち、話し合いや選挙などを通じて社会に参加すること(【社会参画】)が求められています。' }
    ],
    faq: [
      ['効率と公正は、どちらが大事なの?', 'どちらか一方だけでは、よい解決策になりません。\nたとえば、効率だけを考えて人数の多い部にだけ体育館を使わせると、少ない部は不公正だと感じます。反対に、公正だけを考えて全部に同じ時間を与えると、使われない時間のむだが出ます。両方を満たす案を考えるのが、話し合いの目的です。'],
      ['多数決で決めれば、いつも公正なの?', 'いいえ。多数決は、話し合いを十分にしたうえで、最後に決める方法です。\n少数の人の意見を聞かないまま多数決をとると、手続きの公正さが欠けます。また、多数決で少数の人の基本的な権利をうばうことは許されません。'],
      ['合計特殊出生率が2より少し多くないと、なぜ人口が減るの?', '子どもを産むのは女性だけなので、夫婦2人から子ども2人が生まれて、ようやく親と同じ人数になります。\nさらに、大人になる前に亡くなる子どももいるため、人口を保つには平均で約2.1人が必要とされています。']
    ],
    terms: [['合計特殊出生率', '1人の女性が一生のうちに産む子どもの数の平均'], ['高齢化率', '総人口にしめる65歳以上の人口の割合'], ['グローバル化', '人・もの・お金・情報が国境をこえて行き来し、世界の一体化が進むこと'], ['国際分業', '各国が得意なものを生産し、たがいに交換し合うこと'], ['情報リテラシー', '情報を正しく選び、活用する力'], ['効率と公正', 'むだがないか(効率)と、一部の人が不利になっていないか(公正)'], ['SDGs', '2015年に国連で採択された、2030年までの17の持続可能な開発目標']],
    miss: ['効率と公正を逆に覚える。「効率=むだ」「公正=不公平」と、それぞれが防ぎたいもので覚える。', '多数決なら必ず公正だと思う。少数意見の尊重や、全員が参加できる手続きが必要。', '少子化と高齢化を同じ意味だと思う。子どもが減ること/高齢者の割合が高まること、で別の現象。', 'グローバル化の良い面だけ、または悪い面だけを答える。国際分業の利点と、産業の空洞化などの課題を両方挙げる。'],
    sum: ['現代社会の特色は少子高齢化・グローバル化・情報化。', '少子高齢化で、社会保障を支える世代の負担が重くなる。', 'グローバル化は国際分業を進めるが、産業の空洞化などの課題もある。', '対立を合意にするときは「効率」と「公正」で確かめ、多数決の前に少数意見を尊重する。', '持続可能な社会をめざす国際目標がSDGs(17の目標・2030年まで)。'],
    next: '次は「憲法と政治のしくみ(c_m3)」です。社会のきまりの中で最も大切な「憲法」と、国の政治を動かす国会・内閣・裁判所のしくみを学びます。'
  };

  L.c_m3 = {
    goal: '日本国憲法の原則と基本的人権、国会・内閣・裁判所のしくみと三権分立、選挙と地方自治を、理由とともに説明できるようになる。',
    intro: '国の政治は、国民が選んだ代表者が行います。でも、もし1人や1つの機関に権力が集中したら、国民の自由が守られなくなるかもしれません。そこで、権力を3つに分けてたがいに見張らせる【三権分立】や、国の最高のきまりである【憲法】で権力をしばるしくみがあります。「なぜそういうしくみなのか」を考えながら読むと、用語がすっと入ってきます。',
    pre: '【政治】とは、社会の中の対立を調整し、みんなに関わることを決めて実行することです。国の政治を行う力を【権力】といいます。\n【民主主義】とは、国民が政治のあり方を決める考え方です。国民全員が直接集まるのはむずかしいので、選挙で代表者を選び、代表者が話し合って決める【間接民主制(議会制民主主義)】がとられています。\n【法】にはいろいろな種類があります。国会が定めるのが【法律】、地方公共団体が定めるのが【条例】です。そして、法律より上にある、国の最高のきまりが【憲法】です。\n戦前の大日本帝国憲法では、主権は天皇にあり、国民の権利は法律の範囲内でしか認められませんでした。この反省が、今の日本国憲法の土台になっています。',
    secs: [
      { h: '憲法と日本国憲法の三大原則', t: '憲法は、国民の権利を守るために、国の権力をしばるきまりです。権力をもつ人も憲法に従って政治を行わなければならない、という考え方を【立憲主義】といいます。\n憲法は国の【最高法規】で、憲法に反する法律や命令は効力をもちません。\n日本国憲法は1946年11月3日に公布、1947年5月3日に施行されました。三大原則は【国民主権・基本的人権の尊重・平和主義】です。\n【国民主権】…国の政治のあり方を最終的に決める力が国民にあること。天皇は、日本国と日本国民統合の【象徴】で、政治の権限をもたず、内閣の助言と承認によって、法律の公布や国会の召集などの【国事行為】だけを行います。\n【平和主義】…憲法第9条で、戦争を放棄し、戦力をもたず、交戦権を認めないと定めています。政府は、自衛のための必要最小限度の実力として【自衛隊】をもつことは憲法に反しないと説明しています。また、【日米安全保障条約】にもとづいてアメリカ軍が日本にとどまり、核兵器を「持たず、つくらず、持ちこませず」の【非核三原則】をかかげています。\n憲法改正は、各議院の総議員の【3分の2以上】の賛成で国会が発議し、【国民投票で過半数】の賛成が必要です。ふつうの法律より手続きがきびしいのは、権力をしばる最高のきまりを、簡単に変えられないようにするためです。',
        key: '三大原則は国民主権・基本的人権の尊重・平和主義。憲法改正は「各議院の総議員の3分の2以上で発議 → 国民投票で過半数」。',
        ex: [{ q: '衆議院の総議員が465人のとき、憲法改正の発議には、衆議院で少なくとも何人の賛成が必要?', hint: '「総議員の3分の2以上」です。出席議員ではありません。', steps: ['憲法改正の発議には、各議院の総議員の3分の2以上の賛成が必要。', '465×2/3=310。', '「以上」なので、310人ちょうどでも条件を満たす。', 'さらに参議院でも総議員の3分の2以上の賛成が必要で、そのあと国民投票で過半数の賛成を得て改正される。'], a: '310人', check: '310÷465=0.666…で、ちょうど3分の2になっています。' }] },
      { h: '基本的人権', t: '基本的人権は、人が生まれながらにもっている、だれにもおかされない権利です。日本国憲法は、これを「侵すことのできない永久の権利」として保障しています。\n【平等権】…法の下の平等。性別・人種・信条・社会的身分などで差別されない。\n【自由権】…国から不当に制限されない権利。精神の自由(思想・良心、信教、表現の自由など)、身体の自由(理由なく逮捕されない、拷問されない)、経済活動の自由(職業選択、財産権)。\n【社会権】…人間らしい生活を国に求める権利。「健康で文化的な最低限度の生活」を営む権利(【生存権】、第25条)、教育を受ける権利、勤労の権利、労働者の団結権などの労働基本権。\n【参政権】…政治に参加する権利(選挙権・被選挙権など)。【請求権】…人権を守るための権利(裁判を受ける権利、国家賠償請求権など)。\n社会の変化にともなって、良い環境を求める【環境権】、国などの情報を得る【知る権利】、私生活をみだりに公開されない【プライバシーの権利】、自分の生き方を自分で決める【自己決定権】などの【新しい人権】も主張されています。\n人権は、他の人の人権とぶつかるときなどに、社会全体の利益である【公共の福祉】によって制限されることがあります。また、国民には、子どもに普通教育を受けさせる義務・勤労の義務・納税の義務の【三大義務】があります。',
        key: '自由権は「国から自由になる権利」、社会権は「国に人間らしい生活を求める権利」。' },
      { h: '国会:国の唯一の立法機関', t: '【国会】は、主権者である国民が選んだ議員で構成されるので、【国権の最高機関】で、法律をつくることができる【唯一の立法機関】とされています。\n国会は、衆議院と参議院の【二院制】です。2つの議院で慎重に話し合い、一方の行きすぎをおさえるためです。\n・衆議院:任期4年、解散あり、被選挙権25歳以上。\n・参議院:任期6年(3年ごとに半数を改選)、解散なし、被選挙権30歳以上。\n任期が短く解散もある衆議院のほうが、国民の意見を反映しやすいと考えられ、【衆議院の優越】が認められています。予算は衆議院が先に審議し(予算の先議)、内閣不信任の決議は衆議院だけができます。\n法律案・予算・条約の承認・内閣総理大臣の指名で、両院の議決がちがったときは、衆議院の議決が優先されることがあります。たとえば法律案は、衆議院が出席議員の3分の2以上の多数で再び可決すれば成立します。予算などは、両院協議会を開いても意見が一致しないとき、衆議院の議決が国会の議決になります。\n国会には、毎年1月に召集される【常会】(通常国会)、必要に応じて開かれる【臨時会】、衆議院の総選挙後に開かれる【特別会】などがあります。',
        ex: [{ q: 'ある予算について、衆議院は可決し、参議院は否決した。両院協議会を開いたが、意見が一致しなかった。この予算はどうなる?', hint: '予算は「衆議院の優越」が認められているものの1つです。', steps: ['予算は、衆議院が先に審議する(予算の先議権)。', '両院の議決がちがうときは、両院協議会を開いて調整する。', '両院協議会でも意見が一致しない場合、予算については衆議院の議決が国会の議決になる。', 'したがって、衆議院が可決したので、予算は成立する。'], a: '衆議院の議決が国会の議決となり、予算は成立する。', check: '法律案の場合は、両院協議会ではなく「衆議院の出席議員の3分の2以上で再可決」が必要で、予算とはしくみがちがう点も確かめましょう。' }] },
      { h: '内閣と裁判所', t: '【内閣】(行政)…法律や予算にもとづいて、実際に国の仕事を行うのが行政です。内閣は、内閣総理大臣と国務大臣で構成されます。総理大臣は国会議員の中から国会が指名し、国務大臣は総理大臣が任命します(過半数は国会議員)。\n内閣が国会の信任にもとづいて成り立ち、国会に対して連帯して責任を負うしくみを【議院内閣制】といいます。衆議院で内閣不信任決議が可決されると、内閣は【10日以内に衆議院を解散】しないかぎり、【総辞職】しなければなりません。\n【裁判所】(司法)…争いごとや犯罪を、法にもとづいて裁くのが司法です。最高裁判所と、高等・地方・家庭・簡易の下級裁判所があります。裁判官は、自分の良心に従い、憲法と法律にだけしばられて裁判を行います(【司法権の独立】)。\n1つの事件で3回まで裁判を受けられる【三審制】をとり、まちがった判決を防いでいます。第一審の判決に不服なら【控訴】、第二審の判決に不服なら【上告】します。\n裁判には、お金の貸し借りなど個人の間の争いを扱う【民事裁判】と、犯罪を裁く【刑事裁判】があります。2009年からは、重大な刑事事件の第一審に、国民が裁判官と一緒に参加する【裁判員制度】が始まりました。\nすべての裁判所が、法律などが憲法に違反していないかを判断する【違憲審査権】をもち、最終的に判断する最高裁判所は「憲法の番人」とよばれます。',
        key: '議院内閣制:衆議院が内閣不信任を可決 → 内閣は10日以内に衆議院を解散するか、総辞職する。',
        ex: [
          { q: '衆議院で内閣不信任の決議が可決された。内閣がとれる対応を2つ答えよう。', hint: '議院内閣制では、内閣は何の信任の上に成り立っているかを考えます。', steps: ['議院内閣制では、内閣は国会(衆議院)の信任の上に成り立っている。', '信任を失ったので、内閣はそのまま続けることはできない。', '内閣は、総辞職するか、10日以内に衆議院を解散して、選挙で国民の判断を問う。'], a: '10日以内に衆議院を解散する、または総辞職する。' },
          { q: '地方裁判所で行われた民事裁判の第一審の判決に不服がある。次に、どこの裁判所に何という手続きをする?', hint: '三審制で、第一審から第二審へ進む手続きの名前を思い出します。', steps: ['三審制では、1つの事件で3回まで裁判を受けられる。', '第一審の判決に不服で、上の裁判所に裁判のやり直しを求めることを控訴という。', '地方裁判所の第一審の次は、ふつう高等裁判所が第二審を行う。'], a: '高等裁判所に控訴する。', check: '第二審の判決にも不服なら、最高裁判所に上告する、と次の段階まで言えれば理解できています。' }
        ] },
      { h: '三権分立:なぜ権力を分けるのか', t: '権力が1つに集まると、それが乱用されて国民の自由がおびやかされるおそれがあります。そこで、立法・行政・司法の3つの権力を別々の機関にもたせ、たがいに【抑制と均衡】をはかるのが【三権分立】です。フランスのモンテスキューが「法の精神」で説きました。\n国会 → 内閣:内閣総理大臣の指名、内閣不信任の決議。内閣 → 国会:衆議院の解散、国会の召集の決定。\n国会 → 裁判所:裁判官をやめさせるかを決める【弾劾裁判】。\n内閣 → 裁判所:最高裁判所長官の指名、その他の裁判官の任命。\n裁判所 → 国会・内閣:法律や行政処分が憲法に違反していないかの審査(違憲審査)。\nさらに国民は、【選挙】(国会)、【世論】(内閣)、最高裁判所裁判官の【国民審査】(裁判所)を通じて、三権に関わります。\n矢印を図にかいて、「どの機関が、どの機関に、何をするか」を言えるようにしましょう。',
        key: '三権分立のねらいは、権力の集中を防ぎ、国民の自由を守ること。' },
      { h: '選挙と地方自治', t: '選挙の4原則:一定の年齢以上のすべての国民が投票できる【普通選挙】、1人1票の【平等選挙】、だれに投票したか知られない【秘密選挙】、直接候補者に投票する【直接選挙】。選挙権は満18歳以上です。\n衆議院議員の選挙は、1つの選挙区から1人を選ぶ小選挙区制と、政党の得票数に応じて議席を配分する比例代表制を組み合わせた【小選挙区比例代表並立制】です。選挙区によって有権者の数がちがい、1票の価値に差が出る【一票の格差】が課題になっています。\n地方の政治は、住民が身近な問題に取り組み、民主主義を学べることから「【民主主義の学校】」とよばれます。住民は、首長(知事・市町村長)と地方議員を、それぞれ直接選挙で選びます。\n地方公共団体の財源には、自分で集める地方税のほかに、国から配られる地方交付税交付金や国庫支出金などがあり、自主財源が少ないことが課題です。\n住民には【直接請求権】があります(原則)。\n・条例の制定・改廃、監査の請求…有権者の【50分の1以上】の署名(条例は首長へ、監査は監査委員へ)。\n・議会の解散、首長・議員の解職(リコール)…有権者の【3分の1以上】の署名を選挙管理委員会へ。人の地位をうばう請求なので、より多くの署名が必要です。',
        key: '直接請求:条例・監査は50分の1、解散・解職は3分の1。',
        ex: [{ q: '有権者が9万人の市で、条例の制定を請求したい。何人以上の署名が必要で、どこに請求する?また、市長の解職を請求する場合はどうなる?', hint: '条例は50分の1、解職は3分の1です。', steps: ['条例の制定・改廃の請求は、有権者の50分の1以上の署名が必要。', '90000÷50=1800。請求先は首長(市長)。', '市長の解職(リコール)は、人の地位をうばう重い請求なので、有権者の3分の1以上の署名が必要。', '90000÷3=30000。請求先は選挙管理委員会で、その後、住民投票で過半数の同意があれば解職される。'], a: '条例の制定:1800人以上の署名を集め、市長に請求する。市長の解職:30000人以上の署名を集め、選挙管理委員会に請求する。', check: '1800×50=90000、30000×3=90000 と、かけ算でもとの有権者数にもどることを確かめましょう。' }] }
    ],
    faq: [
      ['自由権と社会権は、何がちがうの?', '自由権は「国に口出しされない権利」です。たとえば、国が勝手に本を発行禁止にしたり、理由なく逮捕したりしてはいけません。\n社会権は「国に、人間らしい生活ができるよう求める権利」です。たとえば、生活に困ったときに生活保護を受けられるのは、生存権があるからです。自由権は国に「しないこと」を求め、社会権は国に「すること」を求める、と考えると区別できます。'],
      ['なぜ衆議院のほうが優越しているの?', '衆議院は任期が4年と短く、解散もあるので、選挙が多く行われます。そのため、そのときどきの国民の意見をより強く反映していると考えられるからです。\n参議院は、任期6年で解散がないので、長い目で落ち着いて審議する役割が期待されています。'],
      ['内閣総理大臣は、なぜ国民が直接選ばないの?', '日本は議院内閣制をとっていて、国民が選んだ国会議員の中から、国会が総理大臣を指名するしくみだからです。\nアメリカのように国民が大統領を選ぶしくみ(大統領制)とはちがいます。日本では、国民は選挙で国会議員を選ぶことを通じて、間接的に総理大臣を選んでいるのです。']
    ],
    terms: [['立憲主義', '憲法で国の権力をしばり、国民の権利を守るという考え方'], ['国民主権', '国の政治のあり方を最終的に決める力が国民にあること'], ['公共の福祉', '社会全体の利益。人権どうしの対立を調整する考え方'], ['衆議院の優越', '予算の先議や内閣不信任決議など、衆議院に強い権限が認められていること'], ['議院内閣制', '内閣が国会の信任にもとづいて成り立ち、国会に対して責任を負うしくみ'], ['違憲審査権', '法律などが憲法に違反していないかを判断する裁判所の権限'], ['三審制', '1つの事件で3回まで裁判を受けられるしくみ'], ['直接請求権', '住民が署名を集めて、条例の制定や首長の解職などを求める権利']],
    miss: ['衆議院と参議院の任期・被選挙権(4年・25歳/6年・30歳)を逆にする。「参議院は長く落ち着いて(6年・30歳)」と役割と結びつける。', '内閣総理大臣を国民が直接選ぶと思う。国会議員の中から国会が指名する。', '条例の請求(50分の1・首長へ)と解職の請求(3分の1・選挙管理委員会へ)を混同する。人の地位をうばう請求ほど署名が多く必要、と理由で覚える。', '憲法改正の発議を「出席議員の3分の2」と思う。各議院の「総議員」の3分の2以上。', '生存権を自由権に入れてしまう。国に生活の保障を求める社会権。'],
    sum: ['憲法は権力をしばる最高法規(立憲主義)。三大原則は国民主権・基本的人権の尊重・平和主義。', '人権は平等権・自由権・社会権・参政権・請求権と新しい人権。公共の福祉で制限されることがある。', '国会=立法(衆議院の優越)、内閣=行政(議院内閣制)、裁判所=司法(三審制・違憲審査)。', '三権分立は抑制と均衡。国民は選挙・世論・国民審査で関わる。', '選挙は4原則・満18歳以上。直接請求は50分の1と3分の1。'],
    next: '次は「暮らしと経済(c_econ)」です。政治のしくみに続いて、価格の決まり方や、銀行・税金のはたらきなど、お金の流れのしくみを学びます。'
  };

  var SUPPLY = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="需要曲線と供給曲線の交点で均衡価格が決まる"><line x1="30" y1="130" x2="210" y2="130" class="ax"/><line x1="30" y1="10" x2="30" y2="130" class="ax"/><line x1="50" y1="25" x2="170" y2="120" class="cv"/><line x1="50" y1="120" x2="170" y2="25" class="cv2"/><line x1="30" y1="72.5" x2="110" y2="72.5" class="dash"/><line x1="110" y1="72.5" x2="110" y2="130" class="dash"/><circle cx="110" cy="72.5" r="4" class="pt"/><text x="34" y="20">価格</text><text x="180" y="145">数量</text><text x="174" y="124">需要</text><text x="174" y="28">供給</text><text x="34" y="68">均衡価格</text></svg>';

  L.c_econ = {
    goal: '需要と供給で価格が決まるしくみを図で説明でき、企業・労働・金融・財政(税金)の基本的なしくみを理解できるようになる。',
    intro: '夏になるとアイスクリームがよく売れ、野菜が豊作だと値段が下がります。これは、買いたい量(需要)と売りたい量(供給)のバランスで価格が動いているからです。経済は、家計(わたしたちの家庭)・企業・政府の3つが、お金とものをやりとりして回っています。そのしくみを1つずつ見ていきましょう。',
    pre: '【グラフの読み方】:横の軸(よこ)と縦の軸(たて)が何を表しているかを最初に確かめます。この単元の需要・供給のグラフでは、横が数量、縦が価格です。「右下がり」の線は、右へ行くほど(数量が多いほど)低くなる線です。\n【割合と%】:10%は0.1、5%は0.05です。100万円の10%は 100万×0.1=10万円です。\n【利子(利息)】:お金を借りた人が、借りたお金(元金)に上乗せして返すお金のことです。元金に対する利子の割合を【金利】といいます。\n品物(パン・服など形のあるもの)を【財】、形のない働き(散髪・授業・運送など)を【サービス】といいます。わたしたちは、財とサービスを買って生活しています。',
    secs: [
      { h: '経済とは:家計・企業・政府のつながり', t: '人々が、財やサービスをつくり(生産)、分け合い、使う(消費)活動を【経済】といいます。\n経済は、3つの主体がお金とものをやりとりして回っています。\n【家計】…わたしたちの家庭。企業や政府で働いて所得を得て、財やサービスを買い(消費)、税金を納める。\n【企業】…財やサービスを生産して売り、利益を得る。家計から労働力を受け取り、賃金をはらう。\n【政府】…家計や企業から税金を集め、道路・学校・警察などの公共サービスや、社会保障を提供する。\nほしいものは無限にあっても、お金や時間、資源には限りがあります(【希少性】)。だから、わたしたちは何を買うかを選択しながら暮らしています。\n消費者は、売り手より商品の知識が少なく、不利になりやすい立場です。そこで、【消費者基本法】や【製造物責任法(PL法)】、訪問販売などの契約を一定期間内なら解除できる【クーリング・オフ】などで、消費者が守られています。' },
      { h: '需要と供給で価格が決まる', t: '【需要】は買いたい量、【供給】は売りたい量です。\nなぜ需要曲線は右下がりなのでしょうか。価格が高いと、買いたい人は減り、安いとふえるからです。反対に、価格が高いと、売りたい企業はもうかるのでふえます。だから【需要曲線は右下がり】、【供給曲線は右上がり】になります。\n2つの曲線が交わる点で、買いたい量と売りたい量がつり合います。このときの価格を【均衡価格】といいます。\n需要が供給より多ければ品不足になって価格は上がり、供給が需要より多ければ売れ残って価格は下がります。こうして価格は均衡価格に近づいていきます。\nこのように、市場で価格が上下して需要と供給が調整されるしくみを【市場メカニズム】といいます。市場で決まる価格を【市場価格】といい、価格は「何がどれだけ求められているか」を知らせる信号の役割を果たしています。',
        key: '需要曲線は右下がり、供給曲線は右上がり。交点が均衡価格。需要>供給なら値上がり、供給>需要なら値下がり。',
        fig: SUPPLY,
        ex: [
          { q: 'ある年、キャベツが大豊作になった。キャベツの価格はどうなる?需要と供給の言葉を使って説明しよう。', hint: '大豊作で変わるのは、需要と供給のどちらかを考えます。', steps: ['大豊作で、市場に出回るキャベツ(売りたい量=供給)がふえる。', '買いたい量(需要)はほとんど変わらない。キャベツを食べる量は急にはふえないから。', '供給が需要を上回るので売れ残りが出て、売るために価格が下がる。'], a: '供給がふえて需要を上回るため、価格は下がる。', check: '反対に不作の年は供給が減って品不足になり、価格が上がる、と逆の場合で確かめましょう。' },
          { q: 'ある商品を、均衡価格より高い価格で売り出した。市場ではどんなことが起き、価格はどう動く?', hint: '図で、均衡価格より上の高さに横線を引き、需要と供給の量を比べます。', steps: ['均衡価格より高い価格では、需要曲線(右下がり)の数量は小さく、供給曲線(右上がり)の数量は大きくなる。', 'つまり、売りたい量(供給)が買いたい量(需要)を上回る。', 'その差の分だけ売れ残りが出る。', '売れ残りを減らすため、売り手は価格を下げる。価格は均衡価格に向かって下がっていく。'], a: '供給が需要を上回って売れ残りが出るため、価格は下がり、均衡価格に近づいていく。' }
        ] },
      { h: '企業のしくみと競争', t: '企業の多くは【株式会社】です。株式会社は、【株式】を発行して多くの人から資金を集めます。株式を買って出資した人を【株主】といいます。\n会社が利益を上げると、その一部が株主に【配当】として分けられます。株主は、会社が倒産しても、出資した額以上の責任は負いません(【有限責任】)。そのため、多くの人が安心して出資できます。\n株主は【株主総会】に出席し、経営の方針や役員の選出などを、持っている株式の数に応じて決めることに参加できます。\n企業は、利益を求めるだけでなく、法律を守り、環境に配慮し、地域社会に貢献するなどの【企業の社会的責任(CSR)】を果たすことも求められています。\n1つの企業が市場を支配する【独占】や、少数の企業が支配する【寡占】の状態では、競争が起きず、価格が不当に高くなるおそれがあります。そのため【独占禁止法】があり、【公正取引委員会】が監視しています。\n電気・ガス・水道・鉄道の運賃などは、生活への影響が大きいので、国や地方公共団体が決定や認可をする【公共料金】になっています。',
        ex: [{ q: 'ある会社の株式を200株持っている。この会社は1株あたり15円の配当を出すことにした。受け取る配当はいくら?また、もしこの会社が倒産したら、株主はいくらまで責任を負う?', hint: '配当=1株あたりの配当×持っている株数。責任については「有限責任」を思い出します。', steps: ['配当は、持っている株式の数に応じて分けられる。', '15円×200株=3000円。', '株主は有限責任なので、会社が倒産しても、会社の借金を代わりにはらう必要はない。', '失うのは、株式を買うために出したお金(出資した額)まで。'], a: '配当は3000円。倒産した場合の責任は、株式を買うために出資した額まで(それ以上の借金を負う必要はない)。' }] },
      { h: '働く人を守るしくみ', t: '企業で働く人(労働者)は、会社(使用者)に比べて弱い立場になりがちです。1人で「給料を上げてほしい」と言っても、聞き入れられにくいからです。\nそこで憲法は、労働者に【団結権】(労働組合をつくる権利)・【団体交渉権】(使用者と話し合う権利)・【団体行動権(争議権)】(ストライキなどをする権利)の【労働三権】を保障しています。\nさらに、働く人を守るために【労働基準法】(労働時間は原則1日8時間・週40時間以内、週1日以上の休日など)、【労働組合法】、【労働関係調整法】の【労働三法】があります。\n近年は、パートやアルバイト、派遣社員などの【非正規雇用】がふえています。非正規雇用は、正社員に比べて賃金が低く、雇用が不安定になりやすいという課題があります。\nまた、長時間労働による健康被害を防ぎ、仕事と家庭や地域の生活を両立させる【ワーク・ライフ・バランス】の実現も求められています。\n男女が平等に働けるように、男女雇用機会均等法や、育児・介護休業法も定められています。',
        key: '労働三権は団結権・団体交渉権・団体行動権。弱い立場の労働者が、団結して使用者と対等に話し合うため。' },
      { h: '金融と日本銀行', t: 'お金に余裕のある人から足りない人へお金を融通することを【金融】といいます。\n銀行が預金を集めて、企業などに貸し出すのが【間接金融】です。銀行は、貸し出しの金利を預金の金利より高くし、その差を利益にしています。企業が株式や社債を発行して、直接お金を集めるのが【直接金融】です。\n日本の中央銀行である【日本銀行】には3つの役割があります。①紙幣(日本銀行券)を発行する【発券銀行】、②一般の銀行に貸し出しなどをする【銀行の銀行】、③政府のお金を出し入れする【政府の銀行】。\n日本銀行は、景気や物価を安定させるために【金融政策】を行います。中心は、銀行との間で国債などを売り買いする【公開市場操作】です。\n・不景気のとき:日銀が銀行から国債などを【買う】→ 銀行の手元の資金がふえる → 金利が下がり、企業がお金を借りやすくなる → 投資がふえて景気が回復に向かう。\n・景気が過熱して物価が上がりすぎるとき:日銀が国債などを【売る】→ 銀行の資金が減る → 金利が上がる → 借りにくくなり、景気がおさえられる。',
        key: '不景気には日銀が国債を「買う」(お金をふやす)、景気の過熱には「売る」(お金を減らす)。',
        ex: [{ q: '不景気で企業の投資が減っている。日本銀行は公開市場操作でどうする?その結果どうなるかも順に説明しよう。', hint: '世の中のお金を「ふやしたい」のか「減らしたい」のかを先に決めます。', steps: ['不景気なので、世の中に出回るお金をふやして、企業がお金を借りやすくしたい。', 'そこで日本銀行は、銀行から国債などを買い、代金を銀行にはらう。', '銀行の手元の資金がふえるので、銀行は貸し出しをふやそうとし、金利が下がる。', '金利が下がると企業はお金を借りて工場や設備に投資しやすくなり、景気が回復に向かう。'], a: '日本銀行は銀行から国債などを買う。銀行の資金がふえて金利が下がり、企業がお金を借りて投資しやすくなるので、景気が回復に向かう。' }] },
      { h: '財政と税金', t: '国や地方公共団体が、税金などを集めて、公共サービスなどに使う経済活動を【財政】といいます。収入を【歳入】、支出を【歳出】といいます。\n国の歳出でいちばん大きいのは、年金・医療・介護などの【社会保障関係費】です。次いで、借金の返済や利子の支払いにあてる【国債費】、地方を支援する【地方交付税交付金】などが大きな割合をしめます。\n税金でたりない分は【国債】(国の借金)を発行して補っています。国債の残高は年々ふえており、将来の世代に負担を残すことが課題です。\n税金には、納める人と負担する人が同じ【直接税】(所得税・法人税など)と、ちがう【間接税】(消費税など)があります。消費税は、店が納めますが、実際に負担しているのは買い物をした消費者です。\n所得税は、所得が多いほど高い税率をかける【累進課税】で、所得の差を小さくするはたらきがあります。一方、消費税は所得に関係なく同じ税率なので、所得の低い人ほど所得にしめる税の負担の割合が高くなる【逆進性】があります。\n政府も、不景気のときは公共事業をふやしたり減税したりし、好景気のときはその逆を行って、景気を安定させます(【財政政策】)。',
        key: '所得税は累進課税で格差を小さくし、消費税には逆進性がある。',
        ex: [{ q: '所得200万円の人と1000万円の人が、それぞれ1年間に100万円分の買い物をした。消費税10%の負担は、所得に対して何%ずつになる?', hint: 'まず2人の消費税の額を出し、それぞれの所得でわります。', steps: ['2人とも消費税は 100万円×10%=10万円。消費税は買った額に同じ税率でかかるから。', '所得200万円の人:10万÷200万=0.05 → 5%。', '所得1000万円の人:10万÷1000万=0.01 → 1%。', '所得の低い人ほど負担の割合が高い=逆進性。'], a: '所得200万円の人は5%、1000万円の人は1%(所得の低い人ほど負担の割合が高い)。', check: '200万円の5%は10万円、1000万円の1%も10万円で、どちらも同じ消費税額になっています。' }] },
      { h: '景気の変動とインフレ・デフレ', t: '経済は、生産や消費が活発な【好景気(好況)】と、にぶい【不景気(不況)】を、波のようにくり返します。これを【景気変動】といいます。\n好景気のときは、ものがよく売れ、企業の生産がふえ、賃金も上がりやすくなります。一方で、需要が供給を上回り、物価が上がり続ける【インフレーション(インフレ)】が起きやすくなります。インフレになると、同じお金で買えるものが減り、お金の価値が下がります。\n不景気のときは、ものが売れず、企業の生産が減り、失業者がふえます。物価が下がり続ける【デフレーション(デフレ)】が起きることもあります。デフレでは、ものが安くなっても企業の利益が減って賃金が下がり、さらにものが売れなくなる悪い循環(デフレスパイラル)におちいることがあります。\nそこで、日本銀行の【金融政策】と、政府の【財政政策】で、景気の波を小さくし、物価を安定させようとしています。\n不景気のとき:日銀は国債などを買ってお金をふやし、政府は公共事業をふやしたり減税したりする。\n好景気で物価が上がりすぎるとき:日銀は国債などを売ってお金を減らし、政府は公共事業を減らしたり増税したりする。' }
    ],
    faq: [
      ['需要曲線が右下がりになるのはなぜ?', '価格が下がるほど、「この値段なら買いたい」と思う人や、買う量がふえるからです。\nたとえば、1個300円のりんごは1個しか買わない人でも、1個100円なら3個買うかもしれません。だから、価格が低い(グラフの下の方)ほど、需要の量が多く(右の方)なり、線は右下がりになります。'],
      ['日銀が国債を「買う」と、なぜお金がふえるの?', '日銀が銀行から国債を買うと、その代金を銀行にはらいます。銀行の手元には、国債の代わりにお金がふえます。\n銀行は、ふえたお金を企業などに貸し出そうとするので、世の中に出回るお金がふえ、金利も下がりやすくなります。'],
      ['直接税と間接税は、どうやって見分けるの?', '「税金を役所に納める人」と「実際に負担する人」が同じかどうかで見分けます。\n所得税は、自分の所得から自分が負担して納めるので直接税です。消費税は、店が税務署に納めますが、負担しているのは代金をはらった客なので間接税です。']
    ],
    terms: [['均衡価格', '需要量と供給量がつり合ったときの価格'], ['市場メカニズム', '価格の上下によって需要と供給が調整されるしくみ'], ['独占禁止法', '企業の独占を防ぎ、公正な競争を守る法律。公正取引委員会が運用'], ['労働三権', '団結権・団体交渉権・団体行動権'], ['公開市場操作', '日本銀行が国債などを売買して、出回るお金の量を調整すること'], ['累進課税', '所得が多いほど高い税率をかけるしくみ'], ['逆進性', '所得の低い人ほど、所得にしめる税負担の割合が高くなる性質'], ['インフレーション', '物価が上がり続け、お金の価値が下がること']],
    miss: ['需要曲線と供給曲線の向き(右下がり・右上がり)を逆にする。「高いと買う人は減る=需要は右下がり」と理由で覚える。', '不景気のときに日銀が国債を「売る」と思う。お金をふやしたいので「買う」。', '消費税を直接税だと思う。納める人(店)と負担する人(消費者)がちがう間接税。', '株主は会社の借金を全部はらわなければならないと思う。株主は有限責任で、出資した額までしか責任を負わない。'],
    sum: ['経済は家計・企業・政府の3つの主体で回る。', '需要>供給なら価格は上がり、供給>需要なら下がる。交点が均衡価格。', '株式会社の株主は配当を受け取り、有限責任を負う。労働者は労働三権・労働三法で守られる。', '日本銀行は発券銀行・銀行の銀行・政府の銀行。不景気には国債を買う。', '所得税は累進課税、消費税には逆進性。政府は財政政策で景気を安定させる。'],
    next: '次は「国際社会の課題(c_kokusai)」です。国内の政治と経済に続いて、国と国とのつながりや、国連・地球環境問題などを学びます。'
  };

  L.c_kokusai = {
    goal: '国家と国際社会のしくみ、国際連合(とくに安全保障理事会と拒否権)のはたらき、地球環境問題や国際協力の流れを説明できるようになる。',
    intro: '世界には190をこえる国があり、それぞれが自分の国のことを自分で決める権利(主権)をもっています。でも、紛争や地球温暖化のように、1つの国だけでは解決できない問題がたくさんあります。そこで国々は、国際連合などの場で話し合い、ルールをつくって協力しています。そのしくみと、うまくいかない理由の両方を知ることが大切です。',
    pre: '国の範囲である【領域】は、領土・領海(海岸線から12海里)・領空からなります。海岸線から200海里までの【排他的経済水域】では、沿岸の国が資源を利用できます(地理で学んだ内容です)。\n第二次世界大戦のあと、二度と大きな戦争を起こさないために、1945年に【国際連合】がつくられました。日本は1956年に加盟しました(歴史で学んだ内容です)。\n冷戦の時代には、アメリカとソ連が対立し、国連の話し合いもたびたび止まりました。1989年に冷戦が終わったあとは、地域紛争やテロ、地球環境問題など、新しい課題が目立つようになりました。\n国内の政治では、多数決などでみんなに関わることを決め、法律で守らせることができます。しかし国際社会には、すべての国を従わせる「世界政府」はありません。この点が、国際問題の解決をむずかしくしています。',
    secs: [
      { h: '国家と国際社会のルール', t: '国家は、【主権・領域・国民】の3つの要素からなります。どれか1つでも欠けると、独立した国家とはいえません。\n【主権】とは、ほかの国から支配や干渉を受けず、自分の国のことを自分で決める権利です。主権をもつ国家どうしは、国の大小に関係なく対等です(主権平等)。また、ほかの国の国内の問題に口出ししないことが原則です(内政不干渉)。\n国どうしのルールを【国際法】といい、国どうしが文書で約束した【条約】と、長い間の慣行がルールになった【国際慣習法】があります。公海はどの国の船も自由に航行できる、という「公海自由の原則」などが国際慣習法の例です。\n国どうしの争いを裁く機関として、オランダのハーグに【国際司法裁判所】があります。ただし、裁判を始めるには、原則として争っている両方の国の同意が必要です。国際社会には、国内の警察や裁判所のように、強制的に従わせる力をもつ機関がないからです。\n国旗と国歌は、その国の象徴です。たがいの国旗・国歌を尊重することは、国際的な礼儀とされています。',
        key: '国家の三要素は主権・領域・国民。国際司法裁判所の裁判には、原則として両方の国の同意が必要。',
        ex: [
          { q: 'ある地域には多くの人が住み、はっきりした範囲もあるが、ほかの国に支配されていて、自分たちのことを自分たちで決められない。国家の三要素のうち、何が欠けている?', hint: '「自分たちのことを自分たちで決める権利」を何というかを考えます。', steps: ['国家の三要素は、主権・領域・国民。', '多くの人が住んでいる → 国民はいる。', 'はっきりした範囲がある → 領域はある。', 'ほかの国に支配され、自分たちのことを決められない → ほかの国から干渉を受けず自分で決める権利(主権)がない。'], a: '主権', check: '三要素のうち、残りの2つ(国民・領域)が文中にあることを確かめると、欠けているのが主権だと分かります。' },
          { q: 'A国が、領土をめぐる争いについてB国を国際司法裁判所に訴えた。しかし、B国は裁判に応じることに同意しなかった。裁判はどうなる?', hint: '国際司法裁判所の裁判を始めるための条件を思い出します。', steps: ['国際司法裁判所の裁判は、原則として争っている両方の国の同意があって初めて始まる。', 'B国が同意していないので、この条件を満たしていない。', '国際社会には、国を強制的に裁判に従わせる機関がない。'], a: '原則として、裁判は開かれない(B国の同意がないため)。' }
        ] },
      { h: '国際連合のしくみ', t: '【国際連合(国連)】は、第二次世界大戦の反省から1945年に発足しました。本部はアメリカのニューヨークで、現在190をこえる国が加盟しています。\n【総会】…すべての加盟国が参加し、国の大小に関係なく1国1票で議決します。\n【安全保障理事会(安保理)】…世界の平和と安全の維持に主な責任をもちます。アメリカ・イギリス・フランス・ロシア・中国の5つの【常任理事国】と、任期2年の10の非常任理事国の、15か国で構成されます。\n安保理の重要な議題(実質事項)は9か国以上の賛成で決まりますが、常任理事国が1か国でも反対すると決議できません。これを【拒否権】といいます。大国の協力なしには平和を守れない、という考えからできたしくみです。\nしかし、大国が反対する決議は成立しないので、大国どうしが対立すると、安保理が動けなくなるという問題があります。冷戦の時代や、大国が関わる紛争で、この問題がくり返し起きてきました。\nほかにも、教育・科学・文化の【UNESCO(ユネスコ)】、保健の【WHO(世界保健機関)】、子どもを支援する【UNICEF(ユニセフ)】、難民を保護する【UNHCR(国連難民高等弁務官事務所)】などの機関が活動しています。',
        key: '安保理は常任理事国5か国+非常任理事国10か国。実質事項は9か国以上の賛成が必要で、常任理事国には拒否権がある。',
        ex: [{ q: '安保理で、ある決議案の採決をしたところ、15か国中12か国が賛成し、3か国が反対した。反対した3か国のうち1か国はフランスだった。この決議案は成立する?', hint: '「9か国以上の賛成」と「拒否権」の2つの条件を順に確かめます。', steps: ['実質事項は、15か国中9か国以上の賛成が必要 → 12か国なので条件は満たしている。', 'ただし、常任理事国が1か国でも反対すると成立しない(拒否権)。', 'フランスは常任理事国なので、その反対は拒否権の行使になる。'], a: '成立しない(常任理事国のフランスが反対し、拒否権が行使されたため)。', check: 'もし反対した3か国がすべて非常任理事国なら、12か国の賛成で成立する、と条件を入れかえて確かめましょう。' }] },
      { h: '世界の紛争と難民', t: '冷戦が終わったあと、国どうしの大きな戦争より、1つの国の中や近い地域で起きる【地域紛争】が目立つようになりました。民族や宗教のちがい、資源をめぐる争いなどが原因です。\nまた、特定の国家ではない集団が、政治的な目的のために暴力で人々をおびやかす【テロリズム(テロ)】も、国際社会の大きな問題です。2001年には、アメリカで同時多発テロが起きました。\n紛争や迫害からのがれるため、住んでいた国をはなれた人々を【難民】といいます。国連のUNHCRが、難民の保護や生活の支援を行っています。\n紛争が起きた地域では、国連が停戦の監視や選挙の支援などを行う【PKO(平和維持活動)】を行います。日本は1992年にPKO協力法を定め、自衛隊をPKOに派遣するようになりました。\n紛争を防ぐには、武力で解決するのではなく、話し合いや経済の支援によって、貧困や差別など紛争の原因をなくしていくことが大切です。' },
      { h: '地域統合と南北問題', t: '近い国どうしが経済などで協力を深める【地域統合】が進んでいます。協力すると、関税をなくして貿易をしやすくしたり、大国に対抗する力をもったりできるからです。\nヨーロッパの【EU(ヨーロッパ連合)】は、多くの国で共通通貨ユーロを使い、人やものが国境をこえて自由に移動できます。東南アジアの【ASEAN(東南アジア諸国連合)】、アジア・太平洋地域の【APEC(アジア太平洋経済協力)】などもあります。また、特定の国どうしで関税をなくす協定(FTA・EPA)や、TPPのような広い地域の協定も結ばれています。\n先進国(多くは北半球)と発展途上国(多くは南側)の経済格差の問題を【南北問題】といいます。\nさらに、発展途上国の中でも、資源の豊富な国や工業化に成功した国と、そうでない国との格差が広がっています(【南南問題】)。\n日本は、発展途上国に資金や技術を提供する【ODA(政府開発援助)】を行い、【JICA(国際協力機構)】の青年海外協力隊なども活動しています。政府ではない民間の団体【NGO(非政府組織)】も、国際協力で大きな役割を果たしています。\n発展途上国の生産者が正当な収入を得られるよう、適正な価格で商品を取り引きする【フェアトレード】も広がっています。',
        ex: [{ q: '次の問題は、南北問題と南南問題のどちらにあたる?「アフリカのある国は、ほとんど工業化が進まず貧しいままだが、同じ発展途上国の中でも、石油の豊富な国や工業化に成功したアジアの国は豊かになり、その差が広がっている。」', hint: '格差が「どの国とどの国の間」で起きているかを確かめます。', steps: ['南北問題は、先進国と発展途上国の間の格差。', '南南問題は、発展途上国どうしの間の格差。', 'この文では、アフリカの貧しい国と、石油の豊富な国・工業化したアジアの国(どちらも発展途上国に分類されてきた国)の間の差が問題になっている。'], a: '南南問題(発展途上国どうしの格差だから)' }] },
      { h: '地球環境問題', t: '地球温暖化・酸性雨・砂漠化・熱帯林の減少・オゾン層の破壊などの地球環境問題は、国境をこえて広がるので、国際的な協力が必要です。\n【地球温暖化】は、石油や石炭などを燃やして出る二酸化炭素などの【温室効果ガス】がふえ、地球の気温が上がる現象です。海面の上昇や、異常気象の増加などの影響が心配されています。\n1992年、ブラジルのリオデジャネイロで【国連環境開発会議(地球サミット)】が開かれ、気候変動枠組条約などが結ばれました。\n1997年の【京都議定書】では、【先進国】に温室効果ガスの削減を義務づけました。しかし、排出量がふえていた発展途上国に削減義務がないことや、大量に排出する国の不参加などが課題でした。\n2015年の【パリ協定】では、発展途上国をふくむ【すべての参加国】が、自分で削減目標を立てて取り組むことになりました。産業革命前からの気温上昇を2度より十分低くおさえ、1.5度におさえる努力をすることが目標です。\n先進国は「これまで大量に排出してきたのは先進国だ」と言われ、発展途上国は「これから経済を発展させたい」と主張します。立場のちがいをこえて合意をつくることが、環境問題のむずかしさです。',
        key: '京都議定書(1997年)は先進国だけに削減義務。パリ協定(2015年)はすべての参加国が目標を立てて取り組む。',
        ex: [{ q: '京都議定書とパリ協定のいちばん大きなちがいは何?', hint: '「だれが」削減に取り組むことになったかを比べます。', steps: ['京都議定書(1997年):温室効果ガスの削減を義務づけられたのは先進国だけ。', 'パリ協定(2015年):発展途上国をふくむすべての参加国が、それぞれ削減目標を立てて取り組む。', 'ちがいは「だれが取り組むか」。発展途上国の排出がふえてきたので、すべての国の参加が必要になった。'], a: '京都議定書は先進国にだけ削減を義務づけたが、パリ協定は発展途上国をふくむすべての参加国が削減目標を立てて取り組むこと。' }] },
      { h: '資源・エネルギーと平和への取り組み', t: '石油・石炭・天然ガスなどの【化石燃料】は、燃やすと温室効果ガスを出し、いつかはなくなる限りある資源です。\nそこで、太陽光・風力・地熱・バイオマスなど、くり返し使えて温室効果ガスをほとんど出さない【再生可能エネルギー】の利用が進められています。ただし、天候によって発電量が変わる、費用がかかるなどの課題もあります。\n日本はエネルギー資源のほとんどを輸入にたより、発電は火力が中心です。原子力発電は、2011年の東日本大震災で福島第一原子力発電所の事故が起きてから、安全性をめぐって議論が続いています。\n平和の面では、核兵器をもつ国がふえないようにする【核拡散防止条約(NPT)】や、核兵器の開発・保有・使用などを全面的に禁止する【核兵器禁止条約】(2017年採択)があります。\n日本は唯一の戦争被爆国として、【非核三原則】(持たず・つくらず・持ちこませず)をかかげ、核兵器のない世界をめざしています。ただし、日本は核兵器禁止条約には参加していません。\n貧困・教育・保健などの問題を解決して、人々一人ひとりの生命と生活を守ることを【人間の安全保障】といい、日本の国際協力の柱の一つになっています。' }
    ],
    faq: [
      ['なぜ常任理事国だけ拒否権をもっているの?', '第二次世界大戦の主な戦勝国である5か国が協力しなければ、世界の平和は守れない、という考えからです。\n大国が反対する決議を無理に通しても実行できない、という現実的な理由もあります。ただし、そのために大国どうしが対立すると何も決まらない、という問題が生まれています。'],
      ['国際連盟と国際連合は、何がちがうの?', '国際連盟(1920年発足)は、アメリカが参加せず、決議は全会一致が原則で、侵略した国に対して経済制裁しかできませんでした。そのため第二次世界大戦を防げませんでした。\n国際連合は、大国がすべて参加し、安保理の多数決(拒否権つき)で決め、軍事的な措置もとれるようにして、連盟の弱点を改めました。'],
      ['ODAとNGOは、どうちがうの?', 'ODA(政府開発援助)は、政府が行う援助で、税金が使われます。道路や発電所の建設、技術者の派遣など、大きな規模の援助が中心です。\nNGO(非政府組織)は、政府ではない民間の団体で、寄付などで活動します。現地の人々に寄りそった、きめ細かい支援を得意としています。']
    ],
    terms: [['主権', 'ほかの国から支配や干渉を受けず、自分の国のことを決める権利'], ['国際法', '条約と国際慣習法からなる、国どうしのルール'], ['安全保障理事会', '国連で平和と安全の維持に主な責任をもつ機関。15か国で構成'], ['拒否権', '常任理事国が1か国でも反対すると、重要な決議ができない権限'], ['PKO', '国連の平和維持活動。紛争地域での停戦監視など'], ['南北問題', '先進国と発展途上国の経済格差の問題'], ['パリ協定', '2015年採択。すべての参加国が温室効果ガス削減に取り組む枠組み'], ['再生可能エネルギー', '太陽光・風力など、くり返し使えて温室効果ガスをほとんど出さないエネルギー']],
    miss: ['常任理事国に日本やドイツをふくめてしまう。米・英・仏・露・中の5か国で、第二次世界大戦の主な戦勝国。', '9か国以上が賛成すれば必ず決議できると思う。常任理事国の拒否権がある。', '京都議定書で発展途上国にも削減義務があったと思う。先進国のみ。', '南北問題と南南問題を混同する。「北と南」=先進国と途上国、「南と南」=途上国どうし、と文字で覚える。'],
    sum: ['国家は主権・領域・国民の3要素。国際法は条約と国際慣習法。', '国連の安保理は常任理事国5か国+非常任理事国10か国。常任理事国には拒否権。', '冷戦後は地域紛争・テロ・難民が課題。国連はPKOで平和を支える。', '地域統合(EU・ASEANなど)と、南北問題・南南問題。日本はODAで協力。', '温暖化対策は京都議定書(1997・先進国のみ)からパリ協定(2015・すべての国)へ。'],
    next: '高校に進んだら、「公共・政治経済(c_h3)」で、ここで学んだ政治・経済・国際社会のしくみを、為替や金融政策など、より具体的な数字と場面で深めましょう。'
  };

  // ===== 公共・政治経済 =====
  L.c_h3 = {
    goal: '民主政治の原理、契約と消費者の権利、市場の働きと限界、為替相場(円高・円安)、金融政策と財政・社会保障のしくみを、具体的な数字や場面で説明できるようになる。',
    intro: '「公共」は、18歳で成年になるみなさんが、主権者・消費者・働く人として社会に参加するための科目です。ニュースでよく聞く「円安で物価が上がる」「日銀が金利を上げる」なども、しくみが分かれば自分の生活とのつながりが見えてきます。混乱しやすいところは、必ず具体的な数字で確かめながら読みましょう。',
    pre: '中学の公民で学んだことを確認しましょう。日本国憲法の三大原則は【国民主権・基本的人権の尊重・平和主義】で、国の権力は立法(国会)・行政(内閣)・司法(裁判所)の【三権】に分けられています。\n経済では、価格は【需要と供給】で決まり、需要が多ければ上がり、供給が多ければ下がります。\n【日本銀行】は日本の中央銀行で、発券銀行・銀行の銀行・政府の銀行という3つの役割をもち、国債などの売買で世の中のお金の量を調整します。\n税金には、所得が多いほど税率が高い【累進課税】の所得税や、だれでも同じ税率の消費税などがあります。この単元では、これらをもう一段くわしく、数字を使って理解します。',
    secs: [
      { h: '民主政治の原理と法の支配', t: '【社会契約説】…国家は、人々が自分の生命や自由などの権利を守るために、たがいに契約(合意)してつくったものだ、という考え方です。国王の権力は神から授けられたとする王権神授説に対抗して生まれました。\n【ロック】は、政府が人々の権利をおかすなら、人々は政府に抵抗し、政府をつくりかえることができる(【抵抗権】)と説き、アメリカ独立宣言などに影響を与えました。【ルソー】は、人々が直接政治に参加する【人民主権】を説き、フランス革命に影響を与えました。\n【法の支配】…権力者もふくめ、すべての人が、人権を守るための正しい法に従わなければならないという考え方です。権力者が思うままに支配する「人の支配」と対立します。イギリスで発達しました。\n【権力分立】…モンテスキューが説いた三権分立。権力を分けてたがいに抑制させ、人権を守ります。\nこれらの考え方の土台の上に、日本国憲法の国民主権・基本的人権の尊重・平和主義が成り立っています。\n民主政治では、多数決で決めますが、多数の意見でも少数の人の基本的人権をうばうことはできません。憲法で権力をしばる【立憲主義】が、そのための歯止めになっています。',
        key: '法の支配=権力者も正しい法に従う。人の支配(権力者の思うまま)と対立する。' },
      { h: '契約と消費者の権利', t: '【契約】は、たがいの合意(意思表示の一致)で成立します。売買・アルバイト・アパートを借りることなども契約です。口約束でも、原則として契約は成立します。成立した契約は、守る義務があり、一方的にやめることはできません。\n2022年4月から【成年年齢が18歳】に引き下げられました。成年になると、親の同意なしで、携帯電話やクレジットカードの契約ができます。そのかわり、未成年者であることを理由にした契約の取り消し(未成年者取消権)ができなくなります。\n消費者は、売り手に比べて情報や交渉力が少ないので、法律で守られています。\n・【クーリング・オフ】…訪問販売や電話勧誘販売などで契約した場合、契約書面を受け取った日から8日以内なら、理由を問わず契約を解除できる(マルチ商法などは20日以内)。不意打ちのような勧誘で、冷静に考える時間がなかった人を守るための制度なので、店に自分で行って買った場合や通信販売は対象外。\n・【製造物責任法(PL法)】…製品の欠陥で被害を受けた場合、製造者に過失がなくても損害賠償を求められる。\n・【消費者契約法】…うその説明や、帰らせてもらえないなどの不当な勧誘で結んだ契約を取り消せる。\n困ったときは、消費生活センター(消費者ホットライン「188」)に相談できます。',
        key: '18歳から成年。訪問販売などは書面を受け取ってから8日以内ならクーリング・オフできる。店で自分から買った場合は対象外。',
        ex: [{ q: '18歳の高校生が、自宅に来た訪問販売員から教材を買う契約をし、契約書面を受け取った。5日後に解約したくなった。どうすればよい?', hint: '「18歳」と「訪問販売」の2つの条件をそれぞれ確かめます。', steps: ['18歳は成年なので、「未成年だから」という理由での取り消しはできない。', 'しかし訪問販売なので、クーリング・オフの対象になる。', '書面を受け取った日から8日以内(今は5日後)なので、まだ期間内。', 'クーリング・オフは書面(はがきなど)または電磁的記録(メールなど)で通知する。'], a: 'クーリング・オフの期間(8日以内)なので、書面やメールなどで通知すれば、無条件で契約を解除できる。', check: 'もし自分で店に行って買った場合なら、クーリング・オフは使えない、と条件を変えて確かめましょう。' }] },
      { h: '市場の働きと「市場の失敗」', t: '市場では、価格が上下することで、需要と供給が調整されます(市場メカニズム)。多くの場合、これでものがむだなく配分されます。\nしかし、市場にまかせるだけでは、うまくいかない場合があります。これを【市場の失敗】といいます。\n①【独占・寡占】…売り手が1社や少数しかいないと、競争が起きず、価格が高くなりやすい。→ 独占禁止法で競争を守る。\n②【外部不経済】…ある経済活動が、取り引きに関係のない人に損害を与えること。例:工場の排煙による公害。工場は被害の費用をはらわないので、市場にまかせると、公害を出す生産が多くなりすぎる。→ 規制や課税で対応する。\n③【公共財】…道路・警察・消防のように、お金をはらわない人も利用でき、みんなで同時に使えるもの。お金を取りにくいので、企業は十分に供給しない。→ 政府が税金で供給する。\n④【情報の非対称性】…売り手と買い手で持っている情報に差があると、買い手が不利になる。例:中古車の欠陥を売り手だけが知っている。→ 表示の義務づけや消費者保護の法律で対応する。\nこうした市場の失敗を補うことが、政府の重要な役割です。',
        key: '市場の失敗(独占・外部不経済・公共財・情報の非対称性)を補うのが、政府の役割。',
        ex: [{ q: 'ある工場が、川に排水を流しながら製品を安くつくっている。下流の漁師は魚がとれなくなったが、工場は何もはらっていない。これは市場の失敗のどれにあたり、政府はどう対応できる?', hint: '取り引きに関係のない人が損害を受けている点に注目します。', steps: ['工場と製品の買い手の間の取り引きに、下流の漁師は関係していない。', 'それなのに漁師は損害を受けている。これは外部不経済にあたる。', '工場は被害の費用をはらわないので、製品が安くつくれ、市場にまかせると生産が多くなりすぎる。', '政府は、排水の規制をしたり、汚染に税をかけたりして、工場に被害の費用を考えさせることができる。'], a: '外部不経済。政府は、排水の規制や汚染への課税などで、工場が被害の費用を負担するようにして対応できる。' }] },
      { h: '為替相場:円高と円安', t: '円と外国のお金を交換するときの比率を【為替相場(為替レート)】といいます。\n【円高】…円の価値が上がること。1ドル=100円 → 1ドル=80円 のように、【少ない円で1ドルと交換できる】ようになる。\n【円安】…円の価値が下がること。1ドル=100円 → 1ドル=120円 のように、1ドルを手に入れるのにより多くの円が必要になる。\n「数字が小さくなるのに円高」と混乱しやすいので、必ず「1ドルを買うのに何円必要か」で考えましょう。必要な円が少なくてすむ=円が強い=円高です。\n円高の影響:輸入品が安くなる → 輸入企業や海外旅行をする人に有利。日本製品が海外で値上がりする → 輸出企業には不利。\n円安の影響:その逆。輸出企業には有利だが、輸入品(エネルギー・食料など)が値上がりし、国内の物価を押し上げる。\n為替相場は、円を買いたい人が多ければ円高、円を売りたい人が多ければ円安に動きます。たとえば、日本の金利が外国より低いと、金利の高い外国のお金で預けようとして円を売る人がふえ、円安になりやすくなります。',
        key: '円高=少ない円で1ドルと交換できる。輸入に有利、輸出に不利。円安はその逆。',
        ex: [
          { q: '1ドル=100円から1ドル=120円になった。アメリカで10ドルの商品を日本に輸入すると、日本での価格(円)はどう変わる?これは円高・円安のどちら?', hint: '「10ドルを手に入れるのに何円必要か」を計算します。', steps: ['1ドル=100円のとき:10ドル×100円=1000円。', '1ドル=120円のとき:10ドル×120円=1200円。', '同じ10ドルの商品が、200円高くなる。', '1ドルを買うのにより多くの円が必要になった=円の価値が下がった=円安。'], a: '1000円から1200円に値上がりする。円安(輸入品が高くなる)。', check: '1200÷120=10ドル、1000÷100=10ドル と、ドルにもどすと同じ値段になることを確かめましょう。' },
          { q: '1ドル=100円から1ドル=80円になった。日本の会社が国内で100万円の製品をアメリカに輸出するとき、アメリカでの価格(ドル)はどう変わる?', hint: '円の値段をドルに直すには、1ドルあたりの円でわります。', steps: ['1ドル=100円のとき:100万÷100=1万ドル。', '1ドル=80円のとき:100万÷80=1万2500ドル。', 'アメリカでの価格が2500ドル上がり、売れにくくなる。', '少ない円で1ドルと交換できるようになった=円高。'], a: '1万ドルから1万2500ドルに値上がりする(円高で輸出に不利になる)。', check: '1万2500ドル×80円=100万円 で、もとの円の価格にもどります。' }
        ] },
      { h: '金融政策', t: '【日本銀行】は、物価の安定を目的に【金融政策】を行います。物価が安定しないと、人々は安心してお金を使ったり、企業が計画を立てたりできないからです。\n中心となる手段は、国債などを売買して、世の中に出回るお金の量や金利を調整する【公開市場操作】です。日本銀行は、銀行どうしが短期間お金を貸し借りするときの金利(政策金利)を目標にして、操作を行います。\n不景気やデフレ(物価が下がり続けること)のときは、国債などを買ってお金をふやし、金利を下げる【金融緩和】を行います。\n景気が過熱しインフレ(物価が上がり続けること)のときは、国債などを売ってお金を減らし、金利を上げる【金融引き締め】を行います。\n日本では長くデフレが続いたため、日本銀行は金利をとても低くし、大量に国債を買う大規模な金融緩和を続けてきました。\n金利が上がると、預金の利子がふえる一方で、住宅ローンなどでお金を借りている人や企業の負担がふえます。金融政策は、生活のいろいろな場面に影響するのです。' },
      { h: '財政の機能と課題', t: '【財政】には3つの機能があります。\n①【資源配分】…道路や警察など、市場にまかせると十分に供給されないもの(公共財)を、税金で提供する。\n②【所得の再分配】…累進課税で所得の多い人から多く税を集め、社会保障で所得の少ない人を支えて、所得の差を小さくする。\n③【景気の安定化】…不景気のときは公共事業をふやしたり減税したりし、好景気のときは公共事業を減らしたり増税したりして、景気の波を小さくする。\n日本の財政は、歳出が税収を大きく上回り、その差を【国債】の発行で補っています。国債の残高は1000兆円をこえる規模になっています。\n国債が多くなると、返済や利子の支払い(国債費)がふえて、ほかの政策に使えるお金が減ります(財政の硬直化)。また、将来の世代に負担を先送りすることにもなります。\n税収を確保するため、消費税の税率は引き上げられてきました。消費税は景気に左右されにくく安定した財源になる一方、逆進性があるため、食料品などの税率を低くする軽減税率がとられています。',
        key: '財政の3機能:資源配分・所得の再分配・景気の安定化。' },
      { h: '社会保障:4つの柱', t: '【社会保障】は、憲法第25条の生存権(健康で文化的な最低限度の生活を営む権利)を実現するしくみです。日本の社会保障には、4つの柱があります。\n①【社会保険】…加入者が保険料を出し合い、病気・老後・失業・けが・介護などに備える。医療保険・年金保険・雇用保険・労災保険・介護保険の5つ。介護保険は40歳以上が加入する。\n②【公的扶助】…生活に困っている人に、国が生活費などを支給する。中心は【生活保護】で、費用は税金でまかなわれる。\n③【社会福祉】…高齢者・障がい者・子ども・ひとり親家庭など、支援が必要な人々に、施設やサービスを提供する。\n④【公衆衛生】…感染症の予防、上下水道の整備、健康診断など、国民全体の健康を守る。\n少子高齢化が進むと、年金や医療・介護の費用がふえる一方、保険料や税金を納める働く世代は減ります。どのように財源を確保し、だれがどれだけ負担するかが、大きな課題になっています。\n社会保障をどこまで手厚くするかは、「高い負担で手厚い保障」か「低い負担で最低限の保障」か、という選択でもあります。主権者として、この選択に関わることが求められています。',
        ex: [{ q: '景気が悪く、物価が下がり続けている。日本銀行と政府がとる政策の例を1つずつ答えよう。', hint: '日本銀行は「お金の量」、政府は「税金と公共事業」で景気に働きかけます。', steps: ['日本銀行:世の中に出回るお金をふやしたい → 銀行から国債などを買う(金融緩和)。', 'その結果、金利が下がり、企業がお金を借りて投資しやすくなる。', '政府:世の中の需要をふやしたい → 公共事業をふやす、または減税する(財政政策)。', '減税すれば、家計の手元に残るお金がふえ、消費がふえやすくなる。'], a: '日本銀行は国債などを買って金融緩和を行い、政府は公共事業をふやしたり減税したりする。' }] }
    ],
    faq: [
      ['円高と円安、結局どちらがいいの?', 'どちらにも得をする人と損をする人がいるので、一概にはいえません。\n円高は、輸入品が安くなり海外旅行もしやすくなりますが、輸出企業の売り上げが減ります。円安は、輸出企業はもうかりますが、エネルギーや食料の輸入品が値上がりし、生活費が上がります。急に大きく動くと、企業が計画を立てにくくなるのが一番の問題です。'],
      ['クーリング・オフは、通信販売でも使えるの?', '通信販売(ネットショッピングなど)は、クーリング・オフの対象外です。自分で広告を見て、考える時間をもって申しこんだと考えられるからです。\nただし、多くの通信販売では、店が独自に返品のルールを決めているので、買う前に必ず確認しましょう。'],
      ['社会保険と公的扶助は、何がちがうの?', '社会保険は、前もって保険料を出し合い、困ったときに受け取るしくみです(保険料が中心)。\n公的扶助(生活保護)は、保険料をはらっていなくても、生活に困ったときに国が税金で最低限の生活を保障するしくみです。「備えて出し合う」か「困ったときに税金で支える」かで区別しましょう。']
    ],
    terms: [['法の支配', '権力者もふくめ、すべての人が正しい法に従うという考え方'], ['クーリング・オフ', '訪問販売などの契約を、一定期間内なら無条件で解除できる制度'], ['外部不経済', 'ある経済活動が、取り引きに関係のない人に損害を与えること'], ['円高', '円の価値が上がること。1ドル=100円 → 80円など'], ['金融緩和', '日本銀行が国債などを買い、出回るお金をふやして金利を下げる政策'], ['所得の再分配', '累進課税や社会保障で、所得の格差を小さくする財政の機能'], ['社会保険', '加入者が保険料を出し合い、病気・老後・失業などに備える制度'], ['公的扶助', '生活に困っている人に、国が税金で最低限の生活を保障する制度(生活保護)']],
    miss: ['1ドル=100円 → 80円を、数字が減ったから「円安」と答える。少ない円で1ドルを買えるので円高。', '円高が輸出企業に有利だと思う。海外での価格が上がるので不利。', 'クーリング・オフが、店で自分で買った商品や通信販売にも使えると思う。訪問販売や電話勧誘販売などが対象。', '社会保険と公的扶助を混同する。保険料を出し合うのが社会保険、税金で生活を保障するのが公的扶助(生活保護)。'],
    sum: ['法の支配・社会契約説・権力分立が民主政治の土台。', '成年年齢は18歳。訪問販売などは8日以内ならクーリング・オフ。', '市場の失敗(独占・外部不経済・公共財・情報の非対称性)は政府が補う。', '円高=少ない円で1ドル。輸入に有利、輸出に不利。不景気には日銀が金融緩和、政府は公共事業・減税。', '財政の3機能と、社会保障の4本柱:社会保険・公的扶助・社会福祉・公衆衛生。'],
    next: '社会科の全体をふり返るなら、歴史の「入試レベル:日本史の因果関係(hx_jhist)」の戦後の部分を読み直しましょう。高度経済成長や石油危機、バブル崩壊が、今の財政や社会保障の課題にどうつながっているかが見えてきます。'
  };
})(WPS.LESSONS);
